export const questions = [{"year":110,"nth":1,"num":1,"stem":"依據現行精神衛生法，基於對精神病人的保護，經專科醫師診斷或鑑定，屬嚴重病人者，應置保護人一人。專科醫師應開具診斷證明書交付保護人，此保護人應考量嚴重病人利益。依條文敘述保護人可為：①監護人 ②法定代理人 ③同居人 ④配偶 ⑤父母 ⑥家屬 ⑦心理師","options":["①③④⑤⑦","①②③⑤⑥","①②④⑤⑥","②③④⑥⑦"],"answer":"C","correction":"","chapter":"A","extension":false,"context":null,"id":"110-1-1","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":2,"stem":"當病人服用下列何種藥物時，護理師需教導病人有關體重增加之副作用？","options":["Alprazolam（Xanax）","Propranolol（Inderal）","Olanzapine（Zyprexa）","Venlafaxine（Efexor）"],"answer":"C","correction":"","chapter":"E","extension":false,"context":null,"id":"110-1-2","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":3,"stem":"黃先生，55 歲，被診斷為思覺失調症，與案母同住，服藥不規則，須由案母提醒他吃藥。一個月前， 案母因病過世，黃先生認為鄰居透過社區的 LINE 群組說他的壞話，因此作勢要攻擊鄰居。黃先生最可能有以下何種症狀？","options":["關係妄想（delusion of reference）","誇大妄想（delusion of grandeur）","虛無妄想（nihilistic delusion）","嫉妒妄想（delusion of jealousy）"],"answer":"A","correction":"","chapter":"C","extension":false,"context":null,"id":"110-1-3","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":4,"stem":"有關兒童精神疾病的敘述，下列何者正確？","options":["語言障礙症（language disorders）常在上小學後被發現","輕度智能不足（mild intellectual disability）常在幼稚園時被發現","精神疾病的病徵與兒童的年齡、發展階段沒有關係","侵擾行為、衝動控制及行為規範障礙症（disruptive, impulse control and conduct disorder）是和同儕互動中被發現"],"answer":"D","correction":"","chapter":"O","extension":false,"context":null,"id":"110-1-4","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":5,"stem":"在生物化學研究中，憂鬱症病人最可能缺乏那些神經傳導物質？","options":["多巴胺（dopamine）和甲狀腺素（thyroxine）","γ-胺基丁酸（γ-aminobutyric acid; GABA）和乙醯膽鹼（acetylcholine）","皮質醇（cortisol）和腎上腺素（epinephrine）","血清素（serotonin）和正腎上腺素（norepinephrine）"],"answer":"D","correction":"","chapter":"C","extension":false,"context":null,"id":"110-1-5","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":6,"stem":"對有聽幻覺（auditoryhallucination）、被害妄想（delusion of persecution）的病人進行溝通時，下列回應何者較適當？","options":["這裡除了我和你，並沒有其他人在說話","你說有人要害你，其實這是你的想像","你說有人害你，可是你還活得好好的","你這是幻聽、妄想的精神症狀，藥物可以改善"],"answer":"A","correction":"","chapter":"D","extension":false,"context":null,"id":"110-1-6","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":7,"stem":"對憂鬱症的病人進行「人際關係心理治療」，下列敘述何者較適當？","options":["進行人際關係心理治療時，不需合併藥物治療","認為憂鬱症病人常見的問題是角色轉換困難、人際糾紛","人際關係心理治療者主要對憂鬱症病人進行錯誤認知的分析","治療過程中著重分析憂鬱症病人早期的生活事件"],"answer":"B","correction":"","chapter":"F","extension":false,"context":null,"id":"110-1-7","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":8,"stem":"病人服用抗精神病藥物，有關錐體外徑副作用（extrapyramidal symptoms; EPS）之敘述，下列何者正確？","options":["會有體溫升高至 41℃以上，與肌肉僵硬","出現斜頸、牙關緊閉和舌頭收縮，稱之為遲發性不自主運動","出現坐立不安、來回走動或原地踏步是出現靜坐不能（akathisia）的現象","出現鼓嘴、不斷眨眼和做鬼臉，是屬於急性肌肉緊張異常（acute dystonia）的現象"],"answer":"C","correction":"","chapter":"E","extension":false,"context":null,"id":"110-1-8","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":9,"stem":"環境治療應用於急性住院病房之敘述，下列何項較適當？","options":["提高環境刺激，以照護躁症病人感官增加之需求","不論那種情境使用身體約束及保護室隔離，都不符合環境治療原則","多種感官刺激的環境不適合失智症個案的照護","運用環境治療設計的原則於「住院生活作息表」及「生活討論會」"],"answer":"D","correction":"","chapter":"F","extension":false,"context":null,"id":"110-1-9","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":10,"stem":"當罹患思覺失調症病人不斷敘述他的妄想內容時，下列何項護理措施較適當？","options":["引導病人談與妄想內容有關的情緒與感受","告訴病人不要胡思亂想，症狀就會慢慢不見","強烈質疑病人的妄想內容，讓病人感到自我矛盾與錯亂","儘量不要跟病人討論以免加重病情"],"answer":"A","correction":"","chapter":"H","extension":false,"context":null,"id":"110-1-10","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":11,"stem":"廖先生診斷為躁症，入院後常只吃一口飯，就四處去找病友，說要監督別人有無浪費食物，下列何項護理措施較適當？","options":["為病人準備容易攜帶的食物，例如：三明治讓病人可以在行動中進食","為了讓病人好好吃完一頓飯，需安排與其他病人一起在餐廳用餐","因為病人不容易專心，讓他每天只吃一頓就好","用靜脈注射營養品來補充熱量，平時隨便他愛吃多少都沒關係"],"answer":"A","correction":"","chapter":"I","extension":false,"context":null,"id":"110-1-11","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":12,"stem":"躁症發作（manic episode）的典型臨床特徵，下列何者較適當？","options":["情緒低落，低自尊","精力旺盛，愛管閒事","自殺意念","易有穩固的親密關係"],"answer":"B","correction":"","chapter":"I","extension":false,"context":null,"id":"110-1-12","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":13,"stem":"王先生，在家因覺得有人要害他、跟蹤他而不敢睡覺，故由父親帶來住院，住院後仍覺得周遭的人不懷好意，護理師提供之照護措施，下列何者正確？①同理並接受病人感受 ②主動積極接觸關懷病人 ③評估妄想對病人生活干擾的程度 ④不要與病人爭辯妄想的真實性","options":["①②③","①②④","①③④","②③④"],"answer":"C","correction":"","chapter":"H","extension":false,"context":null,"id":"110-1-13","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":14,"stem":"有關妄想症（delusional disorder）的敘述，下列何者正確？","options":["出現至少持續兩週的妄想","人格異常是妄想症的危險因子之一","導因是因為物質使用或身體病況的生理效應","行為明顯的奇特或怪異"],"answer":"B","correction":"","chapter":"H","extension":false,"context":null,"id":"110-1-14","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":15,"stem":"牛先生，最近被診斷為憂鬱症，醫師開立服用 sertraline（Zoloft®）藥物治療，有關 Zoloft 之敘述，下列何者正確？①選擇性血清素回收抑制劑（SSRIs） ②血清素－正腎上腺素回收抑制劑（SNRIs） ③一般持續服用 2 週以上才有療效出現 ④服藥會有嗜睡、噁心嘔吐等副作用","options":["①②③","①②④","①③④","②③④"],"answer":"C","correction":"","chapter":"E","extension":false,"context":null,"id":"110-1-15","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":16,"stem":"王小姐診斷為妄想症（delusional disorder），認為自己的伙食被下毒，而拒絕食用，下列護理措施何者最適切？","options":["宜安排固定的護理師照顧，培養信任感","扶著病人的手協助餵食","保證醫院食物沒毒，請病人不必多想","護理師直接食用以證明食物沒有毒"],"answer":"A","correction":"","chapter":"H","extension":false,"context":null,"id":"110-1-16","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":17,"stem":"鬱症發作（depressive episode）的典型臨床特徵，下列何者較適當？","options":["意念飛躍","自我價值感低","怕獨處而活動多","無睡眠障礙"],"answer":"B","correction":"","chapter":"I","extension":false,"context":null,"id":"110-1-17","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":18,"stem":"王小姐被診斷為憂鬱症，她最常使用的防衛機轉，下列敘述何者正確？","options":["外射（projection）","內射（introjection）","否認（denial）","合理化（rationalization）"],"answer":"B","correction":"","chapter":"C","extension":false,"context":null,"id":"110-1-18","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":19,"stem":"有關社交焦慮症（social anxiety disorders）之敘述，下列何者較適當？","options":["病人會反覆的出現突發性的害怕失控或即將發瘋的感受","因病人對任何的社交情境均會感受到焦慮，故病人的焦慮型態為漂浮型焦慮","病人會因自覺身處於被觀察的社交情境而引發焦慮","對於合併有肥胖症的病人而言，社交焦慮症引發的恐懼、焦慮或逃避行為與肥胖症有關"],"answer":"C","correction":"","chapter":"J","extension":false,"context":null,"id":"110-1-19","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":20,"stem":"病人因反覆出現強迫性思考及持續洗手的行為，而入院治療，下列敘述何者較適當？","options":["病人的強迫性思考內容常為無意義的","護理目標以直接中止病人的洗手症狀為最優先考量","洗手行為是病人藉此內射出其內在強迫性思考的手段","須評估病人自我傷害的可能性，必要時可戴手套洗手"],"answer":"D","correction":"","chapter":"J","extension":false,"context":null,"id":"110-1-20","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":21,"stem":"有關創傷後壓力症（post-traumatic stress disorder; PTSD）病人的治療處置，下列何者較適當？","options":["若採用藥物治療，治療重點為以鋰鹽來緩解病人情緒症狀","若採用精神分析治療，治療重點為採用家庭系統學說來說明家庭間病態的溝通","若採用行為治療，治療重點為以洪水法協助病人逐步控制侵入性的創傷事件影像","若採用認知治療，治療重點為引導病人修正對創傷事件起因與結果的扭曲認知"],"answer":"D","correction":"","chapter":"J","extension":false,"context":null,"id":"110-1-21","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":22,"stem":"張小姐被診斷為做作型人格障礙症（histrionic personalitydisorder），護理師應事先了解病人的特性， 才能客觀的與病人建立治療性關係，下列何者是張小姐較可能出現的行為？①利用自己身體外觀來吸引他人注意 ②展現快速轉變和膚淺表現的情緒 ③衝動、易怒、具攻擊性 ④常以不適當的性挑逗與他人交往","options":["①②③","②③④","①③④","①②④"],"answer":"D","correction":"","chapter":"N","extension":false,"context":null,"id":"110-1-22","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":23,"stem":"照顧罹患身體症狀及相關障礙症的病人，須特別評估隨著症狀表現而來的附帶收獲（secondarygain）， 下列何項描述較適當？","options":["附帶收獲是指表現出身體症狀便可以直接避免面對心理衝突或壓力","應儘量不要太關注病人的身體症狀，以避免不當的增強附帶收獲","以抗精神病（antipsychotics）藥物進行催眠會談，在過程中給予暗示及建議","鼓勵病人持續關注身體症狀，以關注病人的身體症狀為主要護理措施"],"answer":"B","correction":"","chapter":"K","extension":false,"context":null,"id":"110-1-23","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":24,"stem":"護理師在精神科急性病房照顧王老先生期間，王老先生常表示她就像是自己的女兒一樣，並以「女兒」稱呼護理師。對此狀況之解釋，下列敘述何者較適當？","options":["病人對護理師發生情感轉移","病人有假性痴呆症之變化","這是一般老人對人親切之稱謂","這表示病人對護理師極高之評價"],"answer":"A","correction":"","chapter":"D","extension":false,"context":null,"id":"110-1-24","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":25,"stem":"依據 DSM-5 所訂定之標準，物質使用障礙症（substance use disorders）中，有關耐受性（tolerance） 的敘述，下列何者正確？","options":["使用物質過量或過久，會花時間去尋找使用的物質","因物質使用嚴重，而產生了生理上的依賴，一旦停止使用，會導致身心不適","使用物質造成身體傷害，明知使用物質對身體有傷害仍持續使用","指腦部及身體已適應較高的物質濃度，因此需要更多的物質，才能達到原來的效果"],"answer":"D","correction":"","chapter":"M","extension":false,"context":null,"id":"110-1-25","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":26,"stem":"美沙冬（Methadone）可作為海洛因（Heroin）的替代治療藥物之原因，下列敘述何者錯誤？","options":["避免使用針頭，減少 HIV 傳染","較少欣快感，且長期使用不易產生嗜睡或憂鬱","提升日常生活功能後，較能正常就業","不會造成依賴"],"answer":"D","correction":"","chapter":"M","extension":false,"context":null,"id":"110-1-26","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":27,"stem":"酒精成癮的病人，因長期缺乏下列何種維生素，導致維尼克氏腦症（Wernicke’s encephalopathy）， 出現意識障礙、眼肌麻痺、運動失調症狀？","options":["維生素 A","維生素 B₁","維生素 D","維生素 K"],"answer":"B","correction":"","chapter":"M","extension":false,"context":null,"id":"110-1-27","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":28,"stem":"根據精神疾病診斷準則手冊（diagnostic andstatistical manual of mental disorders：DSM-5），有關譫妄 （delirium）的敘述，下列何者正確？","options":["記憶障礙是診斷之基本要件","病程慢性化，且症狀逐漸惡化","所產生的認知困擾，包含失去定向感、語言、視覺空間能力","移除致病導因後，通常無法完全恢復"],"answer":"C","correction":"","chapter":"L","extension":false,"context":null,"id":"110-1-28","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":29,"stem":"關於認知障礙症病人之臨床症狀，下列何者正確？","options":["定向感障礙部分，通常先發生對人物的定向感障礙","記憶力減退部分，通常先發生遠期的記憶障礙","感覺知覺障礙部分，較少出現日落症候群","語言功能部分，可能出現語言整合、理解及表達能力減退，或出現失語症"],"answer":"D","correction":"","chapter":"L","extension":false,"context":null,"id":"110-1-29","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":30,"stem":"對於暴食症（Bulimia Nervosa）病人的特徵之敘述，下列何者錯誤？","options":["短時間內吃下大量食物","覺得自己無法控制進食的種類與數量","禁食或過度運動也可能是其補償行為的一種","暴食症狀與不當補償行為同時出現，並持續一個月可達診斷標準"],"answer":"D","correction":"","chapter":"O","extension":true,"context":null,"id":"110-1-30","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":31,"stem":"王小弟，5 歲，診斷為自閉症類群障礙症（Autism Spectrum Disorder），下列護理措施何者錯誤？","options":["評估王小弟的情緒、認知及日常生活功能，並鼓勵其發展適齡的技能","安排規律的治療、吃飯與就寢時間","每天關心王小弟，以期待他能有正向情感回饋","溝通必須清楚、具體及簡單化"],"answer":"C","correction":"","chapter":"O","extension":false,"context":null,"id":"110-1-31","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":32,"stem":"黃先生 43 歲，診斷為思覺失調症，症狀經常反覆惡化，兩個月前才剛出院返家，今日又因拒服藥、 自我照顧能力差、暴力攻擊家人而入院，下列敘述何者正確？","options":["入院時即須開始進行出院準備服務","護理師於病人入院時應立即主動約束病人以防再次攻擊暴力","出院前幾天才開始進行出院準備服務，以利病人記住","有鑑於病人經常反覆住院，因此建議病人應長期住院為佳"],"answer":"A","correction":"","chapter":"P","extension":false,"context":null,"id":"110-1-32","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":33,"stem":"有關復元（recovery）的敘述，下列何者正確？","options":["建立一個能容許精神病人退縮退化的環境","生病是無奈的，因此探索生命的意義是一大禁忌","精神病人無法自我控制，故不強調自主調控","協助病人保持希望，自信與樂觀地看待未來"],"answer":"D","correction":"","chapter":"P","extension":false,"context":null,"id":"110-1-33","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":34,"stem":"有關社區精神心理衛生護理的敘述，下列何者正確？","options":["注重病人持續性、一致性的照顧","強調病人的問題解決，不需使用護理評估、診斷、目標、護理處置及評值的模式","不須考量家屬、環境、文化等因素，才是以病人為中心的照護","不應考量經濟、社會等因素，以免在社區護理過程中失焦"],"answer":"A","correction":"","chapter":"P","extension":false,"context":null,"id":"110-1-34","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":35,"stem":"王女士 45 歲，獨居，近半年來自我照顧能力差、常常自言自語，經常倒垃圾到鄰居家，鄰居苦不堪言，而多次報警，仍無法有效處理，有關社區心理衛生護理師之處置，下列何者較適當？","options":["立即聯合警消一起啟動精神疾病強制住院治療","確認王女士非為精神照護系統內登記之精神病人，故不須處理","通報衛生局連結醫療資源，由精神專科醫師到場評估，以進行確診及下一步處置","為避免與王女士衝突，不予處理"],"answer":"C","correction":"","chapter":"P","extension":false,"context":null,"id":"110-1-35","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":36,"stem":"佛洛依德（Sigmund Freud）對偏差行為的看法，認為是早期發展衝突未能妥善解決的結果，此為運用下列何種模式？","options":["人際關係模式","溝通模式","行為模式","精神分析模式"],"answer":"D","correction":"","chapter":"C","extension":false,"context":null,"id":"110-1-36","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":37,"stem":"提供穩定之慢性思覺失調症病人至社區復健中心持續接受照護，是屬於下列何項預防概念？","options":["初級預防","次級預防","三級預防","危機處置"],"answer":"C","correction":"","chapter":"P","extension":false,"context":null,"id":"110-1-37","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":38,"stem":"對於自殺行為與精神疾病之敘述，下列何者錯誤？","options":["不是每一個憂鬱症的病人，都會出現自殺企圖行為","藥癮病人的自殺，主要是因為毒品使用過量，與憂鬱無關","憂鬱症個案在出院後，仍可能有自殺的危險性","思覺失調症病人可能受到幻覺控制而出現自殺企圖行為"],"answer":"B","correction":"","chapter":"G","extension":false,"context":null,"id":"110-1-38","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":39,"stem":"張先生 40 歲，被診斷為思覺失調症，因出現被害妄想，持長棍於住家樓下，對路過行人出現言語恐嚇之行為。經聯絡警消人員送醫後強制住院治療。入病室後病人出現激躁不安、神情緊張、用力拍門及對病友口出威脅的言語，下列何者是醫護人員應立即採取的措施？","options":["醫護人員勿單獨前去處理病人，召來足夠支援人力","請家屬來院安撫並引導病人","醫護人員站在病人後面，並儘量靠近病人","對病人的要求儘量滿足，避免破壞與病人關係"],"answer":"A","correction":"","chapter":"G","extension":false,"context":null,"id":"110-1-39","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":40,"stem":"承上題，經醫護人員規勸，病人仍無法控制行為時，需進行身體約束隔離措施，下列敘述何者正確？ ①身體約束目的是由具體的身體控制，以保護病人不傷害自己及他人 ②執行身體約束過程中，無須告知病人執行目的和時間，只要注意約束過程確保人員安全即可 ③執行身體約束隔離時，每 15 分鐘應探視病人，評估生理狀況與需求 ④疏散現場圍觀者","options":["①②③","②③④","①③④","①②④"],"answer":"C","correction":"","chapter":"G","extension":false,"context":{"num":39,"stem":"張先生 40 歲，被診斷為思覺失調症，因出現被害妄想，持長棍於住家樓下，對路過行人出現言語恐嚇之行為。經聯絡警消人員送醫後強制住院治療。入病室後病人出現激躁不安、神情緊張、用力拍門及對病友口出威脅的言語，下列何者是醫護人員應立即採取的措施？","chapter":"G"},"id":"110-1-40","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":75,"stem":"目前長期照顧十年計畫 2.0 中有關失智症照顧服務，下列敘述何者不適當？","options":["團體家屋目前是專屬失智症個案的照顧模式","強化失智症初級預防主要提供 40 歲以上失智症個案多元服務項目","瑞智學堂、瑞智互助家庭提供失智症個案及其家屬家庭支持服務","提供社區失智症個案管理機制為失智症共同照護中心的功能之一"],"answer":"B","correction":"","chapter":"L","extension":false,"context":null,"id":"110-1-75","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":1,"num":80,"stem":"社區護理師在社區中若發現有疑似失智症個案須進一步確立診斷，應轉介至下列那個機構較適當？","options":["失智社區服務據點","失智共同照護中心","瑞智學堂","失智症日間照護中心"],"answer":"B","correction":"","chapter":"L","extension":false,"context":null,"id":"110-1-80","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110030"},{"year":110,"nth":2,"num":1,"stem":"依據現行精神衛生法規定，嚴重病人不遵從醫囑導致病情不穩或生活功能有退化之虞，經強制社區治療審查會決定許可強制社區治療，此次嚴重病人在接受強制社區治療期間，不能超過多久？","options":["3 個月","6 個月","9 個月","12 個月"],"answer":"B","correction":"","chapter":"A","extension":false,"context":null,"id":"110-2-1","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":2,"stem":"有關症狀穩定且日常生活可自理的精神病人，剛轉入康復之家，首要的復健目標為何？","options":["協助個案提升社區生活的能力","減少藥物服用劑量和緩解副作用","提升及早返家生活的機會","提升個人的職場工作適應"],"answer":"A","correction":"","chapter":"P","extension":false,"context":null,"id":"110-2-2","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":3,"stem":"面對有自傷意念的憂鬱症病人，下列敘述何者最符合治療性溝通行為？","options":["「憂鬱症應該可以治好的，不要擔心。」","「我認為你應該辭職，專心養病才對。」","「想要自殺的人，都在逃避負責任。」","「你對目前自己的狀況，不是很滿意。」"],"answer":"D","correction":"","chapter":"D","extension":false,"context":null,"id":"110-2-3","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":4,"stem":"吳女士，診斷思覺失調症，坐在餐桌前，不斷以手拍打桌子，口中喊著說：「怎麼這麼多蟑螂，快來幫忙打蟑螂。」雖然護理師告訴她沒有蟑螂在桌上，但她仍堅持桌上看到許多蟑螂。此為下列何種精神症狀？","options":["妄想（delusion）","自我感消失（depersonalization）","幻覺（hallucination）","失真感（derealization）"],"answer":"C","correction":"","chapter":"C","extension":false,"context":null,"id":"110-2-4","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":5,"stem":"護理師問病人：「100 減 7 是多少？」然後連續減了五個 7。這種方式除了可以評估病人的計算能力外，還可以評估下列何種能力？","options":["定向感（orientation）","注意力（attention）","判斷力（judgement）","病識感（insight）"],"answer":"B","correction":"","chapter":"B","extension":false,"context":null,"id":"110-2-5","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":6,"stem":"下列何者為貝克（Beck）認知學說的主要論述？","options":["精神問題與個人童年早期未解決之衝突及焦慮有關","人格是被環境所塑造，可用行為改變技巧矯正","情緒低落是對自己、他人及外界的錯誤解釋","高情感表露的家庭可能會增加精神疾病的復發率"],"answer":"C","correction":"","chapter":"F","extension":false,"context":null,"id":"110-2-6","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":7,"stem":"護理師在與病人建立關係的過程中常需要自我坦露（self disclosure），有關自我坦露的敘述，下列何者較適當？","options":["與病人關係對等，坦露程度決定於關係建立的深淺","自我坦露是有目的、有限度的","只要對病人有助益，都要分享自己的類似經驗","自我坦露能擴大「周哈里窗」（Johari window）之自我隱私象限"],"answer":"B","correction":"","chapter":"D","extension":false,"context":null,"id":"110-2-7","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":8,"stem":"有關抗精神病藥物的敘述，下列何者藥理作用最能歸屬於「第二型及第三型多巴胺特別性接受器阻斷劑（specific D₂/D₃ antagonist）」？","options":["Amisulpride（Solian®）","Olanzapine（Zyprexa®）","Risperidone（Risperdal®）","Ziprasidone（Geodon®）"],"answer":"A","correction":"","chapter":"E","extension":false,"context":null,"id":"110-2-8","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":9,"stem":"有關錐體外徑症候群之藥物副作用（extrapyramidal symptoms, EPS）的敘述，下列何者正確？","options":["開始使用抗精神病藥物治療的最初 3～4 天，最常產生的 EPS 是靜坐不能（akathisia）","開始使用抗精神病藥物治療 1 個月後，病人最常產生的 EPS 是急性肌肉緊張異常（acute dystonia）","開始使用抗精神病藥物治療 1 個月內，通常會出現遲發性不自主運動（tardive dyskinesia, TD）","開始使用抗精神病藥物治療的前 3 個月，就可能產生類似巴金森氏症的運動不能、表情呆板及手抖副作用"],"answer":"D","correction":"","chapter":"E","extension":false,"context":null,"id":"110-2-9","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":10,"stem":"有關精神科護理中認知治療的敘述，下列何者最適當？","options":["宜強調個案過去的事件，而非此時此刻的問題","個人的邏輯推理錯誤或不合理想法，常造成焦慮或適應不良","以單一事件對大多數事件做推論，是屬於過度個人化（personalization）","生理回饋儀是基本必備，始能達到認知改變"],"answer":"B","correction":"","chapter":"F","extension":false,"context":null,"id":"110-2-10","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":11,"stem":"護理人員應用行為治療原則於急性病房住院精神疾病病人，下列何者最適當？","options":["病人一出現不適當行為，一律立即給予懲罰","醫師與護理師分別扮黑白臉，對懲罰的態度可不同，以增強其適當的行為","出現攻擊行為後，取消禁止外出購物活動，是符合負向增強法","選擇對個案有影響的增強物，可增強適當的行為"],"answer":"D","correction":"","chapter":"F","extension":false,"context":null,"id":"110-2-11","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":12,"stem":"有關 Benzodiazepine（BZD）的護理指導，下列何者最適當？","options":["BZD 是代謝較快的藥物，將可以改善其記憶力","BZD 類藥物主要就是鎮靜安眠，無法用來抗焦慮","建議勿飲酒的主要原因是酒精促排尿，就會大量將 BZD 排出","長期服用 BZD 可能造成依賴，戒斷時宜逐漸減量"],"answer":"D","correction":"","chapter":"E","extension":false,"context":null,"id":"110-2-12","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":13,"stem":"初次入住精神科急性病房的李先生，擔心醫院伙食被人下毒，有被害妄想不願意用餐，下列何者護理措施最適當？","options":["警告他如果不吃，就須鼻胃管灌食","讓病人協助準備食物，或自備食物","同意先讓他不吃，等餓了自然就肯吃","請其他病人向他保證食物沒有毒"],"answer":"B","correction":"","chapter":"H","extension":false,"context":null,"id":"110-2-13","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":14,"stem":"對於缺乏病識感的思覺失調症住院病人，拒絕服藥時，下列處理何者較為適當？","options":["向病人解釋此為維他命沒有副作用，只要肯服下就好","了解病人拒服藥的原因，觀察其是否有藏藥行為","警告病人不服藥，就不能出院","採鼻胃管灌藥，以確保服下藥物"],"answer":"B","correction":"","chapter":"H","extension":false,"context":null,"id":"110-2-14","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":15,"stem":"有關雙相情緒障礙（bipolar disorder）的病因，下列敘述何者正確？","options":["與電解質不平衡無關","壓力或環境改變，不會提升發病率","與正腎上腺素（norepinephrine）及血清素（serotonin）濃度有關","與遺傳因素無關"],"answer":"C","correction":"","chapter":"C","extension":false,"context":null,"id":"110-2-15","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":16,"stem":"林小姐入院診斷為憂鬱症，常向護理師表示自己做錯事害得父母離婚，又因為自己不夠好，所以男友跟她分手。下列何項回應最適當？","options":["勸導她何必單戀一枝花，男友再找就有了，是他不懂林小姐的好","傾聽並同理她低自尊的感受，適時澄清其價值觀","告訴她事情都過去了，多參加外面的活動就好了","勸她不要再提父母離婚與她有關的想法"],"answer":"B","correction":"","chapter":"D","extension":false,"context":null,"id":"110-2-16","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":17,"stem":"有關病人於住院期間憂鬱症的照護，下列敘述何者正確？","options":["由於病人怕吵，儘量安排單人房給病人減少干擾","在症狀嚴重期最容易出現自殺行為，等病人情緒好轉就解除自殺風險","避免給病人壓力，不要安排活動","病人出現退化行為時，仍要鼓勵病人適時提供自我照顧的機會"],"answer":"D","correction":"","chapter":"I","extension":false,"context":null,"id":"110-2-17","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":18,"stem":"有關躁症病人住院期間的活動安排，下列何項措施最適當？","options":["安排病人參加投籃競賽，發洩過多的體力","鼓勵參與文藝活動，但避免安排精細動作的活動","將病人一天的時間都填滿活動，這樣他就不會分心去干擾別人製造紛爭","因為要訓練病人的持續力與注意力，安排長時間（至少 1 小時）的活動最有效果"],"answer":"B","correction":"","chapter":"I","extension":false,"context":null,"id":"110-2-18","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":19,"stem":"沈女士為慢性精神病病人，平日都可依醫囑按時服用抗精神病藥物，但情緒仍常受幻聽干擾而時有波動，護理師提供的護理措施，下列何者錯誤？","options":["同理病人的感受","詢問病人：「聲音說些什麼？」","直接向病人說：「不要胡思亂想！」","鼓勵運用可行之阻斷幻聽的方法"],"answer":"C","correction":"","chapter":"H","extension":false,"context":null,"id":"110-2-19","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":20,"stem":"憂鬱症病人常伴有退化行為而導致自我照顧能力缺失，護理師提供的相關護理措施，下列何者錯誤？","options":["協助進食","增加水分攝取","安排固定時間如廁","完全協助病人的自我照顧"],"answer":"D","correction":"","chapter":"I","extension":false,"context":null,"id":"110-2-20","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":21,"stem":"有關躁症發作（manic episode）病人最常見的症狀，下列何者正確？","options":["低自尊","意念飛躍","目標導向的活動減少","表情淡漠"],"answer":"B","correction":"","chapter":"I","extension":false,"context":null,"id":"110-2-21","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":22,"stem":"劉先生為思覺失調症病人，身體具異味，衣著髒亂，無法自行清潔身體，針對劉先生自我照顧功能退化的護理，下列何者正確？","options":["尋求人力支援","幫劉先生洗澡","教導劉先生洗澡","尊重劉先生意願"],"answer":"C","correction":"","chapter":"H","extension":false,"context":null,"id":"110-2-22","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":23,"stem":"依據學習理論，有關特定畏懼症（special phobia）病人學習恐懼的途徑，下列敘述何者最適當？","options":["過去曾有被畏懼對象傷害的不愉快經驗","未能從過去經歷過的重大失落事件學習如何處理焦慮","未能感受到自己被重要他人所認可","無法忽略或壓抑反覆出現的想法或衝動"],"answer":"A","correction":"","chapter":"J","extension":false,"context":null,"id":"110-2-23","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":24,"stem":"有關強迫症（obsessive-compulsive disorder, OCD）病人的敘述，下列何者最適當？","options":["病人通常缺乏病識感，無法理解這些強迫性想法","病人常使用內射之防衛機轉，化解內在的衝突不安","病人通常發病前即有求全、完美的傾向，強調事情的是非，缺少通融變化","病人對其所患之強迫思想或行為常覺得不合理或並非自己所願，但尚可抗拒"],"answer":"C","correction":"","chapter":"J","extension":false,"context":null,"id":"110-2-24","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":25,"stem":"有關急性壓力症（acute stress disorder），下列敘述何者錯誤？","options":["病人會出現易怒行為和無預警發怒","診斷的對象限於直接經歷創傷事件者","症狀困擾至少須持續 3 天以上","病人會避免接觸與創傷事件有關的物件或場合"],"answer":"B","correction":"","chapter":"J","extension":false,"context":null,"id":"110-2-25","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":26,"stem":"有關人格障礙症（personality disorder）的特性與病因，下列敘述何者較適當？","options":["與自我（ego）的功能薄弱有關，導致自我控制力較差","與遺傳無關，於嬰幼兒時期人格發展過程中形成障礙","與血清素代謝物（5-HIAA）過高有關，常會有自殺企圖、衝動控制力差","與青春期或成年早期的發展無關，宜以現有症狀表現進行診斷"],"answer":"A","correction":"","chapter":"N","extension":false,"context":null,"id":"110-2-26","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":27,"stem":"邱同學在會考前 1 個月，每次學校模擬考時都感到右手無力，被家人送到神經內科求診，但經多科醫師會診及檢查，卻找不到任何跟生理病變有關的證據，邱同學最有可能是下列何項診斷？","options":["身體症狀障礙症（somatic symptom disorder）","罹病焦慮症（illness anxiety disorder）","轉化症（conversion disorder）","人為障礙症（factitious disorder）"],"answer":"C","correction":"","chapter":"K","extension":false,"context":null,"id":"110-2-27","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":28,"stem":"有關物質使用障礙心理治療的敘述，下列何者錯誤？","options":["此項治療多半在個案恢復期時執行，可疏導個案的內心問題","採用動機式晤談（motivational interview）法，以直接面質為治療的原則","通常與家庭及心理因素息息相關，故除了提供身體治療外，也應追索問題的根源","可疏導個案的內心問題，引導個案使用正向積極的方式發洩其內心的憤怒與不滿"],"answer":"B","correction":"","chapter":"M","extension":false,"context":null,"id":"110-2-28","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":29,"stem":"美沙冬（Methadone）本為麻醉性止痛劑，可替代嗎啡類藥物，以達到治療嗎啡類藥物成癮患者。下列敘述何者正確？","options":["通常用來治療 K 他命成癮的患者","不會有蓄積性，可長期使用，且不需減少劑量","不會有呼吸抑制、欣快感和戒斷症狀","為口服藥劑，可以減少因共用針頭引起的疾病感染"],"answer":"D","correction":"","chapter":"M","extension":false,"context":null,"id":"110-2-29","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":30,"stem":"有關護理評估自閉症類群障礙症（autism spectrum disorder）的核心障礙，下列何者錯誤？","options":["重度智能不足","社交互動障礙","語言溝通障礙","重複刻板的行為模式"],"answer":"A","correction":"","chapter":"O","extension":false,"context":null,"id":"110-2-30","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":31,"stem":"針對阿茲海默氏症引起重度認知障礙症的敘述，下列何者最適當？","options":["日常生活不受影響","在傍晚和前半夜會較嚴重，出現日落症候群","遠期記憶減退通常是最先出現的記憶障礙","情緒變化與以前差別不大"],"answer":"B","correction":"","chapter":"L","extension":false,"context":null,"id":"110-2-31","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":32,"stem":"有關臺灣老年精神健康問題與疾病，下列敘述何者正確？","options":["老年精神疾病盛行率低於 1%","常見的老年精神疾病為雙相情感疾患及物質使用障礙症","老年人自殺，通常少有徵兆，難以觀測及預防","老年人會以飲酒與濫用處方藥物，調適其壓力或憂鬱"],"answer":"D","correction":"","chapter":"L","extension":false,"context":null,"id":"110-2-32","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":33,"stem":"運用簡易心智量表（Mini-Mental State Examination,MMSE）評估老年人精神狀態，下列何者不是其評估的功能表現？","options":["定向感","注意力","記憶力","情緒狀態"],"answer":"D","correction":"","chapter":"B","extension":false,"context":null,"id":"110-2-33","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":34,"stem":"有關罹患注意力缺陷過動症（ADHD）學齡期兒童的治療計畫，下列敘述何者錯誤？","options":["可使用中樞神經興奮劑 Ritalin○R ，來改善其衝動及活動量過高之行為","為避免病情復發，中樞神經興奮劑宜長期服用，絕對不可停藥","可合併使用藥物治療及感覺統合治療，以增加治療效益","急性住院期間宜安排不具攻擊性的活動"],"answer":"B","correction":"","chapter":"O","extension":false,"context":null,"id":"110-2-34","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":35,"stem":"許小姐 35 歲，反覆住院的情感性精神病病人。近日剛從急性病房轉慢性病房，家屬可接受病人返家同住，只是擔心病人病情惡化，病人有工作及復健潛能。下列有關病人的出院準備何者較適當？","options":["在出院前轉介精神衛生護理之家","在出院前轉介日間型精神復健機構","在出院前轉介住宿型精神復健機構","在出院前轉介康復之家"],"answer":"B","correction":"","chapter":"P","extension":false,"context":null,"id":"110-2-35","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":36,"stem":"有關賦能模式（empowerment model）的概念，下列何者正確？","options":["是依個案的需求，由精神專業人員為個案做出最好的決定","提供充分的資訊，協助個案了解自己的狀況，擁有自決的能力","主張在復元的歷程，由精神專業人員承擔個案身心照護之責","視個案為失能者，針對個案的缺點發現問題本身進行問題改善"],"answer":"B","correction":"","chapter":"P","extension":false,"context":null,"id":"110-2-36","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":37,"stem":"臨床護理人員面對病人暴力行為時的心理反應與態度，下列敘述何者正確？","options":["臨床醫師被病人攻擊的危險性最高","當護理人員於職場中被攻擊時，通常出現大聲哭訴","於精神科工作被病人攻擊是正常的現象，所以只要提醒受害工作人員小心即可","營造治療性環境的支持，可以協助護理人員被暴力攻擊時處理情緒"],"answer":"D","correction":"","chapter":"G","extension":false,"context":null,"id":"110-2-37","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":38,"stem":"有關「社區心理衛生中心」的主要服務內容，下列何者適當？","options":["辦理身體健康促進、衛教宣導及專業訓練等活動","辦理心理健康促進活動及高危險群病人之危機處理","執行災難緊急應變之身體創傷救護","辦理民眾身體健康諮詢及身體治療服務"],"answer":"B","correction":"","chapter":"P","extension":false,"context":null,"id":"110-2-38","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":39,"stem":"有關精神科住院病人出現暴力行為的護理措施，下列敘述何者錯誤？","options":["約束病人前，需取得病人同意","執行約束後，至少每 15 分鐘探視病人 1 次","可依照醫囑給予注射抗精神病藥物","病人情況穩定後，讓其有機會說明自己的行為"],"answer":"A","correction":"","chapter":"G","extension":false,"context":null,"id":"110-2-39","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":40,"stem":"有關遭受精神病人暴力攻擊的護理人員之輔導，下列何者較適當？","options":["護理人員被攻擊後可能會感到羞愧，避免直接與其會談","現場立即檢討是否護理人員處置不當而引發病人暴力","加強全院通報系統，以杜絕病房暴力發生","暴力事件後，提升護理人員面對暴力行為的處理能力"],"answer":"D","correction":"","chapter":"G","extension":false,"context":null,"id":"110-2-40","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":75,"stem":"依據長期照顧十年計畫 2.0 失智照護政策之介紹，下列何者錯誤？","options":["將 60 歲以上失智者納入服務對象","廣設「失智社區服務據點」以提供個案及照顧者支持服務，如：家屬照顧訓練及支持團體等","鼓勵縣市政府廣結民間資源，布建日間照顧中心、團體家屋等社區照顧服務","補助入住機構專區之失智症中度以上且具行動能力老人「特別處遇費」，減輕家屬負擔"],"answer":"A","correction":"","chapter":"L","extension":false,"context":null,"id":"110-2-75","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":79,"stem":"王老先生向社區護理師主訴他最近常提不起精神、感覺無力、不想出門、體重也減輕，下列護理師的處置何者最不適當？","options":["轉介至老年醫學科或家醫科就診","轉介參加社區延緩失能失智活動","教導預防跌倒策略","建議多休息，以利恢復體能"],"answer":"D","correction":"","chapter":"L","extension":false,"context":null,"id":"110-2-79","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":110,"nth":2,"num":80,"stem":"依據病人自主權利法規定，有關輕度認知障礙者事先預立醫療決定的敘述，下列何者正確？","options":["18 歲以上者都可以簽署預立醫療決定","意願人簽署「預立醫療決定」前須先經醫療機構「預立醫療照護諮商」","家屬可全權代理簽署「預立醫療決定」文件","有認知障礙者不能簽立「預立醫療決定」"],"answer":"B","correction":"","chapter":"A","extension":false,"context":null,"id":"110-2-80","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2021&e=110110"},{"year":111,"nth":1,"num":1,"stem":"王奶奶，80 歲，因憂鬱症住院。低聲說：「我全身都壞了，兒子不孝順只想要我的財產而已。」護理師說：「妳是擔心自己的身體和財產嗎？」此時護理師所運用的溝通技巧為：","options":["澄清","提出懷疑","鼓勵比較","面質"],"answer":"A","correction":"","chapter":"D","extension":false,"context":null,"id":"111-1-1","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":2,"stem":"社區內舉辦新手媽媽講座，教導懷孕的身心變化相關課程，是屬於精神心理衛生工作中的那一級的預防？","options":["初級預防","次級預防","三級預防","各級皆涵蓋"],"answer":"A","correction":"","chapter":"P","extension":false,"context":null,"id":"111-1-2","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":3,"stem":"下列何者最符合現行精神衛生法所規範的精神病人之保護及權益保障？","options":["為保護住院精神病人之安全，不可以有會客權利","為保護校園安全，學校得拒絕曾罹患精神疾病病人入學就讀","為保護社區安全，慢性精神病患應長期安置於醫療機構","傳播媒體的報導，不得使用與精神疾病有關的歧視性稱呼或描述"],"answer":"D","correction":"","chapter":"A","extension":false,"context":null,"id":"111-1-3","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":4,"stem":"關於精神衛生護理工作範圍，居家護理師於病人出院後，協助強化其社交技巧，此項照護較屬於下列何者？","options":["保健性","治療性","復健性","管理性"],"answer":"C","correction":"","chapter":"P","extension":false,"context":null,"id":"111-1-4","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":5,"stem":"有關譫妄（delirium）的敘述，下列何者錯誤？","options":["觸幻覺是最常見的知覺障礙","任何年齡皆有可能發生","會出現認知困擾","電解質不平衡與譫妄發生有關"],"answer":"A","correction":"","chapter":"L","extension":false,"context":null,"id":"111-1-5","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":6,"stem":"陳護理師因為先生喝酒問題常常引起夫妻之間的衝突，陳護理師想到今天要接的新病人，診斷為酒精使用障礙症（alcohol use disorder），陳護理師就感到焦慮、生氣，這是下列何種現象？","options":["正面情感轉移","負面情感轉移","正面情感反轉移","負面情感反轉移"],"answer":"D","correction":"","chapter":"D","extension":false,"context":null,"id":"111-1-6","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":7,"stem":"承上題，陳護理師與新病人接觸前，宜優先進行下列何項措施？","options":["隱藏自己內心的焦慮與生氣","請護理長改由其他護理師接此病人","自我覺察這類診斷的病人會讓自己感到不適","自己與病人接觸時不能有任何情緒"],"answer":"C","correction":"","chapter":"D","extension":false,"context":{"num":6,"stem":"陳護理師因為先生喝酒問題常常引起夫妻之間的衝突，陳護理師想到今天要接的新病人，診斷為酒精使用障礙症（alcohol use disorder），陳護理師就感到焦慮、生氣，這是下列何種現象？","chapter":"D"},"id":"111-1-7","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":8,"stem":"護理師在病房照護病人，經常會應用行為治療協助病人行為改變，下列敘述何者最適當？","options":["護理師稱讚病人可以踴躍發言，病人因而更願意分享，這是應用負向增強原理","護理師和病人約定，如果不出現干擾行為達 3 天，就可以解除暫禁外出，這是應用正向增強原理","為協助病人養成盥洗習慣，從簡單開始，將任務分成許多步驟推動，是應用逐步養成法的行為處置","將攻擊他人的病人，四肢約束送進保護室觀察，最主要是運用負向增強原理"],"answer":"C","correction":"","chapter":"F","extension":false,"context":null,"id":"111-1-8","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":9,"stem":"協助危機狀態生還者之個別性處置（individual approach），下列何者最適當？","options":["需要發掘個案適用的因應機轉","通常並不包含家人在處置內","重視生理需求，但先不處理心理需求","鼓勵個案澄清（clarify）事實為主，不鼓勵情感宣洩（catharsis）"],"answer":"A","correction":"","chapter":"G","extension":false,"context":null,"id":"111-1-9","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":10,"stem":"下列有關精神疾病臨床症狀的敘述，何者正確？","options":["對外界事務過度注意，甚至有警覺心，稱之為欣快感（euphoria）","對同一件事同時存在兩種相反的情感感受，稱之為不恰當情感（inappropriate affect）","情感遲鈍、面部表情少、對外界漠不關心，稱之為失快樂感（anhedonia）","說話快速而持續，話題轉換迅速，話題間略有關聯，稱之為意念飛躍（flight of ideas）"],"answer":"D","correction":"","chapter":"C","extension":false,"context":null,"id":"111-1-10","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":11,"stem":"強調人是自主的，可自由創造具有價值意義的生存方式，是下列何項心理治療的理論觀點？","options":["心理分析治療","個人中心治療","存在—人文主義治療","認知行為治療"],"answer":"C","correction":"","chapter":"F","extension":false,"context":null,"id":"111-1-11","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":12,"stem":"王小姐在精神科病房住院，住院期間某日與其他病人爭執，出手攻擊對方。依據行為治療理論，下列何項負向增強（negative reinforcement）的處置最適當？","options":["減少外出購物次數","送到保護室","不讓病人吃點心","執行約束"],"answer":"B","correction":"第12題答Ｂ給分。","chapter":"F","extension":false,"context":null,"id":"111-1-12","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":13,"stem":"有關現實治療的描述，下列敘述何者最適當？","options":["可藉由正當、責任與現實來有效管理個人的生活","運用面質技巧，矯正個案的錯誤認知","重視過去的探討，而非此時此刻和未來","運用潛意識引導，協助認識自我的需求"],"answer":"A","correction":"","chapter":"F","extension":false,"context":null,"id":"111-1-13","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":14,"stem":"對慢性思覺失調症且功能退化病人的照護，護理師指導家屬的照護病人的措施，下列何者正確？ ①直接幫病人做日常生活上的照顧，又快又好 ②宜採漸進式訓練 ③需要耐性予以接納與訓練 ④配合獎賞引發學習動機","options":["①②③","①②④","①③④","②③④"],"answer":"D","correction":"","chapter":"H","extension":false,"context":null,"id":"111-1-14","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":15,"stem":"根據 DSM-5 診斷準則，經期前情緒低落症（Premenstrual Dysphoric Disorder）的症狀，下列何者最不適當？","options":["月經前 1 週出現易怒、焦慮、緊張","月經前 1 週出現專注力降低、易疲勞、失去控制感","月經來潮後幾天內症狀會改善","症狀不會影響工作效率"],"answer":"D","correction":"","chapter":"I","extension":false,"context":null,"id":"111-1-15","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":16,"stem":"林先生因為雙相情緒障礙症（Bipolar Disorder）躁症發作住院，主要治療藥物為鋰鹽、carbamazepine （Tegretol®）。護理師發現林先生顯得倦怠、無力，緊急抽血鋰鹽濃度為 0.8mEq/L、Na 為 120 mEq/L。 下列何項護理措施最適當？","options":["鋰鹽濃度偏高，立即停止服用鋰鹽，預防中毒","是 carbamazepine 的嚴重不良反應，立即停止服用","注意評估病人飲水量","再隔 2 個月抽血檢查鋰鹽及 Na 濃度"],"answer":"C","correction":"","chapter":"E","extension":false,"context":null,"id":"111-1-16","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":17,"stem":"黃先生，診斷為思覺失調症（Schizophrenia），規則服藥，在社區復健機構接受治療時，被一位女性踩到腳，他認為自己是病人，又沒結婚，那位女性才會故意踩他的腳。下列何項護理措施最適當？","options":["病人有被害妄想，建議調藥","同理病人並討論對應方法","解釋那位女性不是故意行為","提醒病人走路要注意"],"answer":"B","correction":"","chapter":"H","extension":false,"context":null,"id":"111-1-17","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":18,"stem":"有關思覺失調症（Schizophrenia）病程進展的描述，下列何者最適當？","options":["前驅期以正性症狀為主，出現功能衰退的表現","發病期的發作一般與心理社會壓力事件有關","前驅期常常出現暴力或自傷行為","殘留期通常發生在青少年階段"],"answer":"B","correction":"","chapter":"H","extension":false,"context":null,"id":"111-1-18","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":19,"stem":"小君，診斷為思覺失調症（Schizophrenia），可規則服藥，在大賣場工作自覺可以勝任，但近來懷疑組長挑剔她，以咳嗽暗示要她辭職。下列何者為目前最主要的護理問題？","options":["服藥問題","社區民眾的歧視問題","家庭問題","症狀困擾問題"],"answer":"D","correction":"","chapter":"B","extension":false,"context":null,"id":"111-1-19","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":20,"stem":"承上題，有關提供小君的護理措施，下列何者最適當？","options":["教導努力增加工作表現","提高自我價值感","教導辨識精神症狀及處理","教導正確服藥的方法"],"answer":"C","correction":"","chapter":"H","extension":false,"context":{"num":19,"stem":"小君，診斷為思覺失調症（Schizophrenia），可規則服藥，在大賣場工作自覺可以勝任，但近來懷疑組長挑剔她，以咳嗽暗示要她辭職。下列何者為目前最主要的護理問題？","chapter":"B"},"id":"111-1-20","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":21,"stem":"李小姐因強迫症住院，今日母親探視時又因李小姐的強迫症狀而有爭執，母親離去後李小姐顯得焦躁不安。下列何種說法最有助於協助病人覺察自己的焦慮與行為間的關聯性？","options":["可不可以多告訴我，妳對強迫症的看法？","沒有人是完美的，妳的強迫症狀是正常的。","我看到妳在咬指甲和走來走去，妳現在覺得怎麼樣？","妳很緊張吧，我們來聽音樂消除焦慮。"],"answer":"C","correction":"","chapter":"J","extension":false,"context":null,"id":"111-1-21","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":22,"stem":"根據 DSM-5 診斷準則，有關反社會人格（Antisocial Personality Disorder）的敘述，下列何者最不適當？","options":["無法遵從社會規範，經常遊走於法律邊緣","認為自己很重要，希望他人自動順從自己的意願","不負責任，無法維持工作或亂開空頭支票","不知悔恨，合理化對他人造成的傷害"],"answer":"B","correction":"","chapter":"N","extension":false,"context":null,"id":"111-1-22","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":23,"stem":"有關強迫症病人常使用的防衛機轉，下列何項較不適當？","options":["隔離","反向","抵消","內射"],"answer":"D","correction":"","chapter":"J","extension":false,"context":null,"id":"111-1-23","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":24,"stem":"下列何種藥物，常用於治療強迫症病人的強迫行為？","options":["抗焦慮劑—短效 benzodiazepine，例如 alprazolam（Xanax®）","抗憂鬱劑—選擇性血清素再回收抑制劑，例如 fluvoxamine（Luvox®）","中樞神經興奮劑，例如 methylphenidate（Ritalin®）","抗精神病藥物，例如 aripiprazole（Abilify®）"],"answer":"B","correction":"","chapter":"E","extension":false,"context":null,"id":"111-1-24","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":25,"stem":"王先生，診斷為廣泛性焦慮症，住院第一天顯得坐立不安、肌肉緊繃。有關此時會談的重點，下列何者最適當？","options":["你以前緊張時都是怎麼處理的？","是否因為擔心工作的事而引起？","你和家人相處的狀況如何？","請你說說你現在覺得怎麼樣？"],"answer":"D","correction":"","chapter":"J","extension":false,"context":null,"id":"111-1-25","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":26,"stem":"有關評估假性失智症（pseudodementia）與失智症之臨床差異，下列何者正確？①假性失智症多半有比較清楚的發病時間 ②假性失智症常抱怨認知障礙 ③失智症行為與認知障礙的嚴重度吻合 ④失智症對問話老是回答「不知道」、「忘記了」","options":["①③④","②③④","①②④","①②③"],"answer":"D","correction":"","chapter":"L","extension":false,"context":null,"id":"111-1-26","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":27,"stem":"有關海洛因中毒症狀的敘述，下列何者錯誤？","options":["瞳孔放大","心跳變慢","昏迷","呼吸抑制"],"answer":"A","correction":"","chapter":"M","extension":false,"context":null,"id":"111-1-27","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":28,"stem":"有關酒精成癮治療的敘述，下列何者錯誤？","options":["以麻醉拮抗劑（naloxone）矯正乙醇引發的意識昏迷狀態","以 BZD 與 α₁-Blockers 藥物治療自主神經系統亢奮症狀","戒酒發泡錠（disulfiram）可抑制肝臟代謝酒精的過程","宜合併心理治療"],"answer":"B","correction":"","chapter":"M","extension":false,"context":null,"id":"111-1-28","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":29,"stem":"有關於精神疾病診斷準則手冊（Diagnostic and statistical manual of mental disorders, DSM-5）對於「認知障礙症」診斷準則之敘述，下列何者正確？","options":["病程是慢性而可逆的","記憶障礙是診斷之基本要件","一項或多項的認知範疇顯著較先前的認知表現降低","認知缺損不影響到日常活動獨立進行"],"answer":"C","correction":"","chapter":"L","extension":false,"context":null,"id":"111-1-29","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":30,"stem":"有關注意力不足／過動症（ADHD）的治療原則，下列何者最不適當？","options":["安排活動以疏導其過多的活動力","活動無法持續時應立即終止，以減少挫折","儘量避免選擇需非常專注的靜態活動","不宜安排過度攻擊的活動，以防造成傷害"],"answer":"B","correction":"","chapter":"O","extension":false,"context":null,"id":"111-1-30","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":31,"stem":"張先生，80 歲，診斷為阿茲海默症，因情緒激動及焦慮而住院。近日因不明原因發燒、咳嗽有痰不舒服，表示要回家，且對陪同住院媳婦不諒解，故出手打了媳婦一巴掌。下列何者護理措施最適當？","options":["立即給予張先生抗精神病針劑藥物","將張先生帶離現場，協助痰液排出","告知張先生打人是不被允許的","將張先生帶入保護室，予以約束"],"answer":"B","correction":"","chapter":"L","extension":false,"context":null,"id":"111-1-31","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":32,"stem":"承上題，張先生懷疑家中地契被媳婦偷。下列何項護理措施最適當？","options":["跟張先生澄清：「沒有人會拿您的地契，不用擔心。」","請媳婦向張先生解釋自己並未拿取地契","對張先生說：「你最喜歡的戶外散步時間到了，我們一起去戶外散步！」","請張先生最信任的女兒或兒子到院幫忙安撫"],"answer":"C","correction":"","chapter":"L","extension":false,"context":{"num":31,"stem":"張先生，80 歲，診斷為阿茲海默症，因情緒激動及焦慮而住院。近日因不明原因發燒、咳嗽有痰不舒服，表示要回家，且對陪同住院媳婦不諒解，故出手打了媳婦一巴掌。下列何者護理措施最適當？","chapter":"L"},"id":"111-1-32","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":33,"stem":"有關輕度失智症病人的護理措施，下列何者最適當？","options":["活動安排宜每日做變化，以訓練病人的記憶力","主動協助病人生活照顧，以免增加病人的失能","安排不同的工作人員照顧病人，以增加病人的定向感","當病人出現妄想而激躁時，宜適當轉移注意力"],"answer":"D","correction":"","chapter":"L","extension":false,"context":null,"id":"111-1-33","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":34,"stem":"5 歲的小欣被愛上網咖的父母親獨自留在家裡 3 天了，被發現時只有桌上放一瓶水和一些零食。較屬於下列何項家庭暴力？","options":["身體虐待（physical abuse）","疏忽（neglect）","心理虐待（emotional or psychological abuse）","管教不當（inappropriate discipline）"],"answer":"B","correction":"","chapter":"G","extension":false,"context":null,"id":"111-1-34","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":35,"stem":"病人跟護理師說：「我好想死！沒有她，我真的活不下去。」下列何項護理措施最適當？","options":["告訴病人「拜託，別那麼笨了，就為了一個女人」","病人現在正在情緒低落時，給他時間獨處冷靜後就會沒事","告訴病人「失去她，你心裡真不好受，要不要多談一些！」","這是失戀者常說的話，過一段時間就好了"],"answer":"C","correction":"","chapter":"G","extension":false,"context":null,"id":"111-1-35","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":36,"stem":"照顧精神護理之家的失智症住民，下列何項護理措施最適當？","options":["協助發揮其尚存的優勢和能力","與聽力障礙的住民互動時，只能提高音量、大聲說話","當住民有視、聽幻覺時，宜忽略此症狀","避免跌倒發生，不宜安排活動"],"answer":"A","correction":"","chapter":"L","extension":false,"context":null,"id":"111-1-36","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":37,"stem":"對保護室內病人採取約束處置時，密切觀察的主要項目，不包含下列何項？","options":["是否有娛樂設施","病人的言行反應","個人的生理需求","脈搏及呼吸"],"answer":"A","correction":"","chapter":"G","extension":false,"context":null,"id":"111-1-37","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":38,"stem":"王小姐，45 歲，體重適中，是居住在社區的思覺失調症病人，因服用抗精神病藥物 clozapine，之後發現有代謝症候群。下列敘述何者最適當？","options":["clozapine 出現代謝症候群的症狀，包括嚴重流口水、白血球缺乏等","立即停藥是控制代謝症候群的最好策略","應先釐清代謝症候群是遺傳性或非遺傳性","先測量病人的尿酸做為基準值，有利後續持續追蹤"],"answer":"C","correction":"","chapter":"E","extension":false,"context":null,"id":"111-1-38","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":39,"stem":"承上題，對王小姐因藥物副作用產生的代謝症候群，下列何項護理措施最適當？","options":["瞭解 clozapine 產生糖尿病的危險性，只需追蹤服藥後 1 年之空腹血糖即可","瞭解 clozapine 對尿酸的影響，建議採用低普林飲食","瞭解流口水是 clozapine 造成的代謝症候群問題之一，建議醫師變更藥物","瞭解 clozapine 對體重上升的影響，開始服藥後需持續提供病人營養及運動諮詢"],"answer":"D","correction":"","chapter":"E","extension":false,"context":{"num":38,"stem":"王小姐，45 歲，體重適中，是居住在社區的思覺失調症病人，因服用抗精神病藥物 clozapine，之後發現有代謝症候群。下列敘述何者最適當？","chapter":"E"},"id":"111-1-39","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":40,"stem":"根據卡普蘭（Caplan, G.）危機理論，當個人常慣用的因應機轉失敗時，個體功能變得紊亂時，此為何項危機理論的分期？","options":["衝擊期","紊亂期","求助期","崩潰期"],"answer":"B","correction":"","chapter":"G","extension":false,"context":null,"id":"111-1-40","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":1,"num":63,"stem":"張老先生患有失智症，因他有隨地大小便，且有誤食之問題。基於安全考量，社區護理師應優先建議家屬使用下列何項措施？","options":["將張老先生送至失智症專門照顧機構","儘量將危險物品收起","儘量為張老先生包尿片","訓練張老先生按時如廁"],"answer":"B","correction":"","chapter":"L","extension":false,"context":null,"id":"111-1-63","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111030"},{"year":111,"nth":2,"num":1,"stem":"倪女士，29 歲，程式工程師，輕躁症發作（hypomanic episode）。「我都有按照醫生的交代認真吃藥， 為什麼還會發病？」護理師說：「你覺得很挫折，覺得自己很認真的吃藥卻還是發病」，此時護理師所運用的溝通技巧，下列何者最適當？","options":["反映","鼓勵比較","面質","提出懷疑"],"answer":"A","correction":"","chapter":"D","extension":false,"context":null,"id":"111-2-1","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":2,"stem":"精神復健機構的資深護理師協助病人接受「強制社區治療」的工作項目中，下列何者正確？①藥物治療 ②藥物之依賴性評估 ③藥物之血液檢驗 ④藥物之尿液濃度檢驗 ⑤酒精篩檢 ⑥放射性藥物檢驗","options":["①②③④","②③④⑤","①③④⑤","①③④⑥"],"answer":"C","correction":"","chapter":"A","extension":false,"context":null,"id":"111-2-2","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":3,"stem":"身為專業的精神衛生護理人員，對精神科病人應有的認識，下列敘述何者正確？①病人怪異的想法和行為，都是有目的、有意義的，且為滿足某個需要或溝通某種訊息而呈現出來 ②精神病人的導因， 並非來自單一的病因，而是基因、生活、心理、社會，相互影響的結果 ③精神病人多半缺乏自信， 無安全感、挫折忍受度或抗壓性低 ④一旦診斷為重度精神疾患，就難以治癒，故不需太多關注於病人的病態思想、情緒和行為，只需維持病人的基本生理照護即可","options":["①②③","①②④","①③④","②③④"],"answer":"A","correction":"","chapter":"A","extension":false,"context":null,"id":"111-2-3","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":4,"stem":"精神科醫師伯恩（Eric Berne）在溝通分析中，將人與人互動時彼此的人生地位分為四種型式。下列何者敘述屬於「我好－你不好型」？","options":["覺得自己、他人，甚至全世界都毫無意義","相信自己與他人，能積極面對自己與他人","覺得自己沒有價值，常歸咎自己，認為人生不快樂","不相信別人、自大，易以憤怒的狀態去面對別人"],"answer":"D","correction":"","chapter":"D","extension":false,"context":null,"id":"111-2-4","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":5,"stem":"俗稱安公子的安非他命，其戒斷症狀最可能為下列何者？","options":["精力旺盛","全身耗竭虛脫、憂鬱沮喪","肌肉僵直","注意力集中"],"answer":"B","correction":"","chapter":"M","extension":false,"context":null,"id":"111-2-5","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":6,"stem":"有關抗精神病藥物的副作用，下列敘述何者最適當？","options":["可能引起血壓下降，病人臥姿改為立姿動作應緩慢及注意安全","靜坐不能副作用主要發生在服用抗精神病藥物達兩年以上的病人","服用第一代抗精神病藥物較第二代抗精神病藥物容易發生代謝症候群","若發生類巴金森氏症的錐體外徑症候群副作用，應立即停藥觀察"],"answer":"A","correction":"","chapter":"E","extension":false,"context":null,"id":"111-2-6","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":7,"stem":"有關 Benzodiazepine(BZD)類藥物，下列注意事項敘述何者最適當？","options":["為海洛因成癮替代療法之主要用藥","可減緩病人因酒精戒斷產生的不適","短效型藥物的半衰期為 12 小時以上才能達助眠效果","長期使用 BZD 不會發生耐受性、成癮性和戒斷症狀"],"answer":"B","correction":"","chapter":"E","extension":false,"context":null,"id":"111-2-7","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":8,"stem":"羅小姐，30 歲，診斷為雙相情緒障礙症，居家護理師至其家中訪視，發現可能是躁症發作。下列何者為其最可能出現的症狀？","options":["淡漠、病識感差、思考貧乏","焦慮、身體症狀、睡眠中斷","高昂、活動量大、判斷力差","社交隔離、妄想、音韻連結"],"answer":"C","correction":"","chapter":"I","extension":false,"context":null,"id":"111-2-8","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":9,"stem":"有關病人服用精神科相關藥物的反應及處置，下列何者最適當？","options":["病人開始服用 Venlafaxine（Efexor®）若抱怨有噁心感（nausea），應建議立即停藥或換藥","觀察到剛服用 Mirtazapine（Remeron®）的病人有鎮靜（sedation）表現，應建議立即停藥或換藥","服用選擇性血清素再吸收抑制劑（Selective Serotonin Reuptake Inhibitor, SSRI）的病人，可衛教其自我限制熱量攝取，因為其體重隨時會增加","觀察到服用 Haloperidol（Haldol®）的病人有遲發性不自主運動（tardive dyskinesia）的表現，應建議立即停藥或換藥"],"answer":"D","correction":"","chapter":"E","extension":false,"context":null,"id":"111-2-9","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":10,"stem":"有關思覺失調症病因的敘述，下列何者最適當？","options":["發生率為 5%左右","好發年齡是中老年期","發病與神經心理因素無關","男女發生率相當"],"answer":"D","correction":"","chapter":"C","extension":false,"context":null,"id":"111-2-10","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":11,"stem":"某次張小姐在團體治療過程中說：「尤先生剛才指出我在團體中講話的態度引起別人的不舒服，使我更了解到自己和別人互動的問題。」這段話在團體治療中有關對治療性因素的敘述，下列何者最適當？","options":["利他因素","人際學習","模仿行為","普遍性"],"answer":"B","correction":"","chapter":"F","extension":false,"context":null,"id":"111-2-11","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":12,"stem":"下列何者屬於心理分析治療的策略？","options":["抗拒的解析","正向增強","人際溝通訓練","認知再建構"],"answer":"A","correction":"","chapter":"F","extension":false,"context":null,"id":"111-2-12","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":13,"stem":"根據門寧格（WilliamMenninger）所提出的態度治療理論，對於有操控、挑撥、過分要求的病人，最適當的治療態度為何？","options":["主動友善","被動友善","就事論事","寬容"],"answer":"C","correction":"","chapter":"F","extension":false,"context":null,"id":"111-2-13","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":14,"stem":"有關下列疾患的心理因素，下列何者正確？","options":["人際關係學派提及強迫症的發作源自於早年的肛門期，個人常以自我防衛機轉處理焦慮","以精神分析的觀點來分析焦慮之導因，主要認為焦慮與同儕缺乏同理心有關","學習理論之行為學派視焦慮為一種刺激、反應連結的學習反應","認知學派認為趨避衝突最會誘發個人的焦慮"],"answer":"C","correction":"","chapter":"C","extension":false,"context":null,"id":"111-2-14","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":15,"stem":"關於認知行為治療技巧的敘述，下列何者最適當？","options":["僅需要寫下能夠支持負向想法的證據","用會引起焦慮或災難化的解釋","分析早期發展對問題的影響","利用觀察現實，排除自我中心"],"answer":"D","correction":"","chapter":"F","extension":false,"context":null,"id":"111-2-15","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":16,"stem":"張太太，58 歲，診斷為憂鬱症，入院第三天，整天躺床，覺得焦慮不安、精神不集中且常常哭泣，對病房活動沒有參與動機，下列何者照護措施較適當？","options":["安排在走廊最後一間的房間，以避免過多人走動而干擾病人的休息","選擇競爭性活動以增進病人的生存動機","接受病人宣洩抑鬱情緒的表達方式","安排白天參與需要耗費體力的活動"],"answer":"C","correction":"","chapter":"I","extension":false,"context":null,"id":"111-2-16","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":17,"stem":"楊小姐，52 歲，診斷為憂鬱症，向護理師抱怨：「請你告訴醫生吃藥讓我非常不舒服。」護理師的回答，下列何者最適當？","options":["醫生是為了妳好，請妳多忍耐","醫生查房時，請妳直接跟醫生說","請再多描述是怎麼樣的不舒服","樂觀一點，妳很快就會好起來"],"answer":"C","correction":"","chapter":"D","extension":false,"context":null,"id":"111-2-17","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":18,"stem":"小菲，18 歲，診斷為思覺失調症。小菲雖有規則服藥，但是幻聽干擾時好時壞。父母打聽可以做電氣痙攣療法，因此詢問護理師的意見，下列何者回答最適當？","options":["告知須完全聽從醫師的指示","指出電氣痙攣療法的效果不好","說明病人年紀太小不適合","詢問父母對電氣痙攣療法的期望"],"answer":"D","correction":"","chapter":"E","extension":false,"context":null,"id":"111-2-18","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":19,"stem":"王小姐，與男朋友分手後，出現被跟蹤的感覺，身邊沒有人時卻聽到有人跟她說話，害怕到無法外出工作，且上述症狀持續 1 個月以上。依據 DSM-5 診斷準則，下列何者是王小姐最可能的診斷？","options":["重度憂鬱症（major depressive disorder）","創傷後壓力症（posttraumatic stress disorder）","思覺失調症（schizophrenia）","強迫症（obsessive-compulsive disorder）"],"answer":"C","correction":"","chapter":"H","extension":false,"context":null,"id":"111-2-19","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":20,"stem":"林小姐，15 歲，診斷為思覺失調症，多次因和母親的男朋友有爭執，出現幻聽。下列何者居家護理措施最適當？","options":["教導病人接受母親的男友","建議病人獨居減輕衝突","安排強制住院","安排家庭治療"],"answer":"D","correction":"","chapter":"H","extension":false,"context":null,"id":"111-2-20","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":21,"stem":"葛先生，診斷為雙相情緒障礙症，入院第三天，在入院期間常常在大廳走動，很容易與其他病友起口角或衝突，經醫療團隊討論後決定給予葛先生執行隔離措施，對隔離措施的敘述，下列何者正確？","options":["減少感覺輸入，減少外界過多的刺激","是一種行為治療法，藉以約束葛先生的行為，以減少與他人之衝突","隔離措施沒有程度上的差別","是一種控制手段，以維護病房的安寧"],"answer":"A","correction":"","chapter":"G","extension":false,"context":null,"id":"111-2-21","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":22,"stem":"有關創傷後壓力症（posttraumatic stress disorder）的敘述，下列何者錯誤？","options":["對災難事件不斷反覆的經驗再現（flashback）","持續逃避與此創傷有關的刺激","症狀持續超過 1 個月","常使用抵消的防衛機轉"],"answer":"D","correction":"","chapter":"J","extension":false,"context":null,"id":"111-2-22","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":23,"stem":"強迫症（obsessive-compulsive disorder）的主要臨床症狀，下列敘述何者正確？","options":["10 分鐘內達到極重度之焦慮表現，如呼吸困難","刻意逃避社交場所","有特定對象引發焦慮，如針筒","出現難以控制的重複性行為及思想"],"answer":"D","correction":"","chapter":"J","extension":false,"context":null,"id":"111-2-23","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":24,"stem":"下列有關急性壓力症（acute stress disorder）的敘述，何者錯誤？","options":["創傷後次日可確定診斷","暴露於真正或具威脅性的死亡、或重傷","會出現逃避、解離、警覺等症狀","會引起社交、職業等功能減損"],"answer":"A","correction":"","chapter":"J","extension":false,"context":null,"id":"111-2-24","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":25,"stem":"有關焦慮的敘述，下列何者最適當？","options":["焦慮是主觀的感受，皆與情境無關","中度焦慮時注意力集中，利於學習效果","焦慮伴隨的身體症狀，主要以自主神經系統反應為主","防衛機轉不能降低焦慮"],"answer":"C","correction":"","chapter":"J","extension":false,"context":null,"id":"111-2-25","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":26,"stem":"張先生為長期飲酒，反覆住院戒酒之病人，此次入院後第二天，心跳過快、血壓升高、大量流汗，聲稱於病室內看到蛇。此時病人最可能出現的是下列何者？","options":["酒精性失憶","躁症發作","癲癇發作","震顫性譫妄（delirium tremens）"],"answer":"D","correction":"","chapter":"M","extension":false,"context":null,"id":"111-2-26","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":27,"stem":"物質使用障礙症病人，會產生心理依賴（psychological dependence），下列敘述何者正確？","options":["使用物質過量或過久而持續想要戒除，因此花時間尋找使用之物質以及對物質的渴求","強烈對物質的渴求，為避免不愉快的感受，而持續或間歇式的使用該物質","使用物質造成身體傷害，明知使用物質對身體有傷害仍持續使用","因物質使用嚴重，而產生了依賴性，一旦停止使用，會導致身體不適情形"],"answer":"B","correction":"","chapter":"M","extension":false,"context":null,"id":"111-2-27","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":28,"stem":"有關物質使用障礙症個案的追蹤輔導的敘述，下列何者錯誤？","options":["降低個案渴求物質與預防再發","建立健康與調適的生活型態","主要採取住院方式實施輔導","定期諮商以及協助個案參加治療"],"answer":"C","correction":"","chapter":"M","extension":false,"context":null,"id":"111-2-28","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":29,"stem":"有關厭食症（anorexia nervosa）的臨床特徵敘述，下列何者最不適當？","options":["好發於年輕女性","強烈害怕體重增加或變胖","臨床上常見合併思覺失調症","限制攝取身體所需能量"],"answer":"C","correction":"","chapter":"O","extension":true,"context":null,"id":"111-2-29","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":30,"stem":"有關與神經障礙症兒童溝通，下列何者最不適當？","options":["簡短具體的結構性語句","初次評估必須運用身體接觸技巧","避免太抽象的語句","強調正向的回饋"],"answer":"B","correction":"","chapter":"O","extension":false,"context":null,"id":"111-2-30","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":31,"stem":"針對譫妄病人的護理措施，下列何者正確？","options":["限制飲水，以減少尿失禁情形","環境布置多元豐富，以增加感官刺激","出現睡眠紊亂時，應優先給予安眠藥物幫助入睡","溝通時應簡短扼要，重複告知人事時地物的訊息"],"answer":"D","correction":"","chapter":"L","extension":false,"context":null,"id":"111-2-31","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":32,"stem":"有關老年精神病人的藥物治療，下列敘述何者最適當？","options":["第二代抗精神病藥物較第一代藥物不會引發老年人的錐體外徑症候群","使用三環抗憂鬱劑治療老人憂鬱症，較不會出現心血管方面的副作用","情緒穩定劑有嚴重的副作用，不建議老年躁症病人使用","老年病人使用抗精神病藥物，應從高劑量開始，以增加藥物療效"],"answer":"A","correction":"","chapter":"E","extension":false,"context":null,"id":"111-2-32","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":33,"stem":"慢性思覺失調症病人，於急性病房出院後，轉介至社區復健中心接受工作技能訓練。以三級預防概念來看，「社區復健中心」是屬於何種層級的預防性服務範疇？","options":["初級預防","次級預防","三級預防","危機處置"],"answer":"C","correction":"","chapter":"P","extension":false,"context":null,"id":"111-2-33","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":34,"stem":"有關社區心理衛生的敘述，下列何者最適當？","options":["社區心理衛生的工作完全仰賴社區健康服務中心執行","醫院與社區的銜接是社區心理衛生工作不可或缺的一環","社區心理衛生乃以社區沒有精神疾病為目標","社區心理衛生乃以生物醫學治療模式為主要介入模式"],"answer":"B","correction":"","chapter":"P","extension":false,"context":null,"id":"111-2-34","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":35,"stem":"根據 DSM-5 診斷準則，智能不足嚴重度的分類，下列何者最不適當？","options":["依據智力測驗分數區分","依據適應功能做區分","嚴重度分為輕、中、重以及極重度","智力與適應功能缺損在發展期間發生"],"answer":"A","correction":"","chapter":"O","extension":false,"context":null,"id":"111-2-35","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":36,"stem":"下列何者屬於社區心理衛生工作的初級預防？","options":["轉介精神病人至社區復健機構","提供社區民眾心理衛生教育","提供康復期精神病人職能訓練","提高慢性精神病人服藥順從度"],"answer":"B","correction":"","chapter":"P","extension":false,"context":null,"id":"111-2-36","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":37,"stem":"在精神護理之家的護理人員以住民為中心，提供連續性、持續性的照顧，於其角色功能，下列何者正確？①醫療疾病診斷者 ②聯繫者 ③策畫者 ④協調者 ⑤個案管理者","options":["僅①②③","僅②③④","①③④⑤","②③④⑤"],"answer":"D","correction":"","chapter":"P","extension":false,"context":null,"id":"111-2-37","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":38,"stem":"陳女士，診斷為思覺失調症，因擅自停藥致病情復發，已入院治療一個月，預計下週辦理出院，有關出院準備的護理措施，下列何者最適當？","options":["要求家屬完全負起監督病人服藥的責任","安排病人接受職業訓練，出院後謀生","教導家屬凡事皆予代勞，以預防病人再度發病","引導病人與家屬了解精神疾病規則服藥的重要性"],"answer":"D","correction":"","chapter":"P","extension":false,"context":null,"id":"111-2-38","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":39,"stem":"護理人員與精神病人會談時，常用的治療技巧，下列何者正確？①全神貫注地傾聽 ②儘量不要使用 「為什麼」的問句 ③運用面質技巧盡速建立護病關係 ④運用澄清的技巧了解病人的想法","options":["①②③","①②④","①③④","②③④"],"answer":"B","correction":"","chapter":"D","extension":false,"context":null,"id":"111-2-39","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":111,"nth":2,"num":40,"stem":"有關慢性精神病人四段七級健康促進模式的主要策略，下列何者正確？","options":["第一級策略為健康促進、急性精神症狀控制","第三級策略為居家護理、社區小作手方案","第五級策略為健康檢查、吸菸嚼檳榔等高風險族群篩檢","第六級策略為轉介居家治療與精神長照機構"],"answer":"D","correction":"","chapter":"P","extension":false,"context":null,"id":"111-2-40","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2022&e=111110"},{"year":112,"nth":1,"num":1,"stem":"中華民國精神衛生護理學會致力於推展下列那些專業認證或甄審？①精神衛生護理師 ②社區精神衛生護理能力鑑定 ③精神衛生臨床護理專家 ④精神科專科護理師","options":["僅①②③","僅②③④","僅①③④","①②③④"],"answer":"A 或 D 或 AD","correction":"第1題答Ａ或Ｄ或AD者均給分。","chapter":"A","extension":false,"context":null,"id":"112-1-1","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":2,"stem":"提出個體之人際關係不良會帶來焦慮反應的是那位學者？","options":["榮格（Jung）","阿德勒（Adler）","馬斯洛（Maslow）","沙利文（Sullivan）"],"answer":"D","correction":"","chapter":"C","extension":false,"context":null,"id":"112-1-2","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":3,"stem":"對於嚴重精神病人的強制鑑定與住院治療是精神衛生法的重要基本精神之一，下列敘述何者正確？","options":["因是強制鑑定與住院，並不需要對嚴重精神病人解釋需要強制性約束病人的理由","本島或離島地區，強制鑑定只需交由一位以上直轄（市）、縣（市）主管機關指定之專科醫師進行即可","強制住院雖違反精神病人自主權，但有傷害他人或自己之虞者，皆可通知當地主管機關協助強制鑑定與住院","基於憲法所保障的人身自由權利，對於嚴重精神病人可進行強制鑑定，若病人無法接受或拒絕住院治療，不能強制病人住院"],"answer":"C","correction":"","chapter":"A","extension":false,"context":null,"id":"112-1-3","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":4,"stem":"護理人員可參與精神病人與家屬的相關研討會或會議，協助與鼓勵病人與家屬爭取該有的福利與權益，甚至在國家制定相關精神衛生法案與政策時，提供有利於病人與家屬的訊息給相關機構。此時精神衛生護理人員所表現的是那一個角色？","options":["代言者","決策者","轉介者","教育者"],"answer":"A","correction":"","chapter":"A","extension":false,"context":null,"id":"112-1-4","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":5,"stem":"有關精神疾病與神經傳導物質失調之因素假說，下列敘述何者正確？","options":["思覺失調症負性症狀與多巴胺（dopamine）濃度過高有關","躁症發作與兒茶酚胺（catecholamine）過度分泌有關","憂鬱症與血清素（serotonin）分泌過高有關","焦慮症與 γ-氨基丁酸（γ-Aminobutyric acid, GABA）分泌過多有關"],"answer":"B","correction":"","chapter":"C","extension":false,"context":null,"id":"112-1-5","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":6,"stem":"有關電氣痙攣療法之敘述，下列何者最適宜？","options":["可使憂鬱症病人的血清素與正腎上腺素濃度下降","恐慌症是電氣痙攣療法的最主要適應症","單側式電極片放置於優勢大腦額顳葉交接處","治療前病人須午夜後禁食及簽署同意書"],"answer":"D","correction":"","chapter":"E","extension":false,"context":null,"id":"112-1-6","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":7,"stem":"有關電氣痙攣治療（electroconvulsive therapy, ECT）之併發症，主要為下列何項？①頭痛 ②腦出血 ③呼吸暫停 ④短暫記憶喪失","options":["①②③","①②④","①③④","②③④"],"answer":"C","correction":"","chapter":"E","extension":false,"context":null,"id":"112-1-7","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":8,"stem":"有關情緒穩定劑 Valproic Acid（Depakine®）的敘述，下列何者正確？","options":["主要用於預防鬱症的治療","常見皮膚紅疹的過敏反應，但少有體重增加的副作用","其穩定情緒之作用機轉為增加抑制性神經傳導物質 GABA 的濃度","有效成人每日劑量約 500 mg，且血中濃度需達 1.5～2.0 μg/L"],"answer":"C","correction":"","chapter":"E","extension":false,"context":null,"id":"112-1-8","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":9,"stem":"協助病人規則服用 Lithium Carbonate，下列措施何者最不適宜？","options":["告知病人不規則服藥會增加疾病復發率","鼓勵病人大量喝水以改善藥物副作用","說明疾病病因、症狀、藥物作用及副作用","鼓勵家屬參與病人藥物治療"],"answer":"B","correction":"","chapter":"E","extension":false,"context":null,"id":"112-1-9","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":10,"stem":"依據 DSM-5 診斷準則，有關思覺失調症（Schizophrenia）診斷標準的描述，下列何者正確？","options":["至少有一項必須為負性精神症狀","精神症狀活躍至少持續出現 3 個月以上","社會功能顯著比發病前降低","物質濫用是造成疾病的主要因素"],"answer":"C","correction":"","chapter":"H","extension":false,"context":null,"id":"112-1-10","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":11,"stem":"有關認知行為治療步驟的敘述，下列何者最不適宜？","options":["協助個案了解其負向想法，如何影響他的情緒狀態與行為反應","找出證據來證實個案的想法，是沒有根據或與真實情況不相符","了解個案的深層經驗結構，尊重及保護個案的存在的真實性","找出影響個案產生負向想法的內在錯誤信念或假設，並加以修正"],"answer":"C","correction":"","chapter":"F","extension":false,"context":null,"id":"112-1-11","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":12,"stem":"有關團體治療的敘述，下列何者最適宜？","options":["團體的組成人數以 3～5 人為最佳","成員間的凝聚力是進行團體治療的重要因子","同質性團體比異質性團體好","封閉性團體比開放性團體好"],"answer":"B","correction":"","chapter":"F","extension":false,"context":null,"id":"112-1-12","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":13,"stem":"有關行為治療的運用，下列何者最適宜？","options":["依病房管理方便，建立增強物","依醫療需求訂定行為治療計畫","與個案簽訂契約，不需要徵求家屬同意","個案行為治療的執行，需醫療團隊的合作"],"answer":"D","correction":"","chapter":"F","extension":false,"context":null,"id":"112-1-13","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":14,"stem":"陳先生在住院期間，與多位病人有衝突，且多次出手攻擊。在訂定行為治療時，下列何項措施最適宜？","options":["與病人共同討論","依病房管理原則訂定","由護理師獨立規劃執行","僅需家屬同意"],"answer":"A","correction":"","chapter":"F","extension":false,"context":null,"id":"112-1-14","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":15,"stem":"陳先生診斷為思覺失調症，有嚴重幻聽干擾，時而聽見有人在稱讚他，時而又在指責他，導致他情緒起伏不定，因而多數時間都獨自躺床與幻聽對話。下列何項護理措施最適宜？","options":["提供病人耳塞，讓他聽不到幻聽就好","傾聽病人描述及比較幻聽的內容與改變","每天更換不同護理師，提供不同刺激轉移他的注意力","提供單人房，以免他的對話干擾到其他病人"],"answer":"B","correction":"","chapter":"H","extension":false,"context":null,"id":"112-1-15","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":16,"stem":"趙女士，身高 165 公分，診斷為憂鬱症，近 2 週食慾不佳，每餐只喝少許果汁，體重從 55 公斤降至 45 公斤。依據上述症狀，何者為最適宜的護理診斷？","options":["睡眠型態紊亂","潛在危險性對自己的暴力行為","營養不均衡：少於身體需要","潛在危險性對他人的暴力行為"],"answer":"C","correction":"","chapter":"B","extension":false,"context":null,"id":"112-1-16","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":17,"stem":"陳先生，診斷為雙相情緒障礙症，住院期間不斷投書給院長，對病房設施提出許多建議。下列何項護理措施最適宜？","options":["向院長解釋陳先生的疾病狀況","協助陳先生達成所提出的建議","肯定陳先生的投書行為","和陳先生討論，了解其行為"],"answer":"D","correction":"","chapter":"I","extension":false,"context":null,"id":"112-1-17","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":18,"stem":"有關思覺失調症病人之負性精神症狀，下列何者最適切？","options":["幻覺","動作遲緩","妄想","怪異行為"],"answer":"B","correction":"","chapter":"H","extension":false,"context":null,"id":"112-1-18","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":19,"stem":"林先生躁症發作（ManicEpisode）住急性病房，因為發燒被安置於隔離室觀察，林先生頻頻要求出隔離室，下列那些護理處置最適宜？①設限：你現在發燒要觀察，暫時不能出隔離室 ②拖延：不予理會、不回應 ③給予部分接受：我幫你量體溫，依據體溫狀況再決定 ④要求頻率太高，改為約束， 避免出隔離室","options":["①②③","②③④","僅①③","僅②④"],"answer":"C","correction":"","chapter":"I","extension":false,"context":null,"id":"112-1-19","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":20,"stem":"李小姐，因鬱症發作（Major Depressive Episode）住院，每天均表情愁苦、暗自垂淚。護理師問李小姐：「如果以 0 分到 10 分作評量，0 分是最低落，你目前是幾分？」李小姐回答 0 分。請問護理師正在執行下列何項護理評估？","options":["智能層面的思考內容評估","心理防衛機轉的評估","情緒的客觀評估","心情的主觀評估"],"answer":"D","correction":"","chapter":"B","extension":false,"context":null,"id":"112-1-20","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":21,"stem":"趙小姐診斷為思覺失調症，以下針對思覺失調症的敘述，何者正確？","options":["此困擾是起因於物質使用或身體病況的生理效應","疾病症狀持續至少 4 個月，即可診斷為思覺失調症","1 個月內至少出現妄想、幻覺或胡言亂語症狀","思覺失調症的診斷主要依據負性症狀為主軸"],"answer":"C","correction":"","chapter":"H","extension":false,"context":null,"id":"112-1-21","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":22,"stem":"有關焦慮病人的護理評估，下列何者適宜？①焦慮是一種精神疾患，不須注重生理層面評估 ②護理人員應從病人語言及非語言訊息評估情緒問題 ③評估病人認知層面，有助於了解焦慮的程度 ④評估病人靈性層面，有助於了解病人因應行為的來源","options":["①②③","①②④","①③④","②③④"],"answer":"D","correction":"","chapter":"B","extension":false,"context":null,"id":"112-1-22","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":23,"stem":"謝女士因恐慌症（Panic Disorder）入院，今早開始感覺心跳加速、呼吸困難、頭暈、胸悶，前去向護理師求助，下列護理處置何者最為優先？","options":["提醒謝女士不要誇大解釋身體不適的症狀","安撫謝女士此為恐慌發作的前兆，要學習與症狀共存","詳細詢問所有可能引發謝女士恐慌發作的原因","與謝女士一起進行呼吸放鬆，必要時給予紙袋"],"answer":"D","correction":"","chapter":"J","extension":false,"context":null,"id":"112-1-23","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":24,"stem":"有關中度焦慮的照護原則，下列何者最適宜？","options":["觀察並辨識病人不同焦慮程度的表現","告訴病人焦慮是多餘且過分的","安排病人學習挑戰新的活動","安檢後執行保護性約束"],"answer":"A","correction":"","chapter":"J","extension":false,"context":null,"id":"112-1-24","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":25,"stem":"有關強迫性人格障礙症的臨床表現，下列敘述何者最適切？","options":["缺乏彈性的行為模式","能夠反思自己的行為","常伴隨有宗教妄想","喜歡從事冒險活動"],"answer":"A","correction":"","chapter":"N","extension":false,"context":null,"id":"112-1-25","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":26,"stem":"根據 DSM-5 診斷準則，人格障礙症（General Personality Disorder）的描述，下列何者最不適宜？","options":["會表現在認知、情感、人際功能或是衝動控制","最早可追溯到成人晚期才顯現","持久，無彈性，遍及廣泛的個人及社會狀況","會引起社會、職業或其他重要領域功能的減損"],"answer":"B","correction":"","chapter":"N","extension":false,"context":null,"id":"112-1-26","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":27,"stem":"有關物質使用障礙症的治療原則中，下列敘述何者錯誤？","options":["在安非他命中毒的急性期時，治療包含洗胃、給與維生素 C 以酸化尿液，助安非他命排出體外","利用制癮劑（Disulfiram），使物質使用障礙症病人在使用物質時感到不舒服，而減少物質使用","美沙冬（Methadone），因其採口服，目前作為海洛因替代藥物，減少靜脈注射藥物及共用針頭所引起的疾病感染","長期飲酒導致威尼克氏腦病變（Wernicke’s encephalopathy），可口服或注射維生素 C 治療"],"answer":"D","correction":"","chapter":"M","extension":false,"context":null,"id":"112-1-27","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":28,"stem":"有關物質使用障礙症的生理層面護理措施，下列何者較不適宜？","options":["監測生命徵象與戒斷症狀","提供安全的環境","儘可能協助病人日常生活自我照顧","維持營養與水分、電解質的平衡"],"answer":"C","correction":"","chapter":"M","extension":false,"context":null,"id":"112-1-28","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":29,"stem":"有關智能不足的治療原則與預後，下列何者正確？","options":["治療目標應設定在維持現有能力","藥物為主要的治療方式，用於增加個案智能","重度智能不足兒童若接受妥善教育，其成年後可能會具有職業技能","智能不足兒童仍可能出現精神症狀"],"answer":"D","correction":"","chapter":"O","extension":false,"context":null,"id":"112-1-29","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":30,"stem":"下列有關厭食症（Anorexia nervosa）之敘述，何者錯誤？","options":["好發於年輕女性","強烈害怕發胖，拒絕維持正常體重","常用抗精神病藥物 Haloperidol 來改善症狀","常合併憂鬱、焦慮等症狀"],"answer":"C","correction":"","chapter":"O","extension":true,"context":null,"id":"112-1-30","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":31,"stem":"有關提供老年人睡眠問題的護理指導，下列何者錯誤？","options":["前一天失眠，白天需要多臥床休息","可以考慮以藥物輔助睡眠","只要自覺白天精神還不錯，偶爾失眠不需過度擔心","有計畫地安排白天的活動"],"answer":"A","correction":"","chapter":"L","extension":false,"context":null,"id":"112-1-31","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":32,"stem":"與老年精神病人溝通時，下列何者最適宜？","options":["多運用身體接觸來溝通","溝通時要簡潔快速","一次只談一個問題","避免直視老人，減少威脅感"],"answer":"C","correction":"","chapter":"L","extension":false,"context":null,"id":"112-1-32","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":33,"stem":"有關災難照護中資源保護理論，下列敘述何者最適宜？","options":["可分為物件資源、情境資源、個人特性資源、能量資源等四類","持久的個人特性、性別、種族、性格等因素，屬於社會資源","個人所擁有的房子、車子等物件，屬於能量資源","社會支持與正向的家庭關係，屬於內在心理的個人資源"],"answer":"A","correction":"","chapter":"G","extension":false,"context":null,"id":"112-1-33","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":34,"stem":"預防心理健康問題的發生，是屬於精神衛生預防概念的那一級工作？","options":["初級預防","次級預防","三級預防","四級預防"],"answer":"A","correction":"","chapter":"P","extension":false,"context":null,"id":"112-1-34","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":35,"stem":"護理師對病人執行身體約束處置時，應注意下列那些事項？①口水多的病人，應維持側躺 ②約束超過 2 小時應為病人翻身 ③若約束前注射 Haloperidol，應密切觀察血壓變化 ④病人通常抗拒約束，不一定要說明約束的原因 ⑤約束後應讓病人休息，不宜再與個案會談","options":["①②③","①③⑤","②③④","②④⑤"],"answer":"A","correction":"","chapter":"G","extension":false,"context":null,"id":"112-1-35","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":36,"stem":"在急診室有關藥物使用障礙症（藥物成癮）最常見的問題，下列敘述何者錯誤？","options":["海洛因戒斷症狀，如肌肉痙攣、骨頭痛","譫妄狀態","急性精神病","夢遊"],"answer":"D","correction":"","chapter":"M","extension":false,"context":null,"id":"112-1-36","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":37,"stem":"有關隔離與約束的醫囑，不包含下列何者？","options":["方式","病人的意願","起訖時間","理由"],"answer":"B","correction":"","chapter":"G","extension":false,"context":null,"id":"112-1-37","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":38,"stem":"有關社區中慢性精神病人罹患代謝症候群的生理健康監測，不包括下列何者？","options":["高尿酸","高血壓","高血糖","高血脂"],"answer":"A","correction":"","chapter":"E","extension":false,"context":null,"id":"112-1-38","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":39,"stem":"有關避免慢性精神病病人機構化的護理措施，下列何者最適宜？","options":["為了安定病人的情緒，活動應該規律化，減少改變","帶領病人外出，一定要集體行動，以免發生危險","讓病人定時排隊吃藥，以免忘記服藥","提供多樣化的生活功能訓練，強化病人適應能力"],"answer":"D","correction":"","chapter":"P","extension":false,"context":null,"id":"112-1-39","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":40,"stem":"鼓勵精神病人重返社區後，最可能產生的影響為何？","options":["病人容易再次發病或再住院","病人易形成遊民問題","病人易成為社會危險分子","家屬照護負荷增加"],"answer":"D","correction":"","chapter":"P","extension":false,"context":null,"id":"112-1-40","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":55,"stem":"下列何者屬於家庭情境性危機？①失業 ②事故傷害 ③中頭彩 ④空巢期","options":["僅①②","僅③④","僅①②③","僅①②④"],"answer":"C","correction":"","chapter":"G","extension":false,"context":null,"id":"112-1-55","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":68,"stem":"設置免費注射器與回收盒及保險套供應箱，是屬於三段五級預防的那一層次？","options":["初段第一級預防","初段第二級預防","次段第三級預防","次段第四級預防"],"answer":"B","correction":"","chapter":"M","extension":false,"context":null,"id":"112-1-68","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":72,"stem":"王老先生因為失能遷居入住護理之家，關於遷移壓力症候群之照護措施，下列敘述何者較不適宜？","options":["每日安排不同照顧者，增加適應性","提供入住護理之家前之準備","鼓勵家人、親友經常探望","提供日常生活活動選擇，增加自主性"],"answer":"A","correction":"","chapter":"L","extension":false,"context":null,"id":"112-1-72","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":1,"num":79,"stem":"社區護理師家訪過程，失智症個案王老先生反覆問：「小姐請問你是誰？叫什麼大名？」護理師應採何種應對方式最適宜？","options":["不用正面回答，這是疾病特性之一","對話過程，多次做簡短自我介紹","請個案將護理師姓名背起來，當他問時，反問他","告知名字不是重要議題，應先關注疾病問題"],"answer":"B","correction":"","chapter":"L","extension":false,"context":null,"id":"112-1-79","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112030"},{"year":112,"nth":2,"num":1,"stem":"有關精神衛生護理人員角色功能的敘述，下列何者正確？","options":["社區照護服務常採用個案管理者（Case Manager）","個案管理者只有護理師可擔任","功能性護理是精神科病房普遍的照護方式","護理計畫不必由主責護理師（Primary Nurse）擬定"],"answer":"A","correction":"","chapter":"A","extension":false,"context":null,"id":"112-2-1","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":2,"stem":"某精神科醫師在門診時，暗示病人有新藥的臨床試驗計畫，藥效比較好，病人基於對醫師的信任並認為新藥的治療效果較佳，同意簽人體試驗同意書，下列敘述何者正確？","options":["醫師行為並未違反醫療倫理，因為醫師是為病人著想，病人應該尊重專業","醫師行為並未違反醫療倫理，因為醫療需要進步，應要有病人參與臨床試驗","醫師行為違反醫療倫理，因為並未清楚告知參與新藥之可能風險","醫師行為違反醫療倫理，因為臨床醫師不能進行人體臨床試驗計畫"],"answer":"C","correction":"","chapter":"A","extension":false,"context":null,"id":"112-2-2","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":3,"stem":"將自己內在無法接受的想法、慾望或衝動，歸咎成他人，讓自己減少一份威脅、危險，同時也增加一份保護的作用，此最可能為下列何種心理防衛機轉？","options":["外射（projection）","合理化（rationalization）","認同（identification）","反向行為（reaction formation）"],"answer":"A","correction":"","chapter":"C","extension":false,"context":null,"id":"112-2-3","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":4,"stem":"有關鋰鹽的敘述，下列何者正確？","options":["每日治療劑量之鋰鹽，建議分成 2～3 次服用","藥物主要由肝臟代謝，服藥階段須注意病人肝功能","急性躁期的血中藥物濃度建議維持在 0.6～1.0 mEq/L","濃度超過 4 mEq/L，須停藥與補充水分，但不建議透析治療"],"answer":"A","correction":"","chapter":"E","extension":false,"context":null,"id":"112-2-4","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":5,"stem":"有關抗精神病藥物的敘述，下列何者正確？","options":["抗精神病藥力效果越強者，錐體外徑症候群作用越明顯","抗精神病藥力效果越強者，自主神經系統副作用越明顯","抗精神病藥物強度越強者，建議的每日口服治療劑量就越高","抗精神病藥物作用越強者，其鎮靜作用強度也是越強"],"answer":"A","correction":"","chapter":"E","extension":false,"context":null,"id":"112-2-5","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":6,"stem":"陳女士，35 歲，診斷雙相情緒障礙症，護理師在詢問家族病史中得知此次是陳女士首次發病，她的母親也是雙相情緒障礙症的病人，依病因模式，最符合以下何項病因因素？","options":["潛在因素（predisposing factor）","促發因素（precipitating factor）","續存因素（perpetuating factor）","預後因素（prognostic factor）"],"answer":"A","correction":"","chapter":"C","extension":false,"context":null,"id":"112-2-6","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":7,"stem":"吳先生，40 歲，診斷情感思覺失調症（Schizoaffective Disorder）。護理師問他喜歡從事什麼休閒活動， 吳先生回答說：「我喜歡游泳，勇於認錯，知錯能改，善莫大焉，醃肉好吃，但太鹹，我不能吃，因為我有高血壓。」吳先生有以下那一項症狀？","options":["言語迂迴（circumstantiality）","答非所問（irrelevant answer）","語無倫次（incoherence）","音韻連結（clang association）"],"answer":"D","correction":"","chapter":"C","extension":false,"context":null,"id":"112-2-7","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":8,"stem":"護理師展現同理心（empathy），下列描述何者最適切？","options":["完全融入病人的情緒中","不應表露自己的感受給對方","積極傾聽","不須探索病人的潛在需求"],"answer":"C","correction":"","chapter":"D","extension":false,"context":null,"id":"112-2-8","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":9,"stem":"依據卡普蘭（Caplan）危機理論的敘述，下列何者較適切？","options":["危機是事件本身，與個案情緒反應無關","危機形成和個案的因應機轉（coping mechanism）無關","個案在崩潰期，最常使用慣有的解決問題方法來因應","當危機問題持續未解決，升高的焦慮可能會導致個人崩潰"],"answer":"D","correction":"","chapter":"G","extension":false,"context":null,"id":"112-2-9","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":10,"stem":"下列何項為 BZD 類抗焦慮藥物？","options":["zolpidem（Stilnox®）","lorazepam（Ativan®）","estazolam（Eurodin®）","flunitrazepam（Rohypnol®）"],"answer":"B","correction":"","chapter":"E","extension":false,"context":null,"id":"112-2-10","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":11,"stem":"治療過程中，治療者提供無條件正向關懷與接納，強調人類成長和自我實現的潛能，此為下列那一種治療法？","options":["心理分析治療法（Psychoanalysis Therapy）","行為治療法（Behavioral Therapy）","理情治療法（Rational-Emotive Therapy）","個人為中心式治療法（Person-Centered Therapy）"],"answer":"D","correction":"","chapter":"F","extension":false,"context":null,"id":"112-2-11","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":12,"stem":"張小姐，診斷為妄想症，因懷疑學校同事向校長告狀阻礙其升遷，而有頻繁投訴教育部及謾罵同事等行為，由家屬陪同住院治療。下列護理措施，何者最適切？","options":["同理其妄想所導致的內心感受","協助聯絡教育部，以建立信任感","面質其妄想內容，告知非事實","聯絡學校同事，以釐清事實"],"answer":"A","correction":"","chapter":"H","extension":false,"context":null,"id":"112-2-12","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":13,"stem":"下列有關精神疾病盛行率的敘述，何者正確？","options":["物質使用障礙症是女性最普遍的精神疾病","自閉症類群障礙症的盛行率男性和女性大約相當","思覺失調症的盛行率男性和女性大約相當","雙相情緒障礙症的盛行率男性大於女性"],"answer":"C","correction":"","chapter":"C","extension":false,"context":null,"id":"112-2-13","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":14,"stem":"個別心理治療的主要目的與原則，適當的措施包括下列那些項目？①鼓勵病人自我表露 ②修正阻礙改變的阻力 ③協助了解疾病診斷 ④提供社區就業資訊","options":["①②","②③","③④","①④"],"answer":"A","correction":"","chapter":"F","extension":false,"context":null,"id":"112-2-14","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":15,"stem":"精神科急性病房為維持治療性的硬體環境，須符合下列那項原則？","options":["禁止擺設私人物品，以維持環境的一致性","為病人安全，病房不得裝設窗簾","為維護病人隱私，保護室不應設置玻璃窗","設置公共電話，以供病人對外聯繫之用"],"answer":"D","correction":"","chapter":"F","extension":false,"context":null,"id":"112-2-15","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":16,"stem":"有關家庭治療的護理措施，下列何者最適宜？","options":["當下解決問題，不可安排家庭作業","不需要訂定目標","著重討論過去情境所發生的事物","促進有效的溝通"],"answer":"D","correction":"","chapter":"F","extension":false,"context":null,"id":"112-2-16","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":17,"stem":"劉先生診斷妄想症（Delusional Disorder），堅定地認為太太、兒子與鄰居們意圖要下毒害他，下列敘述何者正確？","options":["出現與現實生活有關的妄想","有明顯的怪異行為","與腦部功能無關","與人格特質無關"],"answer":"A","correction":"","chapter":"H","extension":false,"context":null,"id":"112-2-17","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":18,"stem":"護理師與憂鬱症病人護病關係的建立，下列何者正確？①同理病人的感受和想法 ②給予簡單且直接的訊息 ③採取督促方式陪伴病人 ④協助表達其想法和感覺","options":["①②③","①②④","①③④","②③④"],"answer":"B","correction":"","chapter":"D","extension":false,"context":null,"id":"112-2-18","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":19,"stem":"武先生，28 歲，診斷為雙相情緒障礙症，目前為躁症發作，渴望有女朋友，向護理師說：「你很漂亮， 我可以當你的男朋友。」下列何項護理措施最適宜？","options":["表明二人為護病關係","不予理會","「謝謝你的讚美」","「謝謝，我有男朋友了」"],"answer":"A","correction":"","chapter":"I","extension":false,"context":null,"id":"112-2-19","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":20,"stem":"雙相情緒障礙症（Bipolar Disorder）的治療原則，下列何項敘述不適切？","options":["情緒穩定劑穩定情緒起伏","可合併使用抗精神病藥物治療激躁症狀","認知行為治療找出不理性想法","輕躁症只需心理治療"],"answer":"D","correction":"","chapter":"I","extension":false,"context":null,"id":"112-2-20","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":21,"stem":"陳同學，18 歲，診斷為思覺失調症，父母擔心服藥會影響其學科考試成績。下列護理措施，何者最適切？","options":["告知家屬考試前可以先暫時停藥","引導家屬了解服藥的重要性","告知家屬症狀出現再服藥即可","教導家屬使用轉移注意力來代替藥物使用"],"answer":"B","correction":"","chapter":"H","extension":false,"context":null,"id":"112-2-21","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":22,"stem":"承上題，陳同學及父母擔心疾病又再復發，顯得焦慮不安。下列護理措施，何者最不適切？","options":["教導病人與疾病共存的技巧","教導病人壓力紓解的方法","教導家屬日夜督促病人準備考試的方法","教導家屬預防疾病復發的方法"],"answer":"C","correction":"","chapter":"H","extension":false,"context":{"num":21,"stem":"陳同學，18 歲，診斷為思覺失調症，父母擔心服藥會影響其學科考試成績。下列護理措施，何者最適切？","chapter":"H"},"id":"112-2-22","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":23,"stem":"邊緣型人格障礙症病人有可能將護理師理想化或是言詞貶損護理師，有關此臨床特徵的敘述，下列何項最適切？","options":["無法感受到對懲罰或是痛苦的恐懼","冷漠無情，不在乎傷害他人","強烈的自大以及對他人缺乏同理心","以全好和全壞二分法的觀點看待人際關係"],"answer":"D","correction":"","chapter":"N","extension":false,"context":null,"id":"112-2-23","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":24,"stem":"有關病人以身體症狀帶來附帶收穫（secondary gain）的敘述，下列何者最適切？","options":["病人能增加病識感及服藥意願","滿足病人依賴的需求，減輕需負的責任","病人的記憶力與定向感下降","病人能增加社會互動的意願"],"answer":"B","correction":"","chapter":"K","extension":false,"context":null,"id":"112-2-24","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":25,"stem":"陳先生，近三個月多次忽然間感到胸痛、心悸、發抖、透不過氣，失去現實感等症狀，可在幾分鐘後緩解，經各項身體檢查顯示並無生理疾病，但之後陳先生仍持續擔心症狀會再度發作並死亡。下列敘述何者為陳先生最可能的診斷？","options":["創傷後壓力症","恐慌症","廣泛性焦慮症","社交畏懼症"],"answer":"B","correction":"","chapter":"J","extension":false,"context":null,"id":"112-2-25","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":26,"stem":"王女士，36 歲，半年來經常感到坐立不安、肌肉緊繃、容易疲勞，入睡困難，總是過度擔心工作或家庭會發生問題。王女士最有可能的問題，為下列何者？","options":["慮病症","畏懼症","恐慌症","廣泛性焦慮症"],"answer":"D","correction":"","chapter":"J","extension":false,"context":null,"id":"112-2-26","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":27,"stem":"有關酒精使用障礙症，下列敘述何者錯誤？","options":["酒精主要在小腸吸收，若喝酒又喝水，將增加酒精在體內的吸收","酒精戒斷的個案在戒斷後，會產生酒精戒斷譫妄（delirium tremor）","常因營養不良及維生素 E 缺乏，而發生周圍神經病變","酒精戒斷症狀會出現焦慮、手抖增加、流汗等症狀"],"answer":"C","correction":"","chapter":"M","extension":false,"context":null,"id":"112-2-27","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":28,"stem":"鴉片類的物質其作用越短效，引起的戒斷症狀發作及持續時間的通則為何？","options":["引起的戒斷症狀越長愈強","引起的戒斷症狀越短愈強","引起的戒斷症狀越長愈輕微","引起的戒斷症狀越短愈輕微"],"answer":"B","correction":"","chapter":"M","extension":false,"context":null,"id":"112-2-28","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":29,"stem":"有關物質使用障礙症的護理措施中，下列何者較不適切？","options":["協助物質使用障礙症的病人，核心議題是其個人對於問題的覺察能力","增加個案的現實感，不要與個案爭辯其妄想內容，並同理其害怕、擔心","鼓勵病人使用否認或隔離的心理機轉，以逃避心理壓力","討論戒除的可行方法，協助訂定合適的目標，並評值其成效"],"answer":"C","correction":"","chapter":"M","extension":false,"context":null,"id":"112-2-29","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":30,"stem":"下列有關閱讀障礙（Dyslexia）之敘述，何者錯誤？","options":["理解文字有困難","通常因智力偏低，導致全面性的學習障礙","書寫表達錯誤","閱讀有錯誤"],"answer":"B","correction":"","chapter":"O","extension":false,"context":null,"id":"112-2-30","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":31,"stem":"在某幼稚園就讀大班的林小弟，平時表現良好，只是有些好動，最近眼睛眨個不停，嘴角不自主抽動， 甚至搖頭，頸部晃個不停，樣子十分難看，同學都開始嘲笑他。上述表現最可能為下列何者？","options":["智能不足（Intellectural Disabilities）","雙相情緒障礙症（Bipolar Disorder）","注意力不足／過動症（Attention-Deficit/Hyperactivity Disorders, ADHD）","妥瑞氏症（Tourette’s Disorder）"],"answer":"D","correction":"","chapter":"O","extension":false,"context":null,"id":"112-2-31","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":32,"stem":"關於譫妄及失智症，下列敘述何者最適切？","options":["譫妄病人症狀通常為漸進性發作","譫妄病人通常腦波正常，出現腦回萎縮、腦室擴大","失智症病人的意識狀態，經常日夜波動變化大","失智症初期會有立即性及短期記憶力障礙"],"answer":"D","correction":"","chapter":"L","extension":false,"context":null,"id":"112-2-32","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":33,"stem":"有關老年憂鬱症的敘述，下列何者最不適切？","options":["與血清素神經傳導物質分泌減少有關","會因中風、心血管疾病引發憂鬱症","盛行率常被低估","憂鬱症狀緩解時，須立即停藥"],"answer":"D","correction":"","chapter":"L","extension":false,"context":null,"id":"112-2-33","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":34,"stem":"江先生為思覺失調症病人，出院返家後，常干擾社區居民，但不至於傷害他人，家屬表示病人不願意配合服藥與規律返診，照顧困難。依此情境，最適合提供江先生下列何種精神醫療服務？","options":["強制住院治療","居家治療","精神護理之家","住宿型康復之家"],"answer":"B","correction":"","chapter":"P","extension":false,"context":null,"id":"112-2-34","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":35,"stem":"陳女士，有自殺病史，近一個月終日以淚洗面，並向家人表示不想活在世間，而被家人送至精神科接受住院治療。此時，針對陳女士的護理措施最優先的是：","options":["建立治療性人際關係","安排家屬與個案討論未來生活安置","提供安靜的環境，讓陳女士好好休息","對陳女士採取自殺防範措施"],"answer":"D","correction":"","chapter":"G","extension":false,"context":null,"id":"112-2-35","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":36,"stem":"有關災難護理的敘述，下列何者最不適切？","options":["救難人員也是災難後照護關懷的對象","「二度災難」是指為了申請各類補助而遭遇到的各種困難","要求災民回到事故現場參與情境暴露法治療","考慮災民的文化差異提供照護"],"answer":"C","correction":"","chapter":"G","extension":false,"context":null,"id":"112-2-36","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":37,"stem":"有關急性精神科病房暴力的敘述，下列何者最適切？","options":["口頭攻擊常是暴力行為的先兆","女性工作人員最常遭到病人的暴力攻擊","藥物處置是處理暴力行為最有效的方法","約束病人後，護理師至少每一小時評估一次病人情況"],"answer":"A","correction":"","chapter":"G","extension":false,"context":null,"id":"112-2-37","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":38,"stem":"社區精神復健中心的服務對象之收案條件，下列何者正確？","options":["個案符合精神疾病診斷且精神症狀穩定，可主動服藥及規律門診追蹤者","個案符合精神疾病診斷且精神症狀穩定，但症狀呈現慢性化，需生活照顧者","為了考量個案往返復健中心的安全，一定要有家屬接送","為推展業務，任何病人有職業功能之訓練需求，皆可以為收案對象"],"answer":"A","correction":"","chapter":"P","extension":false,"context":null,"id":"112-2-38","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":39,"stem":"王先生，診斷為思覺失調症，使用抗精神病藥物 clozapine（Clozaril®），用藥前體重、血壓及空腹血糖在正常範圍，第 8 週時體重上升 10%，第 12 週時血糖驗出 130 mg/dL，目前精神症狀及認知功能明顯改善，且已回到職場。下列敘述何者最適切？","options":["病人服用 clozapine 時，出現血糖高，不需過度緊張，也不需再追蹤處理","造成病人血糖高的因素與其年齡、運動程度、家族史有關，與藥物無關","clozapine 屬於第一代抗精神病藥物，導致代謝症候群的可能性低","病人精神症狀及認知功能已經改善，雖出現血糖問題，不宜驟然停藥"],"answer":"D","correction":"","chapter":"E","extension":false,"context":null,"id":"112-2-39","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":40,"stem":"承上題，王先生服用 clozapine 藥物時，下列何者為首要健康風險控制預防措施？","options":["營養、運動諮詢與追蹤代謝症候群相關數據","蛋白質控制之飲食管理","低鈉飲食之血壓控制","危機管理"],"answer":"A","correction":"","chapter":"E","extension":false,"context":{"num":39,"stem":"王先生，診斷為思覺失調症，使用抗精神病藥物 clozapine（Clozaril®），用藥前體重、血壓及空腹血糖在正常範圍，第 8 週時體重上升 10%，第 12 週時血糖驗出 130 mg/dL，目前精神症狀及認知功能明顯改善，且已回到職場。下列敘述何者最適切？","chapter":"E"},"id":"112-2-40","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":48,"stem":"調查社區失智症失能盛行率，最適合應用於下列何種情況？","options":["推估死亡率","評估死亡原因","探討致病因子","規劃醫療設備及人力"],"answer":"D","correction":"","chapter":"L","extension":false,"context":null,"id":"112-2-48","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":59,"stem":"護理師在社區關懷據點進行失智預防衛生教育計畫，下列執行過程順序，何者最適當？①擬訂目標 ②確認需求 ③規劃內容 ④執行計畫 ⑤評價成效","options":["①②⑤③④","②①③④⑤","③④②①⑤","⑤②①③④"],"answer":"B","correction":"","chapter":"L","extension":false,"context":null,"id":"112-2-59","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":2,"num":64,"stem":"社區護理師提供輕度失智家屬有關預防走失指紋捺印、瑞智學堂及失智家屬支持團體等資訊，請問社區護理師扮演下列何種角色？","options":["代言人","協調者","流行病學者","環境改變者"],"answer":"B","correction":"","chapter":"L","extension":false,"context":null,"id":"112-2-64","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112110"},{"year":112,"nth":3,"num":1,"stem":"依據交流分析論（Transactional Analysis）所提出的人類自我狀態（ego state），護理師習慣性的對病人說： 「為什麼你總是做錯，你應該……」、「你不可以……」，使得護病關係較為階層化，此為護理師下列何項自我狀態？","options":["父母型自我狀態（parent ego state）","兒童型自我狀態（child ego state）","成人型自我狀態（adult ego state）","交叉溝通型態（cross communication）"],"answer":"A","correction":"","chapter":"D","extension":false,"context":null,"id":"112-3-1","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":2,"stem":"病人對護理師說：「你對我真好，不像那個小夜班護理師，好兇喔！他還說你壞話……」，面對病人的分化性行為，護理師提供的護理原則，下列何者正確？①傾聽其想法及動機 ②保持中立的態度與其討論 ③隱藏此事，不必告訴其他護理人員 ④以就事論事的態度與其互動","options":["①②③","①②④","①③④","②③④"],"answer":"B","correction":"","chapter":"D","extension":false,"context":null,"id":"112-3-2","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":3,"stem":"施先生因症狀不穩而住院治療，他說：「我真的沒病，為什麼把我關起來？」，護理師使用同理心的技巧回應，下列何者最適宜？","options":["「其實很多病友也覺得自己沒病」","「你問過醫師為什麼來住院？」","「出院只是早晚的問題，別擔心」","「我了解，你覺得自己沒病，住院讓你感到委屈，不受尊重」"],"answer":"D","correction":"","chapter":"D","extension":false,"context":null,"id":"112-3-3","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":4,"stem":"從社區精神醫學的立場來看，下列何者為第一級的預防策略？","options":["心理健康講座","門診治療","危機處置","庇護工場的訓練"],"answer":"A","correction":"","chapter":"P","extension":false,"context":null,"id":"112-3-4","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":5,"stem":"33 歲病人，躁症發作，午餐時間未用餐，護理師去叫病人吃飯，病人說：「房市我最懂，臺北、新北和竹北我都有置產買房，你叫我吃飯，我就送你一間房。」護理師說：「謝謝，你先告訴我，你要坐在那裡吃午餐？」此時護理師所運用的溝通技巧，下列何項最適宜？","options":["提出觀察（making observation）","同理（empathy）","面質（confrontation）","集中話題（focusing）"],"answer":"D","correction":"","chapter":"D","extension":false,"context":null,"id":"112-3-5","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":6,"stem":"世界衛生組織（WHO）近年來重視精神健康領域，建議以「社區」為主，建立「精神健康」的三級預防體系，提供精神疾病復健所需的社會資源，下列常見的社區化照護模式，何者錯誤？","options":["自殺防治的高關懷服務","急性期住院之藥物治療","康復之家","職業重建訓練"],"answer":"B","correction":"","chapter":"P","extension":false,"context":null,"id":"112-3-6","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":7,"stem":"張先生因拿油漆潑鄰居，揚言同歸於盡，而被強制送醫，診斷為思覺失調症，在病房大聲說：「那個鄰居很可惡，故意把車停在我的車道上讓我出不去，我潑油漆只是給他們警告，又不會傷害他們，卻被抓來住院， 沒天理。」護理師運用同理心的技巧回應，下列何項最適宜？","options":["「總之，潑油漆是不對的行為」","「聽起來，你很生氣」","「先冷靜，我們等警察調查清楚」","「你太太有跟鄰居澄清，並無擋路之事」"],"answer":"B","correction":"","chapter":"D","extension":false,"context":null,"id":"112-3-7","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":8,"stem":"有關抗精神病藥物（antipsychotics）副作用之處理，下列何者正確？","options":["使用 propranolol（Inderal®）緩解類巴金森氏症副作用","以抗痙攣藥物，緩解急性肌張力不全副作用","以抗膽鹼藥物（anticholinergic drugs）緩解遲發性運動不能副作用","使用 biperiden（Akineton®）緩解靜坐不能的副作用"],"answer":"D","correction":"","chapter":"E","extension":false,"context":null,"id":"112-3-8","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":9,"stem":"有關電氣痙攣療法（ECT）的敘述，下列何者正確？","options":["治療時採用 150～300 伏特電流通過腦部 1 分鐘引發痙攣","通常是先產生陣發性痙攣，而後才出現強直性痙攣","用在雙相情緒障礙症急性躁期的病人，療效最佳","單側式 ECT，通常將電極片放在非優勢大腦的額顳交接處"],"answer":"D","correction":"","chapter":"E","extension":false,"context":null,"id":"112-3-9","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":10,"stem":"有關認知障礙症病人的特性，下列敘述何者正確？","options":["失智症病人通常會出現遠期記憶的問題","常使用虛談（confabulation）掩飾記憶障礙","柯氏性格量表能評估病人記憶受損情形","立即記憶障礙是指無法回憶近 1 星期的事"],"answer":"B","correction":"","chapter":"L","extension":false,"context":null,"id":"112-3-10","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":11,"stem":"病人主要服用的精神科藥物為 clozapine（Clozaril®），下列敘述何者正確？","options":["此藥最常見嚴重致命副作用是史蒂文強森症候群（Steven-Johnson syndrome）","用藥後，病人血糖會下降","病人停藥後，可立即停止抽血監測血球數","評估病人白血球下降的症狀"],"answer":"D","correction":"","chapter":"E","extension":false,"context":null,"id":"112-3-11","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":12,"stem":"有關情緒穩定劑 carbamazepine 的敘述，下列何者正確？","options":["常見副作用是輕微手抖或腸胃不適，但皮膚疹或複視很少出現","連續服用藥物 5 天後作用可達高峰，有效成人劑量約為 60～120 mg/day","發現病人黏膜潰爛，需確認是否為 Steven-Johnson syndrome（SJS）","因為具有明顯的腎毒性，用藥第 1～2 個月必須每週抽血監測腎功能"],"answer":"C","correction":"","chapter":"E","extension":false,"context":null,"id":"112-3-12","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":13,"stem":"28 歲男性病人，因嚴重精神病症狀，語無倫次及攻擊他人，連續注射 5 mg 的 haloperidol（Haldol®）達每天 20～30 mg，護理師發現他的生命徵象極不穩定、吞嚥困難、全身冒汗，對此抗精神病藥物惡性症候群， 下列何項敘述最適切？","options":["體溫降低","肌酸酐酶（creatine kinase）濃度會驟降","雖然生命徵象不穩定，但病人的意識都能維持清楚","建議立即停藥，並加上支持療法，例如補充體液"],"answer":"D","correction":"","chapter":"E","extension":false,"context":null,"id":"112-3-13","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":14,"stem":"李同學就讀高中三年級，日前媽媽生病過世，李同學因為失落、哀傷住進急性病房，護理師在住院過程提供支持性心理治療（supportive psychotherapy），下列有關支持性心理治療概念的描述，何者錯誤？","options":["為改善病人症狀","為提升個案的自尊","可強化李同學的自我功能","宜探討問題背後的原因"],"answer":"D","correction":"","chapter":"F","extension":false,"context":null,"id":"112-3-14","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":15,"stem":"林先生患第一型雙相情緒障礙症（Bipolar IDisorder）多年，當其在躁症發作時，很容易與人起衝突，而出現攻擊行為，下列護理措施何者正確？①將病人留在現場 ②鼓勵病人以言語表達其感受 ③必要時，帶入保護室隔離 ④以堅定口氣指示病人適當的行為","options":["①②③","①②④","①③④","②③④"],"answer":"D","correction":"","chapter":"G","extension":false,"context":null,"id":"112-3-15","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":16,"stem":"李同學，18 歲，第一次被診斷為第一型雙相情緒障礙症，護理師向李同學及家屬進行護理指導時，下列何者最適宜？","options":["病人功能會退化，需要長期的安置","發病年齡越晚，預後越差","需規律藥物治療，避免疾病再發作","服用鋰鹽時，血中濃度應維持在 1.5 mEq/L"],"answer":"C","correction":"","chapter":"I","extension":false,"context":null,"id":"112-3-16","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":17,"stem":"林同學，20 歲，上台報告時總是會極度恐懼或焦慮，也無法在公共場所用餐，平時會儘量避免與他人交談或互動。林同學最有可能的問題是下列何者？","options":["社交畏懼症（Social Phobia）","轉化症（Conversion Disorder）","選擇性不語症（Selective Mutism）","廣泛性焦慮症（Generalized Anxiety Disorder）"],"answer":"A","correction":"","chapter":"J","extension":false,"context":null,"id":"112-3-17","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":18,"stem":"葉先生，36 歲，診斷恐慌症，發作時感到喘不過氣、胸痛、四肢麻痺，在急診時大喊：「我覺得快死了！」， 下列護理師的處置，何者最適宜？","options":["「不會，你不會死，不用想太多，你現在太緊張了，這些都是正常的焦慮症狀」","「冷靜一下，好好地說清楚你發作時的感覺」","「請問你以前都怎麼處理這種情況？」","「你現在人在醫院，我們陪著你。你很安全」"],"answer":"D","correction":"","chapter":"J","extension":false,"context":null,"id":"112-3-18","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":19,"stem":"有關酒癮病人之敘述，下列何者正確？①停止喝酒後，戒斷症狀會在很短的時間內發生，且持續 5～7 天 ②酒精戒斷譫妄以聽幻覺為主 ③戒斷症狀包括：焦慮、厭食、失眠、顫抖等 ④常有營養不良和維他命 B 群缺乏的情形","options":["①②③","①③④","①②④","②③④"],"answer":"B","correction":"","chapter":"M","extension":false,"context":null,"id":"112-3-19","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":20,"stem":"出現柯沙寇夫症候群（Korsakoff’s syndrome）的酒精成癮者，其典型症狀為何？","options":["懷疑配偶不忠，嫉妒妄想","近期記憶力喪失","覺得一直聽到聲音，像是有人在命令他","流鼻水、發燒、流淚、打呵欠"],"answer":"B","correction":"","chapter":"M","extension":false,"context":null,"id":"112-3-20","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":21,"stem":"邵女士，67 歲，因車禍接受手術，在加護病房第二天出現混亂、慌張、不安、定向障礙之症狀，小夜班時不斷拉鈴要求出去，大夜班時跟護理師反映牆壁上有許多蟑螂。針對此譫妄（delirium）狀態，下列何項護理措施最適宜？","options":["儘可能採約束隔離措施，以免病人出現更混亂的行為","病人能參與定向感訓練，增進認知功能","增加感官刺激活動，以緩和病人緊張情緒","提供病人安全、安靜舒適的環境"],"answer":"D","correction":"","chapter":"L","extension":false,"context":null,"id":"112-3-21","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":22,"stem":"有關心理防衛機轉的敘述，下列何者正確？","options":["無意識抑制自己的內在衝動是壓抑作用（suppression）","以特定行為消除內心的焦慮是抵銷作用（undoing）","將原始的衝動壓抑到潛意識的層面是轉移作用（displacement）","將內在衝突藉由象徵性的身體症狀呈現是取代作用（substitution）"],"answer":"B","correction":"","chapter":"C","extension":false,"context":null,"id":"112-3-22","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":23,"stem":"社區心理衛生護理人員會主動關心社區中需要健康服務的民眾，利用工具與會談技巧，篩檢社區中的高危險群，以達早期發現的目的。此護理人員執行角色最符合下列何者？","options":["照顧提供者（care provider）","個案發現者（case finder）","諮詢者（consultant）","評值者（evaluator）"],"answer":"B","correction":"","chapter":"P","extension":false,"context":null,"id":"112-3-23","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":24,"stem":"有關社區精神心理衛生目的之敘述，下列何者最不適宜？","options":["提升病人生活適應","促進個人復元","由專業人員積極主導治療計畫","以病人的優勢取向，發展病人的因應能力"],"answer":"C","correction":"","chapter":"P","extension":false,"context":null,"id":"112-3-24","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":25,"stem":"林先生，60 歲，罹患思覺失調症已 40 年，目前無明顯精神症狀，自我照顧功能下降需他人協助生活照顧， 無其他家人可協助照料。依林先生之狀況，最適合安排下列何種精神醫療資源？","options":["社區心理衛生中心","日間留院","居家治療","精神護理之家"],"answer":"D","correction":"","chapter":"P","extension":false,"context":null,"id":"112-3-25","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":45,"stem":"職業衛生護理師發現某些作業員突有壓力大增、情緒不穩的現象。下列何項措施最不適當？","options":["評估員工身心壓力狀況","建議服用抗憂鬱藥物","進行異常個案追蹤管理","辦理壓力調適健康講座"],"answer":"B","correction":"","chapter":"G","extension":false,"context":null,"id":"112-3-45","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":112,"nth":3,"num":49,"stem":"張先生近來被子女發現會忘記一些日常事情，醫師診斷為輕型認知障礙症（Mild Neurocognitive Disorder）， 家人不放心他白天一人在家，共照個管師與個案和家人商議後，轉介他至其居住所在的巷弄據點，於是張先生每週有三個早上會自己騎車至據點活動與吃午餐。這樣的措施是屬於：","options":["初段預防的健康促進","次段預防的早期篩檢","次段預防的早期治療","三段預防的限制殘障"],"answer":"D","correction":"","chapter":"L","extension":false,"context":null,"id":"112-3-49","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2023&e=112180"},{"year":113,"nth":1,"num":1,"stem":"有關情感轉移（transference）的敘述，下列何者正確？","options":["是指病人將過去經驗的人物情感轉移到護理師","是指護理師將過去經驗的人物情感轉移到病人","對護病關係的建立絕對有不好的影響","是指護理師對病人有性幻想"],"answer":"A","correction":"","chapter":"D","extension":false,"context":null,"id":"113-1-1","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":2,"stem":"有關多巴胺（dopamine）傳導路徑理論與思覺失調症的關係，下列敘述何者最適切？","options":["興趣動機缺乏的症狀主要與結節—漏斗部多巴胺路徑有關","妄想幻覺的症狀主要與中腦—邊緣多巴胺路徑有關","類巴金森氏症狀主要與中腦—皮質多巴胺路徑有關","泌乳素上升的副作用主要與黑質—紋狀體多巴胺路徑有關"],"answer":"B","correction":"","chapter":"C","extension":false,"context":null,"id":"113-1-2","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":3,"stem":"有關家庭治療之敘述，下列何者最適切？","options":["鮑恩（Bowen）家庭治療理論中三角關係（triangles），僅存於夫妻或手足間","鮑恩（Bowen）家庭治療之目標是降低家庭成員分化程度","策略性（strategic）家庭治療以解決家庭溝通問題為導向","家庭治療並不處理家庭危機，僅提供諮商與行為修正"],"answer":"C","correction":"","chapter":"F","extension":false,"context":null,"id":"113-1-3","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":4,"stem":"李先生為憂鬱症病人，因工作不順遂，與同事發生嚴重爭執，由案妻陪同到醫院接受治療，下列何項溝通技巧最不適宜？","options":["主動傾聽","澄清","拓寬話題","批判"],"answer":"D","correction":"","chapter":"D","extension":false,"context":null,"id":"113-1-4","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":5,"stem":"有關認知行為治療的敘述，下列何者最適切？","options":["不處理壓力的生理反應","引導個案調整想法和行為","強調個案早期發展階段的問題","了解個案潛意識對人際關係的影響"],"answer":"B","correction":"","chapter":"F","extension":false,"context":null,"id":"113-1-5","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":6,"stem":"汪小姐剛入住急性精神科病房，覺得門把骯髒，都使用紙張包覆才願意轉動把手，下列何項護理措施最適宜？","options":["不給與紙張，強迫他適應觸摸門把","向他解說，拿紙張是不必要的","要他負責清洗病房的門把","提供他紙張，直到他的焦慮減輕"],"answer":"D","correction":"","chapter":"J","extension":false,"context":null,"id":"113-1-6","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":7,"stem":"有關日落症候群（sundown syndrome）較常見於何種疾患？","options":["失智症","恐慌症","雙相情緒障礙症","譫妄患者"],"answer":"A","correction":"","chapter":"L","extension":false,"context":null,"id":"113-1-7","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":8,"stem":"葉同學剛滿18歲，診斷為雙相情緒障礙症（bipolar disorder），媽媽非常不解的詢問護理師為什麼會這樣。關於疾病的生物病因，下列何項回答最為適切？","options":["受到 近日持續高溫的影響，待天氣轉涼即可改善","跟內分泌系統或神經傳導物質有關，需要藥物治療","跟家族遺傳無直接相關，媽媽不用太自責","鉛中毒是最常見的生物病因"],"answer":"B","correction":"","chapter":"C","extension":false,"context":null,"id":"113-1-8","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":9,"stem":"下列何項描述符合鬱症發作（major depressive episode）的診斷？","options":["主觀感受想法洶湧不止","憂鬱症狀須持續二週才能診斷","與是否造成社交、職業或其他功能缺損無關","可能失眠，不會嗜睡"],"answer":"B","correction":"","chapter":"I","extension":false,"context":null,"id":"113-1-9","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":10,"stem":"有關思覺失調症病人出現生活懶散、缺乏動機，下列何項護理措施最不適切？","options":["鼓勵建立每日作息表","對參與團體治療給予讚賞","與病人的互動保持真誠與公開","向病人保證藥物治療只是短暫的"],"answer":"D","correction":"","chapter":"H","extension":false,"context":null,"id":"113-1-10","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":11,"stem":"王小姐有被害妄想，一直擔心家人在食物中下毒，入院後仍不肯進食。下列何者是最優先的護理措施？","options":["請醫師立即插鼻胃管給予灌食","告知病人再不進食，要進保護室","請病人家屬準備伙食","協助病人自行採購包裝完整的食物"],"answer":"D","correction":"","chapter":"H","extension":false,"context":null,"id":"113-1-11","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":12,"stem":"有關思覺失調症病人常不規則服藥，下列何項出院藥物護理最不適切？","options":["評估家庭主要照顧者是誰","了解不服藥的原因","提供藥物相關資訊","返家後的藥物，可供家人自行選擇"],"answer":"D","correction":"","chapter":"E","extension":false,"context":null,"id":"113-1-12","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":13,"stem":"根據佛洛伊德學說，人格障礙病人在肛門期受到過度的管教約束，影響心性發展。以下何者為其日後的行為模式？","options":["對不同性別的父母產生性吸引","強烈地傾向追求愉悅、避免痛苦","行為傾向一板一眼、缺乏彈性","生活的大小事都要他人為其承擔責任"],"answer":"C","correction":"","chapter":"N","extension":false,"context":null,"id":"113-1-13","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":14,"stem":"有關恐慌症的敘述，下列何者最不適切？","options":["預期中的反覆發作","突發的恐懼會於幾分鐘內達最高峰","常見心悸、喘不過氣、胸痛等症狀","可能出現失真感、失自我感"],"answer":"A","correction":"","chapter":"J","extension":false,"context":null,"id":"113-1-14","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":15,"stem":"有關美沙冬（methadone）的敘述，下列何者正確？","options":["不會有呼吸抑制、欣快感和戒斷症狀","成癮性比海洛因低，戒斷症狀也比海洛因輕微","是一種替代療法，其治療主要是心理安撫作用","病人需終身服用"],"answer":"B","correction":"","chapter":"M","extension":false,"context":null,"id":"113-1-15","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":16,"stem":"李同學，12歲，對無法停止洗手行為，感到情緒低落並無自信，導致每次不停的洗手，即使手已經破皮仍繼續洗手。護理師建議李同學藉由玩自己最喜歡的小小兵玩具轉移注意力並練習不繼續洗手。此種照護處置是應用下列何種治療技巧？","options":["沙箱療法（sand body therapy）","非指引性治療（non-directive play）","暴露與反應阻止法（exposure and response prevention）","生理回饋（bio-feedback）"],"answer":"C","correction":"","chapter":"F","extension":false,"context":null,"id":"113-1-16","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":17,"stem":"有關物質使用障礙症成因之敘述，下列何者錯誤？","options":["成癮物質會直接活化酬償系統，產生愉悅感","同儕互相影響是使用成癮物質的因素之一","家庭功能失調是使用成癮物質的因素之一","與對成癮物質的認知無關，不會想戒除"],"answer":"D","correction":"","chapter":"M","extension":false,"context":null,"id":"113-1-17","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":18,"stem":"廖奶奶，84歲，獨居，三個月前經歷結縭60年的老伴過世，面帶愁容、不與人打招呼。廖奶奶向女兒表示自己不想再吃藥了，活著沒有意思。評估廖奶奶的精神健康狀況後，下列何者應為最優先的護理處置？","options":["了解廖奶奶對於伴侶離世的內心感受，協助抒發與轉移注意","進一步評估廖奶奶的自殺意念與計畫，防範自殺危險","陪伴廖奶奶透過緬懷過往記憶，重新找到價值與存活意義","儘快安排廖奶奶入住護理之家，提供緊急密切的生理照護"],"answer":"B","correction":"","chapter":"G","extension":false,"context":null,"id":"113-1-18","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":19,"stem":"承上題，廖奶奶經醫師建議入院治療，有關各項治療的敘述，下列何者最適當？","options":["透過哀傷輔導，可協助廖奶奶表達內心的感受","為改善廖奶奶憂鬱情緒，必須服用rivastigmine（Exelon®）","為防範廖奶奶自殺，護理師應密切觀察，每5分鐘提供探視","儘量要求廖奶奶參加所有治療活動，轉移其負面情緒"],"answer":"A","correction":"","chapter":"L","extension":false,"context":{"num":18,"stem":"廖奶奶，84歲，獨居，三個月前經歷結縭60年的老伴過世，面帶愁容、不與人打招呼。廖奶奶向女兒表示自己不想再吃藥了，活著沒有意思。評估廖奶奶的精神健康狀況後，下列何者應為最優先的護理處置？","chapter":"G"},"id":"113-1-19","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":20,"stem":"下列何者不屬於神經發展障礙症（neurodevelopmental disorders）的疾病？","options":["智能不足","自閉症類群障礙症","注意力不足／過動症","遺尿症"],"answer":"D","correction":"","chapter":"O","extension":false,"context":null,"id":"113-1-20","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":21,"stem":"孫先生於精神科病房出院後，規則服藥，病情穩定，但面臨經濟困境及就業需求。護理師為協助其發展經濟及就業，必須具有下列何項實務能力？","options":["建構自我","疾病管理","精神衛生需求評估","資源連結"],"answer":"D","correction":"","chapter":"P","extension":false,"context":null,"id":"113-1-21","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":22,"stem":"有關社區心理衛生工作之敘述，下列何者屬於第三級預防工作？","options":["加強門診治療功能","在里民中心辦理心理衛生講座","對社區中有高度自傷危險者給予危機處置","協助精神病人重返社區生活"],"answer":"D","correction":"","chapter":"P","extension":false,"context":null,"id":"113-1-22","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":23,"stem":"災難急性期運用安心團體（debriefing），下列敘述何者最適切？","options":["於創傷後三個月開始實施最適宜","治療者協助個案回顧、經歷並整合創傷之過程","是屬於精神分析類的支持性治療團體","進行結構式之駁斥、澄清、面質、結束等步驟"],"answer":"B","correction":"","chapter":"G","extension":false,"context":null,"id":"113-1-23","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":24,"stem":"有關精神護理之家的服務對象其收置條件，可包含下列何者？①精神症狀穩定且慢性化者 ②不需急性住院治療但需生活照顧者 ③需急性住院治療之年邁者、失智者 ④無家可歸的慢性精神病人","options":["僅③④","僅①②③","僅①②④","①②③④"],"answer":"C","correction":"","chapter":"P","extension":false,"context":null,"id":"113-1-24","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":25,"stem":"吳先生，因住院期間多次企圖割腕自殺，必須採取保護約束之措施。有關約束處置之敘述，下列何者最不適當？","options":["需有醫師開立醫囑，才能給予約束","至少每15分鐘探視病人一次","每2小時評估病人是否可以解除保護約束","應持續約束病人，直到自殺意念消失"],"answer":"D","correction":"","chapter":"G","extension":false,"context":null,"id":"113-1-25","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":40,"stem":"顧先生原為一家之主，因病辭職在家休養，現由妻子支撐全家開銷並成為家中主要經濟決策者，下列何者最符合其家庭權力類型？","options":["傳統權威型","情況權威型","分享權威型","讓步妥協型"],"answer":"B","correction":"","chapter":"F","extension":false,"context":null,"id":"113-1-40","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":41,"stem":"承上題，顧太太因身兼數種角色，自覺難以扮演好各個角色，此現象顯示顧太太出現下列何種角色情況？","options":["角色相稱","角色力竭","角色不一致","角色不互補"],"answer":"B","correction":"","chapter":"F","extension":false,"context":{"num":40,"stem":"顧先生原為一家之主，因病辭職在家休養，現由妻子支撐全家開銷並成為家中主要經濟決策者，下列何者最符合其家庭權力類型？","chapter":"F"},"id":"113-1-41","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":1,"num":47,"stem":"陳女士，喪偶，罹患中度失智症，與兒女同住但平日兒女需上班。下列何項長照服務應優先建議？","options":["社區關懷據點","喘息服務","老人公寓","日間照顧"],"answer":"D","correction":"","chapter":"L","extension":false,"context":null,"id":"113-1-47","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113030"},{"year":113,"nth":2,"num":1,"stem":"蕭女士，已婚，先生因失業長期酗酒。今日因細故酒後毆打蕭女士，致頭部受創，血流不止，由警察及社工護送至急診。下列護理措施何者最優先？","options":["協助申請醫療補助，以利經濟支援","協助向法院提出告訴","協助聘請律師，申請保護令","尋找適當空間，確保安全與隱私"],"answer":"D","correction":"","chapter":"G","extension":false,"context":null,"id":"113-2-1","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":2,"stem":"有關社區精神復健的照護重點，下列何者最不適切？","options":["促進病人的復元","提升病人的生活品質","主動給予病人藥物服用","提升病人參與治療計畫的能力"],"answer":"C","correction":"","chapter":"P","extension":false,"context":null,"id":"113-2-2","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":3,"stem":"李小姐，診斷為思覺失調症，主治醫師告知下星期要安排她出院返家，不料她面有難色，靜坐在大廳半小時。下列護理措施何者最適切？","options":["轉介心理師進行人格測驗","同理李小姐對出院的想法或感受","教導李小姐辦理出院的手續","向李小姐保證有困難可以再入院"],"answer":"B","correction":"","chapter":"P","extension":false,"context":null,"id":"113-2-3","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":4,"stem":"精神衛生工作的三級預防概念，下列何者屬於三級預防的工作內容？","options":["積極治療防止病症惡化","早期診斷，早期轉介，早期治療","於某社區衛生所舉辦一場壓力管理的衛生講座","協助病人回歸社區並提供可能的就業輔導資訊"],"answer":"D","correction":"","chapter":"P","extension":false,"context":null,"id":"113-2-4","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":5,"stem":"有關恐慌症的敘述，下列何者最適切？","options":["為器質性因素所引起的急性混亂","藥物治療以情緒穩定劑如鋰鹽為主","心理治療無助於改善病情","發作時應以病人安全為優先處置"],"answer":"D","correction":"","chapter":"J","extension":false,"context":null,"id":"113-2-5","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":6,"stem":"吳先生，25 歲，唸高中時出現幻聽、被害妄想，開始接受精神科治療，近三個月自行減藥，症狀越來越嚴重，他告訴護理師：「我知道我有精神病，我知道我的病吃藥可以改善，但我就是不想吃那麼多藥。」這是屬於何種病識感？","options":["無病識感（no insight）","理智性病識感（intellectual insight）","部分病識感（partial insight）","情感性病識感（true emotional insight）"],"answer":"B","correction":"","chapter":"B","extension":false,"context":null,"id":"113-2-6","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":7,"stem":"有關家庭治療，下列敘述何者最適切？","options":["家庭的次系統是屬於家庭的外在結構","家庭治療需集合全體家人才能進行治療","家庭治療主要強調全家的病態溝通","家庭是動態的系統，家庭問題可以世代間傳遞"],"answer":"D","correction":"","chapter":"F","extension":false,"context":null,"id":"113-2-7","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":8,"stem":"趙女士，在病房內出現未滿足其需求時，便威脅要撞牆。下列護理措施何者最適宜？","options":["配合病人要求以減少傷害","提供病人界限清楚的環境設限","忽視病人撞牆行為","限制病人行動"],"answer":"B","correction":"","chapter":"G","extension":false,"context":null,"id":"113-2-8","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":9,"stem":"提供躁症發作（manicepisode）病人的住院環境，下列考量何者較為適宜？①環境簡化，壁飾窗簾都應避免 ②家具擺放避免病人跌撞或暴力破壞 ③提供能消耗體力的活動與設施 ④病房伙食準備高熱量簡便食物","options":["①②③","②③④","①③④","①②④"],"answer":"B","correction":"","chapter":"F","extension":false,"context":null,"id":"113-2-9","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":10,"stem":"楊小姐，診斷為思覺失調症，住院後在病床存有大量零食。下列護理措施何者最適切？","options":["趁病人不注意時，快速把零食收至護理站","鼓勵病人把零食分送給其他病友","與病人會談以理解存放零食的原因","暫停醫院伙食，待零食食用完畢再訂餐"],"answer":"C","correction":"","chapter":"H","extension":false,"context":null,"id":"113-2-10","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":11,"stem":"李小姐為躁症發作病人，大夜班護理師查房時發現李小姐跟男病友一起躺在床上，下列護理措施何者較適宜？①觀察兩人的性互動行為程度 ②將兩人分開持續密切觀察 ③鼓勵學習適切的異性互動 ④將李小姐持續隔離，防範接觸異性","options":["①②③","②③④","①③④","①②④"],"answer":"A","correction":"","chapter":"I","extension":false,"context":null,"id":"113-2-11","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":12,"stem":"根據 DSM-5 診斷準則，有關第一型雙相情緒障礙症（bipolar disorder）之鬱症（major depressive episode） 症狀，不包括下列何項？","options":["幾乎每天都感到悲傷、哭泣","偶而睡眠差無精打采","一個月內體重明顯增加或減少超過 5%","社交、職業或其他重要功能減損"],"answer":"B","correction":"","chapter":"I","extension":false,"context":null,"id":"113-2-12","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":13,"stem":"有關思覺失調症的致病原因，下列敘述何者最不適切？","options":["多巴胺（dopamine）受體濃度過低","額葉功能缺損","父母具高度情緒表達","父母採雙重束縛型的溝通"],"answer":"A","correction":"","chapter":"C","extension":false,"context":null,"id":"113-2-13","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":14,"stem":"下列何者最可能為海洛因急性中毒的症狀？","options":["講話滔滔不絕","呼吸抑制、昏迷","注意力集中","活動量變大"],"answer":"B","correction":"","chapter":"M","extension":false,"context":null,"id":"113-2-14","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":15,"stem":"有關心理防衛機轉，下列敘述何者正確？","options":["有意識的壓抑自己不應該有的情緒和衝動，是潛抑作用（repression）","藉由建設性的行為，來滿足不被社會所接受的慾望，且對社會有利，是昇華作用（sublimation）","面對痛苦情緒時，可藉由內射作用（introjection）移轉給他人","合理化作用（rationalization）可將原始的慾望，轉移到潛意識層面而無法覺知"],"answer":"B","correction":"","chapter":"C","extension":false,"context":null,"id":"113-2-15","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":16,"stem":"蕭小姐，46 歲，育有二子，因先生外遇，最近離婚後獨居，整日鬱鬱寡歡沉默不語，近日突出現語言障礙， 發聲困難及奇異步態，影響日常作息，住院後神經學檢查無異常，下列護理措施何者最適切？","options":["簡單環境介紹，不須過度詳細說明，以免增加蕭小姐負擔","協助蕭小姐改善身體不適、促進舒適，與其建立信任感為首要護理措施","首先應立即依據神經學檢查報告予以面質蕭小姐，促進面對問題進行心理治療","宜暗示檢查結果並不是百分之百正確，建議蕭小姐宜有更進一步檢查"],"answer":"B","correction":"","chapter":"K","extension":false,"context":null,"id":"113-2-16","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":17,"stem":"林小姐，為重大火車出軌事件的倖存者，診斷為創傷後壓力症（posttraumatic stress disorder），下列敘述何者最不適切？","options":["症狀需持續六個月以上","會對出軌意外的原因或結果歸咎自己","不斷出現火車出軌的畫面","可能會出現口語或肢體攻擊性行為"],"answer":"A","correction":"","chapter":"J","extension":false,"context":null,"id":"113-2-17","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":18,"stem":"有關物質使用障礙症病人的護理措施，下列敘述何者不適切？","options":["個案出現妄想時，應增加個案的現實感","個案出現操縱或暴力行為時，予以適當受限","個案使用否認心理防衛機轉時，應協助處理內心衝突","採取批判性態度，譴責其物質使用行為"],"answer":"D","correction":"","chapter":"M","extension":false,"context":null,"id":"113-2-18","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":19,"stem":"有關行為治療應用的情境，下列何者最適切？","options":["思覺失調症的急性正性症狀","住院病人破壞病房安寧的行為","探討早期成長經驗對家庭婚姻問題的影響","探討創傷的失落與挫折因素"],"answer":"B","correction":"","chapter":"F","extension":false,"context":null,"id":"113-2-19","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":20,"stem":"林小弟，7 歲，診斷為自閉症類群障礙症（autismspectrumdisorder），近期在校出現暴力攻擊行為而入院接受治療，下列敘述何者正確？","options":["抗精神病藥物如 Haloperidol 副作用多，可能影響林小弟發育，因此臨床上不建議使用","可運用消弱法等技巧，改善林小弟不當行為","為避免林小弟傷害他人，給予長時間隔離","藥物使用 1 個月後症狀未改善，可再增加劑量持續使用 1 個月"],"answer":"B","correction":"","chapter":"O","extension":false,"context":null,"id":"113-2-20","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":21,"stem":"有關老年憂鬱症的治療，下列敘述何者最不適切？","options":["目前第一線藥物為三環抗憂鬱劑","從最小的有效劑量開始調整起","電痙攣治療（ECT）可治療嚴重的老年憂鬱症","要注意抗憂鬱劑停藥後焦慮、失眠等副作用"],"answer":"A","correction":"","chapter":"E","extension":false,"context":null,"id":"113-2-21","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":22,"stem":"有關精神衛生護理社區護理實務能力，下列敘述何者正確？","options":["協助病人建構自我與賦能，主要是指護理人員應能自我覺察","疾病管理照護，主要是讓病人住院治療藉以控制症狀","日常生活之自我管理，主要是協助病人確立、解決生活問題，增強自我管理策略","工作與就業輔導，主要是指護理人員應全力聚焦在協助病人找工作"],"answer":"C","correction":"","chapter":"P","extension":false,"context":null,"id":"113-2-22","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":23,"stem":"錢先生，36 歲，罹病 10 年，由父母照顧提供其生活所需。日常與家人相處時多言語衝突，指責父母。案父與病人多各說各話，案父尋求居家護理師協助。此情境下，精神科居家護理師最優先的照護目標為何？","options":["促進案家互動式溝通","改善案家家庭經濟","進行身體健康評估","教導病人壓力因應"],"answer":"A","correction":"","chapter":"F","extension":false,"context":null,"id":"113-2-23","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":24,"stem":"有關暴力行為之導因，下列敘述何者正確？","options":["研究結果發現血清素（serotonin）增加、多巴胺減少，可能會增強暴力衝動或行為","腦器質性病變，較不容易發生暴力行為","對於電視經常報導打鬥、搶劫等暴力行為，不會對個人產生影響","在幼年期常受父母忽視或虐待，可能導致孩子暴力傾向"],"answer":"D","correction":"","chapter":"G","extension":false,"context":null,"id":"113-2-24","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":2,"num":25,"stem":"有關災難防治觀點，下列敘述何者最不適切？","options":["災難無法避免，僅需強調災難後的處置","重建需針對災害型態進行改良工作","強調災難不可預測性及影響","需進行修補性與關懷性的災難防制工作"],"answer":"A","correction":"","chapter":"G","extension":false,"context":null,"id":"113-2-25","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113100"},{"year":113,"nth":3,"num":1,"stem":"有關治療性關係之特性，下列敘述何者正確？","options":["鼓勵護理師進行深度自我開放","治療性關係之各期不連續且不重疊","關係的維持具有彈性，無需設定明確目標","學習建立新行為是工作期常見主題"],"answer":"D","correction":"","chapter":"D","extension":false,"context":null,"id":"113-3-1","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":2,"stem":"在執行精神病人保護約束時，護理人員告知每 15 分鐘會來探視病人，並確實按時探視，此符合下列那項倫理原則？","options":["知情同意","行善","守信","自主"],"answer":"C","correction":"","chapter":"A","extension":false,"context":null,"id":"113-3-2","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":3,"stem":"王先生罹患慢性思覺失調症，精神症狀穩定，但局部功能退化，具有復健潛能，需積極復健治療，下列安排何者最適合？","options":["日間住院治療","慢性住院治療","護理之家療養","急性住院治療"],"answer":"A","correction":"","chapter":"P","extension":false,"context":null,"id":"113-3-3","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":4,"stem":"有關鋰鹽 Lithium（Lidin®）的敘述，下列何者最正確？","options":["主要是促進躁症病人腦部兒茶酚胺（catecholamine）的分泌及活化","口服用藥只需服用大約 2 天，療效通常就非常明顯與穩定","需要嚴格限制食鹽攝取量，以免鋰鹽在腎臟的清除率過高","服用一天後若出現腸胃症狀，例如噁心、嘔吐，建議可進餐時服用鋰鹽"],"answer":"D","correction":"","chapter":"E","extension":false,"context":null,"id":"113-3-4","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":5,"stem":"王先生，20 歲，診斷妥瑞氏症，護理師問他：「你今年幾歲？」王先生答：「幾歲？」接著問：「現在做什麼工作？」王先生答：「什麼工作？」這是屬於下列那一種症狀？","options":["音韻連結（clang association）","回音性言語（echolalia）","言語貧乏（poverty of speech）","言語持續（perseveration）"],"answer":"B","correction":"","chapter":"C","extension":false,"context":null,"id":"113-3-5","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":6,"stem":"有關認知行為治療的特徵，下列敘述何者最適切？","options":["運用心理分析以解決問題","運用精神動力以解決問題","運用人際互動關係以解決問題","運用學習理論以解決問題"],"answer":"D","correction":"","chapter":"F","extension":false,"context":null,"id":"113-3-6","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":7,"stem":"團體治療中，成員 A 抱怨女兒天天工作忙常見不到人，表示自己辛苦撫養小孩很不值得。成員 B 表示自己女兒也很忙，建議父母要學習自己照顧自己，以上的團體互動最符合何項團體療效因素？","options":["存在因素","原生家庭經驗再現","發展社交技巧","利他性"],"answer":"A","correction":"","chapter":"F","extension":false,"context":null,"id":"113-3-7","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":8,"stem":"高小姐罹患「雙相情緒障礙症」，因情緒高昂，整天在家裡不停翻箱倒櫃忙進忙出，表示自己是神力女超人，不需進食，晚上不睡覺一直打電話給警局要一起去拯救世界，故家人帶她入院治療，下列高小姐護理問題何者適切？①營養攝取不足 ②現存性自我傷害 ③睡眠型態紊亂 ④恐懼","options":["①②","①③","②④","③④"],"answer":"B","correction":"","chapter":"B","extension":false,"context":null,"id":"113-3-8","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":9,"stem":"有關思覺失調症（schizophrenia）的敘述，下列何者最適切？","options":["思考、知覺及行為障礙的疾病","常有記憶力減退，無法照顧自己","很少會有幻覺干擾","在疾病前趨期以正性精神症狀為主"],"answer":"A","correction":"","chapter":"H","extension":false,"context":null,"id":"113-3-9","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":10,"stem":"陳小華，20 歲診斷為思覺失調症，在高中二年級即出現幻聽，常覺得別人在議論他，大家都知道他在想什麼，拒絕與人接觸，不願意上學，自我照顧變差。下列何者屬於正性精神症狀？","options":["拒絕與人接觸","不願意上學","持續出現幻聽","自我照顧變差"],"answer":"C","correction":"","chapter":"H","extension":false,"context":null,"id":"113-3-10","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":11,"stem":"有關妄想症狀的護理措施，下列敘述何者最適切？","options":["以建立治療性關係為首要目標","和病人辯論妄想內容的正確性","藥物治療以鎮靜安眠藥物為主","要儘早面質及修正妄想的內容"],"answer":"A","correction":"","chapter":"H","extension":false,"context":null,"id":"113-3-11","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":12,"stem":"陳先生，因鬱症發作，情緒低落，有自殺行為而住院，每日皆會哭泣。有關家屬的照護，下列何項最適宜？","options":["協助家屬瞭解病人目前的狀況","勸導家屬暫停探望病人","給家屬保證，治療後就不會再發病","建議家屬避免與其他親友互動"],"answer":"A","correction":"","chapter":"I","extension":false,"context":null,"id":"113-3-12","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":13,"stem":"有關疾病與核心症狀配對的描述，下列何者最適切？","options":["社交焦慮症：病人會迴避開放的空間，因而導致外出受限","創傷後壓力症：病人會出現「回憶重現（flashback）」的症狀","特定畏懼症：病人會對許多事物有過多的焦慮與擔憂","廣泛性焦慮症：病人會出現重複的行為或心智活動"],"answer":"B","correction":"","chapter":"C","extension":false,"context":null,"id":"113-3-13","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":14,"stem":"王女士，遭遇嚴重土石流而家園全毀，倖存後診斷為創傷後壓力症（posttraumatic stress disorder），下列敘述何者最不適切？","options":["應等待病人做好心理準備才進行危機處理，預後較佳","對人有疏離或與他人疏離，無法感到幸福與被愛","無法記得創傷事件的一個重要情節","可能會有恐懼、驚恐、憤怒、罪惡感和羞愧"],"answer":"A","correction":"","chapter":"J","extension":false,"context":null,"id":"113-3-14","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":15,"stem":"畏避型人格障礙症（avoidant personality disorder）臨床特徵的敘述，下列何者最適切？","options":["害怕被批評或被拒絕，避免涉及人際接觸的工作場合","害怕失去支持或認可，會努力去討好順從他人","利用自己身體外觀來吸引他人注意","需要過度的讚美，並認為自己有特權"],"answer":"A","correction":"","chapter":"N","extension":false,"context":null,"id":"113-3-15","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":16,"stem":"有關身體症狀障礙症（somatic symptom disorder）的敘述，下列何者較不適切？","options":["與人格特質有關，但與生活壓力無關","藉此引起周遭他人的注意","藉此獲得親朋好友的支持與同情","以身體症狀掩飾情緒困擾"],"answer":"A","correction":"","chapter":"K","extension":false,"context":null,"id":"113-3-16","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":17,"stem":"林同學高中生，近半年常在週末深夜 3～4 點回家，功課一落千丈，精神顯得恍惚、視覺模糊、協調性變差、心跳過速、血壓升高，近來常常夜尿頻繁而求診泌尿科，診斷為物質濫用導致的間質性膀胱炎。林同學最有可能使用下列那種毒品？","options":["安非他命","Ｋ他命","大麻","flunitrazepam（俗名 FM2）"],"answer":"B","correction":"","chapter":"M","extension":false,"context":null,"id":"113-3-17","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":18,"stem":"有關自閉症類群障礙症（autism spectrum disorder）的描述，下列何者正確？","options":["會因為要獲得情緒喜悅而與同伴交往","對一成不變的生活常規顯得不耐煩","可能會出現刻板或重複的動作","語言溝通方面，通常沒有問題"],"answer":"C","correction":"","chapter":"O","extension":false,"context":null,"id":"113-3-18","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":19,"stem":"有關社區精神心理衛生的護理過程，下列敘述何者最適切？","options":["重視社區成員的整體心理健康","服務進行方式為一對一的個人關係","主要服務的焦點要能協助解決社區家屬的需要","病人的家庭有經濟問題時，通常不用評估"],"answer":"A","correction":"","chapter":"P","extension":false,"context":null,"id":"113-3-19","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":20,"stem":"洪小弟，6 歲，一年多來出現不自主的眨眼睛、裝鬼臉或聳肩膀，會發出「哼、哼、哼」的聲音。洪小弟的狀況最可能是下列那個問題？","options":["注意力不足／過動症（ADHD）","行為規範障礙症（Conduct Disorder）","智能不足（Intellectual Disability）","妥瑞氏症（Tourette’s Disorder）"],"answer":"D","correction":"","chapter":"O","extension":false,"context":null,"id":"113-3-20","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":21,"stem":"陳女士，診斷為阿茲海默症，經住院治療後準備出院。家屬顯得焦慮，不知道如何照顧陳女士，頻頻詢問其他病友家屬的照護意見。下列護理措施何者最適切？","options":["強調陳女士自我照顧能力足夠，請家屬不必焦慮","避免太多家屬參與照顧，以免產生衝突","傾聽家屬的感受，介紹社會照顧資源","告知家屬每個病人情況不同，不需聽取他人的意見"],"answer":"C","correction":"","chapter":"L","extension":false,"context":null,"id":"113-3-21","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":22,"stem":"下列對於社區精神心理衛生服務系統的敘述何者正確？","options":["注重病人持續性、一致性的照顧","社區精神心理衛生服務的多元服務機構，只強調精神病人的治療需要","社區精神心理衛生服務無法提供即時的住院安排，強調留在家中持續治療","由於社區精神衛生只是公衛護理師的眾多業務之一，因此並不需要進行持續精神衛生教育"],"answer":"A","correction":"","chapter":"P","extension":false,"context":null,"id":"113-3-22","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":23,"stem":"對居住於精神護理之家的失智症住民照護原則，下列何者正確？①維持病房生活作息的常規化 ②儘可能維持住民的最大生活功能 ③安排其與同輩進行團體活動 ④經常改變病房佈置以強化定向感訓練 ⑤ 安排每天由不同人員照顧，以強化記憶功能","options":["①②③","①④⑤","②③④","③④⑤"],"answer":"A","correction":"","chapter":"L","extension":false,"context":null,"id":"113-3-23","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":24,"stem":"王先生診斷為思覺失調症，在精神科慢性病房接受治療，護理人員運用治療性環境促進病人的社交技巧， 下列何項錯誤？","options":["協助病人熟悉環境，包括工作人員、病友、生活作息及環境設施","協助安排參與各種促進人際互動的活動","鼓勵病人從事團體活動，幫助他們建立自信心與成就感","安排病人參與競爭性活動"],"answer":"D","correction":"","chapter":"F","extension":false,"context":null,"id":"113-3-24","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":25,"stem":"以心理健康促進三級預防概念，屬初級預防敘述下列何者正確？①於社區進行心理衛生問題評估篩檢 ② 提供張老師資源，以增加個人調適能力 ③舉辦健康講座，促進心理健康 ④輔導職能復健，增進其功能","options":["①②③","①③④","②③④","①②④"],"answer":"A","correction":"","chapter":"P","extension":false,"context":null,"id":"113-3-25","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":113,"nth":3,"num":50,"stem":"世界衛生組織提出延緩失能的六大能力，有關「長者整合性照護指引（Integrated care for older people, ICOPE）」之評估項目，下列何者最適當？","options":["行動、認知、感官、藥物、營養及憂鬱","行動、認知、視力、聽力、營養及憂鬱","行動、認知、失禁、營養、憂鬱及日常生活活動","行動、認知、營養、藥物、憂鬱及日常生活活動"],"answer":"B","correction":"","chapter":"L","extension":false,"context":null,"id":"113-3-50","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2024&e=113180"},{"year":114,"nth":1,"num":1,"stem":"林小姐常責怪自己，認為凡事過錯都是自己造成的。下列何項心理防衛機轉最適合說明林小姐的行為？","options":["合理化（rationalization）","潛抑（repression）","內射（introjection）","退化（regression）"],"answer":"C","correction":"","chapter":"C","extension":false,"context":null,"id":"114-1-1","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":2,"stem":"精神醫學史上，主張不以鐵鍊限制病人行動，奠定人道主義精神照護的代表性人物，下列何者正確？","options":["克雷佩林（Emil Kraepelin）","畢乃爾（Phillipe Pinel）","佛洛伊德（Sigmund Freud）","瓊斯（Maxwell Jones）"],"answer":"B","correction":"","chapter":"A","extension":false,"context":null,"id":"114-1-2","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":3,"stem":"根據DSM-5診斷準則，有關精神疾病的診斷及臨床表徵，下列敘述何者正確？","options":["妄想症（delusional disorder）病人經常會出現明顯奇特怪異的行為","重鬱症（major depressive disorder）病人最常出現思緒飛躍的症狀","思覺失調症（schizophrenia）病人最常出現罪惡妄想的症狀","強迫症（obessive-compulsive disorder）病人會出現強迫思考、強迫行為的症狀"],"answer":"D","correction":"","chapter":"C","extension":false,"context":null,"id":"114-1-3","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":4,"stem":"有關抗精神病藥物的敘述，下列何者正確？","options":["躁症急性發作期，若已使用情緒穩定劑，則不建議併用抗精神病藥物","clozapine（Clozaril®）和fluvoxamine（Luvox®）產生交互作用，會誘發非預期癲癇痙攣","長效針劑risperidone（Risperdal Consta®）本質水性，多採淺層肌肉注射","鋰鹽為治療譫妄症的首選藥物"],"answer":"B","correction":"","chapter":"E","extension":false,"context":null,"id":"114-1-4","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":5,"stem":"護理師詢問病人「您幾歲？」，病人回答「38歲」，再繼續問病人「之前的工作服務多久？」，病人仍回答「38歲」，病人對之後的問題皆回答「38歲」。此現象屬於下列何種症狀？","options":["音韻連結（clang association）","言語持續（perseveration）","重複言語（verbigeration）","回音性言語（echolalia）"],"answer":"B","correction":"","chapter":"C","extension":false,"context":null,"id":"114-1-5","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":6,"stem":"有關「以整個事件中的單一細節下結論，而沒有考慮整個事件中還有其他相關的訊息」，是屬於下列何項「負向認知思考模式」？","options":["二極化的思考","完美主義","選擇性的偏差推論","武斷推論"],"answer":"C","correction":"","chapter":"F","extension":false,"context":null,"id":"114-1-6","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":7,"stem":"下列何者不是動機式晤談法（motivational interview）的基本原則？","options":["創造不一致的想法","應用夢的解析分析問題","支持自我效能感","避免發生爭辯"],"answer":"B","correction":"","chapter":"F","extension":false,"context":null,"id":"114-1-7","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":8,"stem":"有關代幣制度的敘述，下列何項不適宜？","options":["是行為治療中的一項技術","最適合在病人精神症狀混亂時使用","以具有交換價值的象徵物代替金錢","屬於操作制約作用的學習原理"],"answer":"B","correction":"","chapter":"F","extension":false,"context":null,"id":"114-1-8","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":9,"stem":"胡先生，診斷為思覺失調症，因不停將家中東西丟到大街上，哥哥予以制止，胡先生即要攻擊哥哥。剛入住急性病房治療，下列何者為最優先的護理處置？","options":["確認胡先生身邊環境與物品的安全性，進行暴力行為之評估與預防發生","直接先至保護室並給予預防性約束，以免發生自傷傷人行為","警告胡先生在醫院裡面不容許有攻擊行為發生，否則就無法出院","為表達護理師的關懷與建立信任，可先單獨與病人會談了解他為何要攻擊哥哥"],"answer":"A","correction":"","chapter":"G","extension":false,"context":null,"id":"114-1-9","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":10,"stem":"根據DSM-5診斷準則，有關情感思覺失調症（schizoaffective disorder）的敘述，下列何者正確？","options":["臨床症狀以情感障礙為主","在無情緒障礙症發作時，有二週以上的妄想或幻覺","思考障礙和情緒障礙不會同時發作","不會出現妄想、幻覺"],"answer":"B","correction":"","chapter":"H","extension":false,"context":null,"id":"114-1-10","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":11,"stem":"宋小姐因情緒低落且有自殺行為，入院治療已兩週，常一個人臥床獨處，少與其他病友互動。下列何項護理措施最適宜？","options":["配合病人低落心情，環境宜減少光線刺激","提供安靜的單人房，減少打擾病人","播放低沉的音樂，避免刺激病人","設計簡單的活動，增加病人活動"],"answer":"D","correction":"","chapter":"I","extension":false,"context":null,"id":"114-1-11","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":12,"stem":"陳同學19歲，出現怪異行為，診斷為思覺失調症。因為干擾鄰居被送至精神科急性病房住院。入院時，說自己沒有生病，吵著要出院回家。以下何項護理措施最適切？","options":["請他保證不再干擾鄰居就可以回家","跟他說必須住滿三個月才可考慮出院","引導他表達自己會住院的過程","跟他說只要配合吃藥就可以出院"],"answer":"C","correction":"","chapter":"H","extension":false,"context":null,"id":"114-1-12","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":13,"stem":"承上題，住院第二天，陳同學表示我的父母一定是假的，否則不會將自己的小孩抓來住院。下列護理師的回答何者最適當？","options":["「你的父母是不得已的」","「你的父母是為你好」","「父母的想法很難瞭解」","「這個想法很困擾你」"],"answer":"D","correction":"","chapter":"D","extension":false,"context":{"num":12,"stem":"陳同學19歲，出現怪異行為，診斷為思覺失調症。因為干擾鄰居被送至精神科急性病房住院。入院時，說自己沒有生病，吵著要出院回家。以下何項護理措施最適切？","chapter":"H"},"id":"114-1-13","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":14,"stem":"林先生總是表現出自己很優越，看不起醫護人員，認為自己是群體中最重要的人，且擁有特權。護理師針對此自戀行為（narcissistic）之應對方式，下列何者最適切？","options":["持續的讚美病人，滿足其自誇的需求","利用幽默，與病人開玩笑，營造輕鬆的氣氛","為維持病人的自尊，接受病人對醫護人員的貶低","了解病人的自誇行為並持續提供包容，但避免過度讚美"],"answer":"D","correction":"","chapter":"N","extension":false,"context":null,"id":"114-1-14","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":15,"stem":"有關創傷後壓力症（posttraumatic stress disorder）的敘述，下列何者最適切？","options":["會出現解離反應，感到創傷事件重演","不包含目擊創傷發生於他人身上的經驗","創傷事件不會產生明顯生理反應","負面情緒不包含易怒或無預兆的發怒"],"answer":"A","correction":"","chapter":"J","extension":false,"context":null,"id":"114-1-15","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":16,"stem":"辛小姐診斷為強迫症，會反覆出現希望妹妹死掉的念頭，且對此感到非常焦慮。所以每當看到妹妹時，就開始在心中默念圓周率的數字以減輕焦慮。下列何項敘述最能說明辛小姐的行為？","options":["以抵消對妹妹的負面想法","以投射的作用逃避念頭","自我肯定，證明自己的數學好","一種解離性的狀態"],"answer":"A","correction":"","chapter":"J","extension":false,"context":null,"id":"114-1-16","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":17,"stem":"有關使用嗎啡之敘述，下列何者正確？","options":["嗎啡能有效止痛且提神","嗎啡使用後會產生欣快感","嗎啡只能口服使用","護理師可自行斟酌使用"],"answer":"B","correction":"","chapter":"M","extension":false,"context":null,"id":"114-1-17","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":18,"stem":"根據DSM-5診斷準則，有關智能不足適應功能的評估，下列何者最不適切？","options":["適應功能評估包含概念、社會以及實務三個領域","個人在獨立與擔當社會責任方面無法達到適齡的發展及文化準則，稱為適應功能缺損","評估個人的閱讀、書寫、問題解決能力以及對陌生情境的判斷力等，是屬實務領域","適應功能缺損會使個人在多重環境中的一項或多項日常活動功能受限"],"answer":"C","correction":"","chapter":"O","extension":false,"context":null,"id":"114-1-18","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":19,"stem":"陳小弟，上課時容易分心、坐不住、喜歡往外跑，不受控制的行為讓老師很困擾。陳小弟最可能出現以下何項問題？","options":["智能不足（intellectural disabilities）","雙相情緒障礙症（bipolar disorder）","妥瑞氏症（Tourette's disorder）","注意力不足／過動症（ADHD）"],"answer":"D","correction":"","chapter":"O","extension":false,"context":null,"id":"114-1-19","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":20,"stem":"有關老年憂鬱症的敘述，下列何者最不適切？","options":["以身體症狀反應情緒","常談論自殺想法","記憶力變差","合併日落症候群"],"answer":"D","correction":"","chapter":"L","extension":false,"context":null,"id":"114-1-20","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":21,"stem":"有關社區精神衛生護理評估的敘述，下列何者正確？","options":["不需了解個案的生活習慣及社交狀態，以免涉及病人私領域","不需評估照顧者對病人疾病的瞭解，以免涉及照顧者私領域","不需評估社區的資源，因與精神衛生護理無關","需評估個案、家屬及社區三方面的狀況，以提供多元的社區照護"],"answer":"D","correction":"","chapter":"P","extension":false,"context":null,"id":"114-1-21","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":22,"stem":"對於安置在精神護理之家的病人，下列服務內容何者最適宜？","options":["病人的精神症狀呈現慢性化，宜提供生活的照顧","照顧目標應優先讓病人能返回家庭","病人的精神症狀屬活躍期，宜嚴格監控行動","需積極安排病人就業規劃"],"answer":"A","correction":"","chapter":"P","extension":false,"context":null,"id":"114-1-22","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":23,"stem":"楊太太擔心自己罹患大腸癌，經多次檢查皆正常，但她仍深信自己不久人世，變得無食慾、失眠， 有輕生念頭。下列何項為最優先的護理措施？","options":["教導紓解壓力的方法","再做詳盡健康檢查，降低憂鬱","評估自殺的風險程度","鼓勵寫遺囑，降低焦慮"],"answer":"C","correction":"","chapter":"G","extension":false,"context":null,"id":"114-1-23","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":24,"stem":"有關社區精神衛生護理的角色功能，下列何者最適切？","options":["不提供直接照護服務","個案管理者是唯一的角色功能","發現心理困擾個案是疾病預防者的角色","不須進行研究工作"],"answer":"C","correction":"","chapter":"P","extension":false,"context":null,"id":"114-1-24","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":25,"stem":"有關解除肢體的約束，下列何者最不適宜？","options":["避免提及約束之事，以免激怒病人","瞭解病人在約束中的感受及需要","與其他工作人員共同解除病人的約束","觀察約束部位的膚色狀況"],"answer":"A","correction":"","chapter":"G","extension":false,"context":null,"id":"114-1-25","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":1,"num":44,"stem":"有關校園霸凌之敘述，下列何者最適當？①個人或集體持續以語言、肢體動作或網路等直接對他人故意欺負或戲弄之行為 ②成績優秀者最不容易成為被霸凌的對象 ③長期遭受霸凌者可能出現反擊行為再去霸凌比自己弱勢的人 ④網路霸凌須有重複性，至少要有二次才算","options":["①②③","僅①③","①③④","僅③④"],"answer":"B","correction":"","chapter":"O","extension":false,"context":null,"id":"114-1-44","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114030"},{"year":114,"nth":2,"num":1,"stem":"根據精神衛生法，有關嚴重病人的敘述，下列何者正確？①病人呈現出與事實脫節之精神狀態 ②不能處理自己事務者 ③若被認定為嚴重病人必須強制住院 ④需要專科醫師診斷認定","options":["①②③","②③④","①②④","①③④"],"answer":"C","correction":"","chapter":"A","extension":false,"context":null,"id":"114-2-1","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":2,"stem":"有關治療性人際關係的敘述，下列何者錯誤？","options":["有目的之互動","屬社交性關係","目標的設定以個案為主","有助於建立信任關係"],"answer":"B","correction":"","chapter":"D","extension":false,"context":null,"id":"114-2-2","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":3,"stem":"林太太因為同時面臨工作、婚姻、親子互動等多項挫折，而有憂鬱情緒，護理師的回應下列何者不適當？","options":["你可以跟我訴說你難過時的心情與感受","你的憂鬱情緒一定會很快就好起來的，不用想那麼多","陪伴林太太坐著，不用刻意說些什麼","我了解面對這麼多的問題，讓你感到難受"],"answer":"B","correction":"","chapter":"D","extension":false,"context":null,"id":"114-2-3","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":4,"stem":"長期使用鋰鹽（Lithium）治療雙相情緒障礙症（bipolar disorder），下列何項是必須定期檢查的項目？①甲狀腺功能 ②肺功能 ③肝臟功能 ④腎臟功能","options":["①②","②③","③④","①④"],"answer":"D","correction":"","chapter":"E","extension":false,"context":null,"id":"114-2-4","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":5,"stem":"有關自閉症類群障礙症（autism spectrum disorder）之敘述，下列何者錯誤？","options":["男性發生率高於女性","通常在 3 歲前發病","對主要照顧者有強烈的依戀行為","與同儕缺乏社交互動"],"answer":"C","correction":"","chapter":"O","extension":false,"context":null,"id":"114-2-5","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":6,"stem":"有關思覺失調症病因學，下列敘述何者正確？","options":["思覺失調症的發生與家族病史無關","思覺失調症的發生與高度情緒表達的家庭互動無關","中樞神經傳導物質多巴胺（dopamine）活動量過高是病因之一","腦神經結構與功能呈現腦室縮小及大腦額葉代謝上升"],"answer":"C","correction":"","chapter":"C","extension":false,"context":null,"id":"114-2-6","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":7,"stem":"關於理情治療（rational emotive therapy）的論點，下列敘述何者正確？","options":["消除不良的事件情境","駁斥非理性的信念","建立新的社交技巧行為","修正個人早期創傷經驗"],"answer":"B","correction":"","chapter":"F","extension":false,"context":null,"id":"114-2-7","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":8,"stem":"關於團體療效因子「凝聚力」的敘述，下列何者正確？","options":["感受到彼此的共同點而產生歸屬感","領悟到並非只有自己有特定的心理困擾","模仿其他成員的適應性行為","從其他成員的回饋領悟到自己的行為問題"],"answer":"A","correction":"","chapter":"F","extension":false,"context":null,"id":"114-2-8","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":9,"stem":"有關 Caplan 的危機理論，下列敘述何者最適當？","options":["當個人面對壓力源時，會嘗試使用之前的成功經驗來解決問題","評估危機事件對個人的影響，不需評估個人的情緒反應","個人僅需要使用內部支持來因應危機，解決問題","當個人情緒崩潰時，不需尋求外部支持解決問題"],"answer":"A","correction":"","chapter":"G","extension":false,"context":null,"id":"114-2-9","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":10,"stem":"有關妄想症患者（delusional disorder）之敘述，下列何者最適當？","options":["具有明顯情緒症狀如憂鬱","有明顯的功能受損及怪異行為","具有系統有組織的想法但與事實不符","過度使用內射防衛機轉處理內在衝突"],"answer":"C","correction":"","chapter":"H","extension":false,"context":null,"id":"114-2-10","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":11,"stem":"董先生 44 歲，擔任貿易公司科長，近 2 個月來，出現食慾差、體重下降、失眠，感覺人生沒有希望，有自殺企圖，入院治療。下列護理措施何項最優先？","options":["分析壓力的來源","安排工作治療","提供營養諮詢","預防自我傷害"],"answer":"D","correction":"","chapter":"G","extension":false,"context":null,"id":"114-2-11","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":12,"stem":"宋先生，第一型雙相情緒障礙症（bipolarⅠdisorder）躁症發作（manic episode），住院後常語帶操縱或威脅地命令病友，強占遊戲主導權，引起病友公憤。針對宋先生的操縱行為，下列何項護理措施最適當？","options":["以就事論事的態度給予設限","應以權威式的態度，以免被操縱","為避免衝突，應包容病人的行為","私下協調病友接納病人的行為"],"answer":"A","correction":"","chapter":"I","extension":false,"context":null,"id":"114-2-12","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":13,"stem":"有關思覺失調症正性症狀（positive symptoms）之行為表徵，下列何者正確？","options":["幻覺","情感平淡","思考貧乏","對活動缺乏興趣"],"answer":"A","correction":"","chapter":"H","extension":false,"context":null,"id":"114-2-13","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":14,"stem":"思覺失調症病人陳述：「護理師，我聽到我媽媽在廁所說話，聲音吵死了」。下列護理師的回應何者最適當？","options":["「你說的聲音我也聽到了。」","「你媽媽並沒有在這裡，怎麼會聽到？」","「你亂說，廁所裡沒有任何聲音。」","「聽到這些聲音讓你很困擾。」"],"answer":"D","correction":"","chapter":"D","extension":false,"context":null,"id":"114-2-14","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":15,"stem":"護理師依創傷知情照護（trauma-informed care）的要素與原則，協助病人處理創傷經驗時，下列何者最不適當？","options":["協助病人辨識和處理創傷相關的症狀","理解創傷對病人生活或行為的影響","讓病人努力回憶及描述創傷事件的過程","提供病人安全環境與心理上的安全感"],"answer":"C","correction":"","chapter":"G","extension":false,"context":null,"id":"114-2-15","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":16,"stem":"李同學對於成績表現非常在意，在考試時手能握筆但突然無法寫字，被送來急診，經神經內科檢查手部功能正常，李同學的臨床表徵最符合下列何項診斷？","options":["轉化症（功能性神經症狀障礙症）","罹病焦慮症","身體症狀障礙症","自我感障礙症"],"answer":"A","correction":"","chapter":"K","extension":false,"context":null,"id":"114-2-16","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":17,"stem":"承上題，對於李同學應採取的護理措施，下列何者最適當？","options":["衛教李同學及家長，不必特別處置，數天內症狀就會緩解","持續更縝密的神經學檢查，直到找出神經學病因","讓李同學請病假，不用考試，以移除壓力源","症狀可藉由暗示、建議或藥物催眠會談得到改善"],"answer":"D","correction":"","chapter":"K","extension":false,"context":{"num":16,"stem":"李同學對於成績表現非常在意，在考試時手能握筆但突然無法寫字，被送來急診，經神經內科檢查手部功能正常，李同學的臨床表徵最符合下列何項診斷？","chapter":"K"},"id":"114-2-17","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":18,"stem":"有關物質使用障礙症所指的耐受性（tolerance），下列敘述何者錯誤？","options":["停止使用成癮物質後出現之身心不適","腦部已適應較高的物質濃度，需要更多的物質","需要增加使用量才能達到預期的效果","與使用多種物質的交互作用有關"],"answer":"A","correction":"","chapter":"M","extension":false,"context":null,"id":"114-2-18","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":19,"stem":"有關老年憂鬱症的敘述，下列何者錯誤？","options":["老年憂鬱症通常會有明顯的憂鬱情緒表現","女性老年人較男性老年人發生憂鬱症的比例高","城市老年人較鄉村老年人發生憂鬱症的比例高","慢性病老年人較一般老年人發生憂鬱症比例高"],"answer":"A","correction":"","chapter":"L","extension":false,"context":null,"id":"114-2-19","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":20,"stem":"下列敘述何者為早期失智症的主要症狀表現？","options":["臥床無法行動","日常生活無法自理","認字不能或失語症","出現日落症候群"],"answer":"D","correction":"","chapter":"L","extension":false,"context":null,"id":"114-2-20","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":21,"stem":"有關協助精神病人復元的概念敘述，下列何者錯誤？","options":["找到自信並保持希望","建立保持正向自我感","建立生病的意識，找出生活的意義","理解精神疾病的不可控制及無法處理與克服的障礙"],"answer":"D","correction":"","chapter":"P","extension":false,"context":null,"id":"114-2-21","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":22,"stem":"有關社區心理衛生中心的敘述，下列何者正確？","options":["辦理心理健康促進活動及高危險群病人之危機處理","由長期照顧管理專員協助自我照顧功能","為病人從醫院返家前的暫時安置地點","直接提供病人職業訓練及就業輔導"],"answer":"A","correction":"","chapter":"P","extension":false,"context":null,"id":"114-2-22","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":23,"stem":"美美是 8 年級學生，和同學吵架後，遭到集體圍剿，同學不斷用「婊」、「賤人」叫她，還罵她「當狗也不配」。護理師協助美美進行危機處置時，下列技巧何者不適宜？","options":["宣洩","澄清","再保證","忽略"],"answer":"D","correction":"","chapter":"G","extension":false,"context":null,"id":"114-2-23","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":24,"stem":"朱先生，罹患思覺失調症兩年多，此次因在屋內焚燒報紙，遭鄰居報警後，強制送醫治療。入病室後，突然走到護理站前，目光敵視、肌肉緊繃、用力拍打窗戶及踢護理站的門，大聲吼叫：「我沒有病，我要出去，不然我就砸破玻璃。」下列何者為暴力介入最優先處置？","options":["運用言語的技巧讓病人冷靜","設立清楚的限制與規則","尋求支援人力使用身體處理技巧","治療性的關切和情緒支持"],"answer":"C","correction":"","chapter":"G","extension":false,"context":null,"id":"114-2-24","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":2,"num":25,"stem":"小美與父親在大地震中雙雙遭震垮的房屋壓住，父親當場不幸過世，小美經過急救後，挽回性命，但雙腿截肢。有關災難倖存者在急性期的反應表現，下列何者最不適當？","options":["會有揮之不去的印記","因為親人死亡伴隨著罪惡感","出現無端的憤怒","會接納自己與家人的遭遇"],"answer":"D","correction":"","chapter":"G","extension":false,"context":null,"id":"114-2-25","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114100"},{"year":114,"nth":3,"num":1,"stem":"有關新興影響精神物質（new psychoactive substances, NPS），下列敘述何者最不適當？","options":["常被用在派對中","常以茶包、糖果等形式包裝販賣","都是天然、容易被檢測","藥物混用情形嚴重"],"answer":"C","correction":"","chapter":"M","extension":false,"context":null,"id":"114-3-1","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":2,"stem":"陳先生，24 歲，跟護理師說：「你很像我的女朋友，我們感情很好，你跟她一樣有酒窩，由你來照顧我， 我很高興。」此為下列何項治療性人際關係？","options":["正向情感轉移","負向情感轉移","正向情感反轉移","負向情感反轉移"],"answer":"A","correction":"","chapter":"D","extension":false,"context":null,"id":"114-3-2","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":3,"stem":"依據環境治療原則，在精神科病房公共區域懸掛日曆及時鐘的主要目的，下列何者最適當？","options":["提高對藥物副作用的認識","增加定向感和現實感","增加情感調適能力","提高對自我人格的反思"],"answer":"B","correction":"","chapter":"F","extension":false,"context":null,"id":"114-3-3","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":4,"stem":"張小弟，診斷注意力不足／過動症，幼兒園大班，上課時喜歡走動，多話，無法遵守教室規定和老師提醒， 常跟其他小朋友吵架，下列處置何者最不適當？","options":["協助張小弟認識自己的優點，強化正向行為","運用行為修正方法，教導張小弟學習合宜的社交行為","轉介父母參與親職教養講座和過動兒家長支持團體","安排靜坐於教室角落讓張小弟練習控制自己的衝動"],"answer":"D","correction":"","chapter":"O","extension":false,"context":null,"id":"114-3-4","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":5,"stem":"有關特定場所畏懼症，下列敘述何者最不適當？","options":["病人知道這種害怕是不合理的，而且反應過度","只會對特定對象或情境表現出顯著的恐懼","恐懼或焦慮僅與社交場合有關","病人會出現恐懼或主動逃避這些特定場合"],"answer":"C","correction":"","chapter":"J","extension":false,"context":null,"id":"114-3-5","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":6,"stem":"有關抗焦慮藥戒斷症狀，下列何者正確？","options":["焦慮、失眠、出汗","記憶受損","動作不協調","言語含糊不清"],"answer":"A","correction":"","chapter":"E","extension":false,"context":null,"id":"114-3-6","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":7,"stem":"關於同理心，下列敘述何者最適當？","options":["僅使用口頭語言回應病人","能察覺和體認他人的情緒狀態","強調自己的觀點並給予建議","能滿足對方的所有需求"],"answer":"B","correction":"","chapter":"D","extension":false,"context":null,"id":"114-3-7","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":8,"stem":"李先生的妻女在一次意外事件中相繼過世，有關李先生對此事件的心理調適防衛機轉，下列敘述何者最適當？","options":["談到妻女過世這件事，有意識的抑制失落的情緒，為潛抑作用（repression）","很平淡的描述完整的事件，彷彿這是發生在他人身上的事件，為隔離作用（isolation）","會談時胸前別一朵白色的花，為轉化作用（conversion）","自責當天自己若不讓妻女出門，就不會發生這件意外，為抵消作用（undoing）"],"answer":"B","correction":"","chapter":"C","extension":false,"context":null,"id":"114-3-8","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":9,"stem":"有關創傷後壓力症（posttraumatic stress disorder），下列敘述何者最不適當？","options":["親身目擊事件者可能也是受創者","會出現解離、記憶重現等反應","努力逃避與創傷事件相關的痛苦記憶","不會影響社交、職業或其他重要領域的功能"],"answer":"D","correction":"","chapter":"J","extension":false,"context":null,"id":"114-3-9","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":10,"stem":"有關解離性失憶症（dissociative amnesia）的護理措施，下列何者最適當？","options":["主要目標為將病人缺損的記憶回憶起來","因應日常生活嚴重失能情形","引導病人表達情緒和感受","鼓勵病人將注意力聚焦於身體症狀"],"answer":"C","correction":"","chapter":"K","extension":false,"context":null,"id":"114-3-10","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":11,"stem":"楊小姐，診斷第一型雙相情緒障礙症（bipolar Idisorder），說話滔滔不絕有意念飛躍現象，情緒高亢，易怒不安，吃飯不專心，洗澡洗頭易分心，入睡困難，近日曾與陌生人發生性行為。下列何項是楊小姐之主要健康問題？①自我照顧能力缺失 ②潛在危險性對自我的暴力行為 ③思考過程改變 ④睡眠型態紊亂","options":["①②③","②③④","①③④","①②④"],"answer":"C","correction":"","chapter":"B","extension":false,"context":null,"id":"114-3-11","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":12,"stem":"承上題，對楊小姐所進行之護理措施何者最不適當？","options":["宜安排精細活動磨練耐心與專注力","洗澡洗頭時在旁協助避免被其他事吸引","注意其月經週期","可給予容易攜帶之食物或少量多餐"],"answer":"A","correction":"","chapter":"I","extension":false,"context":{"num":11,"stem":"楊小姐，診斷第一型雙相情緒障礙症（bipolar Idisorder），說話滔滔不絕有意念飛躍現象，情緒高亢，易怒不安，吃飯不專心，洗澡洗頭易分心，入睡困難，近日曾與陌生人發生性行為。下列何項是楊小姐之主要健康問題？①自我照顧能力缺失 ②潛在危險性對自我的暴力行為 ③思考過程改變 ④睡眠型態紊亂","chapter":"B"},"id":"114-3-12","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":13,"stem":"有關抗鬱劑的衛教，下列敘述何者最適當？","options":["服用選擇性血清素再吸收抑制劑，須衛教病人減少水分攝取","服用 fluoxetine（Prozac®）容易產生嗜睡、疲倦副作用，故建議睡前服用","出現激躁、高燒等血清素症候群，須增加抗憂鬱藥物的劑量","服用單胺氧化酶抑制劑，須衛教病人勿食用含酪胺酸（tyramine）食物"],"answer":"D","correction":"","chapter":"E","extension":false,"context":null,"id":"114-3-13","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":14,"stem":"有關憂鬱症，下列敘述何者適當？①甲狀腺功能過高 ②症狀持續至少六個月 ③腦中血清素不足 ④女性發生率大於男性","options":["①②","③④","①③","②④"],"answer":"B","correction":"","chapter":"I","extension":false,"context":null,"id":"114-3-14","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":15,"stem":"小宣，18 歲，家中發生大火，導致房屋全毀，腿部燒傷約 10%，有強烈的焦慮及憂鬱反應，目前首要的災難危機處置目標，下列何者最適當？","options":["安排工作訓練與就業輔導","穩定狀態、減緩症狀","房屋重建","安排休閒娛樂活動"],"answer":"B","correction":"","chapter":"G","extension":false,"context":null,"id":"114-3-15","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":16,"stem":"一位 22 歲女性，常瘋狂地逃避想像被男友拋棄、經常有空虛感、對人際關係極度敏感、情緒不穩定、有過度消費和割腕等自我傷害的衝動行為。這位病人最可能罹患下列何項人格障礙症？","options":["自戀型人格障礙症（narcissistic personality disorder）","做作型人格障礙症（histrionic personality disorder）","反社會型人格障礙症（antisocial personality disorder）","邊緣型人格障礙症（borderline personality disorder）"],"answer":"D","correction":"","chapter":"N","extension":false,"context":null,"id":"114-3-16","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":17,"stem":"有關自殺的概念，下列敘述何者最不適當？","options":["大部分會採取自殺的人，內心通常是充滿矛盾、猶豫不決","多數自殺者會以口頭、書面及行為等方式，表達其自殺意念與企圖","自殺的想法一定會持續存在，並不會消失","曾有自殺企圖者，可能會以更激烈的行動自殺"],"answer":"C","correction":"","chapter":"G","extension":false,"context":null,"id":"114-3-17","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":18,"stem":"有關老年人自殺的特性，下列敘述何者最不適當？","options":["老人的自殺意圖強烈","老人較少尋求精神科的醫療","獨居為老年人自殺的危險因子之一","輕度失智症老人不會有自殺傾向"],"answer":"D","correction":"","chapter":"G","extension":false,"context":null,"id":"114-3-18","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":19,"stem":"躁症病人於住院期間之護理，下列敘述何者最適當？","options":["安排競爭性活動，以宣洩過多體力","護理師應直接駁斥病人誇大性談話內容","鼓勵病人睡前增加運動量，以促進睡眠品質","飲食的攝取宜選擇高熱量易消化之食物"],"answer":"D","correction":"","chapter":"I","extension":false,"context":null,"id":"114-3-19","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":20,"stem":"躁症病人常到護理站做出過多的要求，例如外出買零食，下列護理措施何者適當？①拖延轉移注意力 ②執行肢體約束 ③給予適當的限制 ④雙方協商給予部分滿足","options":["①②③","①②④","①③④","②③④"],"answer":"C","correction":"","chapter":"I","extension":false,"context":null,"id":"114-3-20","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":21,"stem":"有關家庭暴力，下列敘述何者最適當？","options":["受暴者不會發生在男性","可能發生在任何具有家庭關係者之間","身體虐待不屬於家庭暴力種類","家庭暴力形成原因多為單一因素造成"],"answer":"B","correction":"","chapter":"G","extension":false,"context":null,"id":"114-3-21","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":22,"stem":"有關妄想症（delusional disorder），下列敘述何者最適當？","options":["對人信任感不足較多疑","一定會出現幻覺","常使用內射機轉","生活功能顯著退化減損"],"answer":"A","correction":"","chapter":"H","extension":false,"context":null,"id":"114-3-22","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":23,"stem":"李先生，診斷思覺失調症（schizophrenia），初住院期間頻找女病友聊天，聲稱自己是木星上的王子降落地球，病房中的女病友皆是他的嬪妃。下列何項護理措施最適當？","options":["以面質的方式，提醒病人木星沒有人類","安排男性護理師照顧，以免病人出現情感轉移","傾聽但不與病人爭辯其妄想的真實性","提供現實感，提醒勿犯重婚罪"],"answer":"C","correction":"","chapter":"H","extension":false,"context":null,"id":"114-3-23","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":24,"stem":"張先生為慢性思覺失調症病人，剛住進康復之家，下列何者是張先生最適當的復健目標？","options":["培養在社區獨立生活的技能","減少精神藥物服用劑量","規劃外出工作","提升自主性，可自由不夜宿"],"answer":"A","correction":"","chapter":"P","extension":false,"context":null,"id":"114-3-24","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":25,"stem":"有關日間留院照護，下列敘述何者最適當？","options":["具開放性及自主性，可訓練病人自我管理","病人能自行決定停用抗精神病藥物","不需要學習自我了解及人際互動","不需要處理病人與家人間的衝突"],"answer":"A","correction":"","chapter":"P","extension":false,"context":null,"id":"114-3-25","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":114,"nth":3,"num":47,"stem":"有關失智症個案照護之目標，下列敘述何者最不適當？","options":["維持個案最佳的生活狀態","提供安全的生活環境","提供多元且多變化的照護環境與模式","提供有尊嚴的生活"],"answer":"C","correction":"","chapter":"L","extension":false,"context":null,"id":"114-3-47","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2025&e=114170"},{"year":115,"nth":1,"num":1,"stem":"吳小姐，24歲，碩士生，單親家庭，因應疫情返家遠距學習，在家期間與母親朝夕相處備感壓力。 返診時對護理師說:「我坐在房間窗邊會想，如果跳下去會怎樣？」，根據同理心的原則，下列何項護理師的回應最適切？","options":["「請問你住幾樓？」","「你有不想再活下去的念頭嗎？」","「你還很年輕，人生才要開始。」","「等疫情降級跟媽媽分開來住，這種情況就會改善。」"],"answer":"B","correction":"","chapter":"D","extension":false,"context":null,"id":"115-1-1","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":2,"stem":"向精神病人和家屬說明電痙攣療法對憂鬱症的療效和治療過程，讓他們可以充分了解後再決定簽署同意書，此時醫療人員是秉持下列那一項倫理原則？","options":["自主原則","不傷害原則","誠實原則","公平原則"],"answer":"A","correction":"","chapter":"A","extension":false,"context":null,"id":"115-1-2","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":3,"stem":"黃小姐，診斷為思覺失調症，擔心一星期後即將出院返家。下列何項護理措施最適切？","options":["加強黃小姐服用情緒穩定劑的劑量","要黃小姐安心等待出院","陪伴安撫黃小姐不安的情緒","建議延後黃小姐出院日期"],"answer":"C","correction":"","chapter":"P","extension":false,"context":null,"id":"115-1-3","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":4,"stem":"病人是20歲大學重考生，從小備受呵護寵愛長大，個性內向順從，成績中等。指考失利後，出現心情低落、胃口差、失眠等症狀，醫師診斷為鬱症，住院治療 2 週後，父母認為病人需要重回補習班接受鞭策，因此辦理自動出院，病人出院後出現自殺企圖。下列敘述何者最適宜？","options":["大學考試失敗是生病的潛在因素（predisposing factor）","從小個性內向順從是生病的促發因素（precipitating factor）","父母的照護能力是生病的續存因素（perpetuating factor）","成長過程受寵愛呵護是生病的促發因素（precipitating factor）"],"answer":"C","correction":"","chapter":"C","extension":false,"context":null,"id":"115-1-4","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":5,"stem":"有關老人憂鬱症的敘述，下列何者錯誤？","options":["是老年人口中罕見的疾病","自殺是憂鬱症最具潛在性致命因素","會抱怨認知障礙","常訴說身體症狀而忽略情緒症狀"],"answer":"A","correction":"","chapter":"L","extension":false,"context":null,"id":"115-1-5","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":6,"stem":"有關第一代抗精神病藥物之敘述，下列何者正確？","options":["主要作用機轉是來自於多巴胺受體的促進作用","抗精神病作用越強的藥物，其鎮靜作用較低","抗精神病作用越強的藥物，其錐體外徑副作用越低","相較於haloperidol，chlorpromazine較會靜坐不能"],"answer":"B","correction":"","chapter":"E","extension":false,"context":null,"id":"115-1-6","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":7,"stem":"根據團體治療型態的定義及目標，鼓勵成員在團體中用言語表達，並探討個人現在與過去情境中， 情緒或心理上的問題，以增進成員的人格重建或行為型態之修正與調適。屬於下列何種團體治療？","options":["健康指導團體","會心團體","娛樂治療團體","生物回饋團體"],"answer":"B","correction":"","chapter":"F","extension":false,"context":null,"id":"115-1-7","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":8,"stem":"有關家庭結構評估，下列何者屬於內在結構？","options":["文化","次系統","社經地位","宗教"],"answer":"B","correction":"","chapter":"F","extension":false,"context":null,"id":"115-1-8","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":9,"stem":"有關思覺失調症病因之描述，下列何項正確？①負性症狀主要與多巴胺活動量過高有關 ②父母為高情緒表達且互動僵化 ③其發病與遺傳因素有相關 ④病人的自我（ego）功能異常","options":["①②③","①②④","①③④","②③④"],"answer":"D","correction":"","chapter":"C","extension":false,"context":null,"id":"115-1-9","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":10,"stem":"有關病人保護約束隔離期間的護理措施，下列何者正確？","options":["每30分鐘觀察病人狀況","滿足基本生理需求","不需要醫囑","打開監視器觀察，不須現場探視"],"answer":"B","correction":"","chapter":"G","extension":false,"context":null,"id":"115-1-10","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":11,"stem":"謝先生，診斷為雙相情緒障礙症，因要求外出抽菸未獲同意，在病室內摔東西。下列何項護理措施最適宜？","options":["以嚴厲語氣制止病人","引導病人用言語表達憤怒","立即告知會延後病人出院的日期","直接將病人約束"],"answer":"B","correction":"","chapter":"G","extension":false,"context":null,"id":"115-1-11","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":12,"stem":"有關被害妄想的護理措施，下列何者最適切？","options":["積極與病人互動","頻繁評估其妄想內容","採被動友善方式接近病人","做任何護理技術時不需要額外解釋"],"answer":"C","correction":"","chapter":"H","extension":false,"context":null,"id":"115-1-12","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":13,"stem":"林先生，躁症發作（manic episode）住院，在病房客廳對著病友們滔滔不絕的批判醫護人員、醫院設施，並表示要投訴媒體。下列何項最適宜此時護理處置？","options":["將林先生帶開，陪伴參加病房歌唱活動","轉知被批判的醫護人員，改善對林先生的態度","持續傾聽林先生的抱怨，並給予肯定","提供事實，澄清林先生所批判內容"],"answer":"A","correction":"","chapter":"I","extension":false,"context":null,"id":"115-1-13","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":14,"stem":"吳先生，診斷為思覺失調症，近期被害妄想嚴重，拒絕服藥，因擔心鄰居窺看，將所有窗戶都貼上牛皮紙。下列何項居家護理處置最適切？","options":["通知警察強制送醫","與居家治療團隊討論處置","建議病人搬家","教導鄰居自我安全防護"],"answer":"B","correction":"","chapter":"H","extension":false,"context":null,"id":"115-1-14","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":15,"stem":"恐慌症（panic disorder）的病人在至少一次恐慌發作後，最有可能會出現下列何種情況？","options":["更加減少對自己身體感受的關注程度","試圖忽略對下一次發作的擔憂","時常出現解離症狀，以減少現實情境中的恐慌發作","避免現身不熟悉的情境，以免恐慌發作"],"answer":"D","correction":"","chapter":"J","extension":false,"context":null,"id":"115-1-15","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":16,"stem":"有關人格障礙症的敘述，下列何者最適切？","options":["妄想型人格障礙症病人總是選擇孤單的活動","邊緣型人格障礙症病人常見有不穩定的人際關係及明顯的衝動性","孤僻型人格障礙症病人常見具有強烈的自大，對他人缺乏同理心","依賴型人格障礙症病人常見漠視且侵犯他人權益的行為"],"answer":"B","correction":"","chapter":"N","extension":false,"context":null,"id":"115-1-16","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":17,"stem":"林先生經歷暴雨過後家園遭遇土石流，目睹父親死亡，倖存後被診斷為創傷後壓力症 （posttraumatic stress disorder），每當下起大雨或看到土石流的新聞，林先生最不可能出現下列何種反應？","options":["過度的悲痛與罪惡感","人際疏離，無法感受到快樂","失眠、反覆的噩夢","經常重返事故地點"],"answer":"D","correction":"","chapter":"J","extension":false,"context":null,"id":"115-1-17","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":18,"stem":"有關愷他命（ketamine）的敘述，下列何者錯誤？","options":["在醫學上是用於手術麻醉","容易罹患急性膀胱間質炎","常見中毒症狀是心搏過速、震顫、噁心嘔吐","ketamine屬於第三級毒品"],"answer":"B","correction":"","chapter":"M","extension":false,"context":null,"id":"115-1-18","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":19,"stem":"小華的媽媽抱怨，小華很聰明、人緣好，但就是認字很差，文章表達不清楚。下列何項是小華最可能出現的診斷？","options":["抽搐症","行為規範障礙症","閱讀障礙症","自閉症"],"answer":"C","correction":"","chapter":"O","extension":false,"context":null,"id":"115-1-19","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":20,"stem":"陳女士，70歲，診斷為思覺失調症，因出現明顯精神症狀而入院治療。下列何項入院護理照護最適切？","options":["安排不同的照護人員，以增加對人的定向感","若病人出現暴力行為，直接採取隔離與約束處置","當病人出現妄想時，可協助分散注意力","當病人出現幻覺時，應先協助區別現實與幻覺的不同"],"answer":"C","correction":"","chapter":"L","extension":false,"context":null,"id":"115-1-20","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":21,"stem":"涂先生，41歲，診斷為雙相情緒障礙症，與病友因口角發生攻擊行為，揚言要致其死，經醫囑予約束隔離30分鐘，有關約束隔離的敘述，下列何者正確？","options":["約束的目的主要為保護涂先生，穩定其情緒，而非考量保護另一位病友免於傷害","約束一定會涉及不符倫理的議題，同時也是破壞涂先生與工作人員信任關係的主因","運用隔離措施之三個原則，包括獨居、隔離、減少感覺輸入","因情況危急，通常不需再向涂先生說明太多"],"answer":"C","correction":"","chapter":"G","extension":false,"context":null,"id":"115-1-21","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":22,"stem":"承上題，有關身體約束的相關護理措施，下列敘述何者正確？","options":["依照醫囑執行約束，不需簽署同意書","約束中應觀察四肢之血液循環及臉部膚色、溫度與感覺","為保護病人，不可等到足夠人力，需立即執行約束，以免產生嚴重傷害","在執行約束之後應協助病人補充大量水分"],"answer":"B","correction":"","chapter":"G","extension":false,"context":{"num":21,"stem":"涂先生，41歲，診斷為雙相情緒障礙症，與病友因口角發生攻擊行為，揚言要致其死，經醫囑予約束隔離30分鐘，有關約束隔離的敘述，下列何者正確？","chapter":"G"},"id":"115-1-22","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":23,"stem":"張太太因先生車禍意外過世出現激動不安、捶打家人，遂被帶至急診救治。依據卡普蘭 （Caplan.）危機理論，張太太目前處於危機發展過程的那一期？","options":["衝擊期","崩潰期","求助時期","紊亂期"],"answer":"D","correction":"","chapter":"G","extension":false,"context":null,"id":"115-1-23","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":24,"stem":"提供精神病人出院回歸社區的照護，下列敘述何者最適切？","options":["辦理心理衛生講座，協助病人認識精神疾病","廣設急性精神病房，因應病人急性發病所需","增設社區復健治療，提升病人之社區適應能力","推廣自殺防治，以減少全國自殺死亡率"],"answer":"C","correction":"","chapter":"P","extension":false,"context":null,"id":"115-1-24","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":25,"stem":"有關慢性精神病人的特性與照顧原則，下列說明何者正確？①病人正性症狀較多，且症狀嚴重 ② 醫療照顧應減少機構化之負面影響 ③居住環境應重視安全、舒適和定向感的刺激 ④藉由病人的生活規劃，有助減輕負性症狀","options":["僅①②","僅②③","僅②③④","①②③④"],"answer":"C","correction":"","chapter":"P","extension":false,"context":null,"id":"115-1-25","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":40,"stem":"有關家庭的成長性和情境性危機敘述，下列何者正確？①成長性危機通常是可預測的 ②情境性危機是專指負向事件 ③中頭彩可能造成家庭的情境性危機 ④外派進修屬成長性危機","options":["①②","①③","②③","②④"],"answer":"B","correction":"","chapter":"G","extension":false,"context":null,"id":"115-1-40","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":1,"num":46,"stem":"有關失智社區服務據點的服務項目，下列何者最不適當？","options":["提供極輕度至輕度失智者之認知功能促進活動","提供個案共餐等長照預防服務","提供失智個案申請外籍照顧服務員","提供照顧者支持團體及照顧訓練課程"],"answer":"C","correction":"","chapter":"L","extension":false,"context":null,"id":"115-1-46","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115030"},{"year":115,"nth":2,"num":1,"stem":"林先生，診斷為思覺失調症（schizophrenia），近因被害妄想、情緒激躁，因此住院治療，一週後情緒趨於穩定，林先生詢問何時可以出院，下列護理師告知病人的處理何者最適當？","options":["和醫療團隊討論治療計畫","住院時間太短不適合出院","出院必須由家人同意","建議醫師調高藥物劑量"],"answer":"A","correction":"","chapter":"A","extension":false,"context":null,"id":"115-2-1","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":2,"stem":"有關精神障礙病人在復元過程的敘述，下列何者正確？","options":["是逐漸好轉的線性發展過程","減少承擔日常生活自我照顧責任是助力因素","終生受疾病所苦，無法找到生命意義","是朝向發揮潛力掌握自我生活的歷程"],"answer":"D","correction":"","chapter":"P","extension":false,"context":null,"id":"115-2-2","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":3,"stem":"精神病人擅自離開精神照護機構，行蹤不明時，依據民國 111 年公布之精神衛生法，下列何者處置最適當？","options":["應立即通知病人戶籍地之里長協尋","病人離院後立即通知家屬辦理出院","應立即通知地方主管機關及警察機關協尋","當警察發現病人時，應予以拘留管束"],"answer":"C","correction":"","chapter":"A","extension":false,"context":null,"id":"115-2-3","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":4,"stem":"一位 42 歲女性，診斷憂鬱症，經醫師處方千憂解 duloxetine（Cymbalta®）治療。用藥第 7 天返診時，她抱怨最近常感焦慮、緊張、容易出汗、手抖。下列評估或處置，何者最適當？","options":["評估為藥物耐受性不佳，建議立即改用抗精神病藥物","評估為高血壓危象，需立即停藥並補充酪胺酸的攝取","此為藥物初期常見的中樞神經症狀，應加強衛教與觀察","此藥主要作用在多巴胺 D₂ 接受器，需改為血清素類抗憂鬱藥"],"answer":"C","correction":"","chapter":"E","extension":false,"context":null,"id":"115-2-4","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":5,"stem":"張先生，78 歲，因迷路警察通知家人領回，張先生大聲表示：「我只是想拜訪老王，一時想不起他住那裡， 所以才在附近逛逛。」家人感錯愕，因為 1 個月前才陪爸爸參加王先生的葬禮。下列何項最可能是張先生的診斷？","options":["焦慮症","妄想症","憂鬱症","失智症"],"answer":"D","correction":"","chapter":"L","extension":false,"context":null,"id":"115-2-5","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":6,"stem":"電氣痙攣療法（electroconvulsive therapy, ECT）的臨床適應症，下列選項何者較適當？①人格障礙症 ②對藥物治療無效的躁症 ③嚴重憂鬱症且自殺意念強烈 ④思覺失調症合併僵直症","options":["①②③","①②④","①③④","②③④"],"answer":"D","correction":"","chapter":"E","extension":false,"context":null,"id":"115-2-6","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":7,"stem":"以下治療性團體中的對話，小芬的回應最能顯示何項團體療效因子？ 小明：「我覺得我很失敗，一輩子都沒辦法從這種狀態中走出來。」 小芬：「我之前也有這種感覺，但從團體中，我學會了接受自己的情緒，還重新找回了工作的方向，你要有信心。」","options":["情緒宣洩（catharsis）","存在因子（existential factor）","灌注希望（instillation of hope）","發展社交互動技巧（development of socializing techniques）"],"answer":"C","correction":"","chapter":"F","extension":false,"context":null,"id":"115-2-7","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":8,"stem":"王小姐，診斷思覺失調症，主要症狀為被害妄想、多疑，難以與他人建立信任關係，下列那些符合環境治療的原則？①採取主動友善的態度，密集與其互動 ②注意環境並定時安檢，維護其他病人的安全 ③僅在必要時給予簡要的問候，不過度主動關心 ④暫時停止其所有的團體活動，以降低其妄想與多疑","options":["①②","①④","②③","②④"],"answer":"C","correction":"","chapter":"F","extension":false,"context":null,"id":"115-2-8","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":9,"stem":"有關思覺失調症之敘述，何者錯誤？","options":["通常好發年齡為 15～45 歲之間","症狀多以思考和知覺障礙為主","疾病症狀持續至少 6 個月以上","與多巴胺濃度過低有關"],"answer":"D","correction":"","chapter":"H","extension":false,"context":null,"id":"115-2-9","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":10,"stem":"下列有關憂鬱症病因之敘述何者正確？①病人最常使用的防禦機轉為內射 ②病人的本我弱，超我強 ③病人對自我有負向看法，這是屬於認知理論 ④當憂鬱情緒好轉時，自殺的意念就會消失","options":["①②③","①②④","①③④","②③④"],"answer":"A","correction":"","chapter":"C","extension":false,"context":null,"id":"115-2-10","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":11,"stem":"張先生是一位思覺失調症病人，住院期間常摀著耳朵自言自語說：「有人一直在罵我，叫我去死！」護理師發現他因此情緒顯得很焦慮。下列護理師的處置，何者最適當？","options":["嚴肅地告訴張先生：「你聽到的聲音可能是真的。」","建議張先生：「可以戴上耳機聽音樂減少聲音干擾。」","告訴張先生：「只要按時吃藥，你很快就會好起來的！」","平淡地說：「這些都是幻聽，睡飽就好了。」"],"answer":"B","correction":"","chapter":"H","extension":false,"context":null,"id":"115-2-11","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":12,"stem":"有關雙相情緒障礙症的治療，下列何者最適當？","options":["鋰鹽治療血中濃度須達 2.0 mEq/L 以上，才能發揮作用","電氣痙攣療法治療躁症病人，至少每天施行 1 次","抗精神病藥物不會用於急性躁症發作","心理治療有助於病人壓力因應，預防再發作"],"answer":"D","correction":"","chapter":"I","extension":false,"context":null,"id":"115-2-12","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":13,"stem":"小蕙，21 歲，因嚴重幻聽和混亂行為，被診斷思覺失調症。有關影響疾病預後較好的因素，下列何者最適當？","options":["父親有思覺失調症病史","能適應藥物治療且規則服藥","持續有嚴重的認知功能障礙","家屬為高情感表達（high expressed emotion）"],"answer":"B","correction":"","chapter":"H","extension":false,"context":null,"id":"115-2-13","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":14,"stem":"一位 30 歲男性，診斷反社會型人格障礙，因酒駕肇事被強制送醫，住院期間不斷抱怨醫院伙食、環境， 並對醫護人員咆哮，甚至出現言語威脅。下列那項護理措施最為適切？","options":["立即限制其行動自由，避免影響其他病人","同理病人的憤怒情緒，並給予擁抱以示安慰","對病人干擾行為給予設限，及說明對行為的期待","避免與病人有任何眼神接觸，以免激怒病人"],"answer":"C","correction":"","chapter":"N","extension":false,"context":null,"id":"115-2-14","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":15,"stem":"林同學認為門把很髒，於碰觸門把之後要花 30 分鐘洗手，治療者讓林同學有意識的碰觸門把，再幫助林同學漸漸耐受不強迫洗手帶來的焦慮感，而學會控制與因應，為下列何項治療方法？","options":["精神分析治療","人際關係治療","思考中斷法","暴露及反應預防療法"],"answer":"D","correction":"","chapter":"F","extension":false,"context":null,"id":"115-2-15","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":16,"stem":"有關身體症狀障礙症（somatic symptom disorder）的敘述，下列何者最適當？","options":["身體症狀不會造成日常生活顯著困擾","身體症狀持續時間一般不超過 1 個月","對健康或症狀一直高度焦慮","逃避症狀或健康問題，不願就醫"],"answer":"C","correction":"","chapter":"K","extension":false,"context":null,"id":"115-2-16","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":17,"stem":"有關酒精戒斷症狀的陳述，下列何者錯誤？","options":["會出現交感神經興奮的症狀","增加 GABA 的抑制功能為戒斷症狀產生的機轉之一","可能會出現震顫性譫妄（delirium tremens）","戒斷症狀可給予 benzodiazepine（BZD）藥物治療"],"answer":"B","correction":"","chapter":"M","extension":false,"context":null,"id":"115-2-17","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":18,"stem":"有關厭食症（anorexia nervosa）的敘述，下列何者錯誤？","options":["可分為節制型和嗜食／清除型二種亞型","清除行為包含不當使用瀉劑，或者進行自我催吐","身體質量指數（BMI）小於 16 kg/m2仍屬正常範圍","扭曲的身體心像是厭食症的特徵之一"],"answer":"C","correction":"","chapter":"O","extension":true,"context":null,"id":"115-2-18","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":19,"stem":"小新，診斷自閉症類群障礙，從小就喜歡一個人自己玩，不理人，不太喜歡別人碰觸，不看人，有幾次過馬路當媽媽要帶小新快速通過斑馬線時，小新會尖叫，掙開媽媽，如果出門回家走不同路線，小新也會大吵大鬧，去公園遊樂場最喜歡坐在鞦韆上自我旋轉將鞦韆鍊條扭緊再放開。下列敘述何者正確？","options":["避免帶小新出門以改善行為問題","安排感覺統合治療，處理小新感官過度反應的行為問題","疾病主要是嬰兒時期依附關係發展障礙所致","當他情緒不受控制時，立即把他抱緊，直到安靜為止"],"answer":"B","correction":"","chapter":"O","extension":false,"context":null,"id":"115-2-19","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":20,"stem":"有關自閉症類群障礙症（autism spectrum disorder, ASD）敘述，下列何者最不適當？","options":["症狀通常要到學齡期後才會出現","宜儘早訓練個案語言溝通能力","症狀會引起社交、職業等功能缺損","行為治療可培養適當的生活習慣"],"answer":"A","correction":"","chapter":"O","extension":false,"context":null,"id":"115-2-20","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":21,"stem":"李先生，45 歲，獨居，目前住院已滿 2 個月，曾有干擾家庭與社區的問題，家屬表示無法督促就醫，出院準備服務的評估發現能自我照顧但無病識感，無工作動機，出院後就不想吃藥，不會主動就醫。下列何項是出院準備服務轉介的首選？","options":["精神護理之家","庇護性工作坊","居家治療","社區復健中心"],"answer":"一律給分","correction":"第21題一律給分。","chapter":"P","extension":false,"context":null,"id":"115-2-21","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":22,"stem":"有關社區精神病人個案管理原則的敘述，下列何者正確？","options":["因為家屬無病識感，不需與家屬建立治療結盟關係","社區服務資源多元，協助個案進行資源連結","個案拒絕家訪，則改為持續電訪服務即可","日常生活管理並非社區精神科個案管理的重點"],"answer":"B","correction":"","chapter":"P","extension":false,"context":null,"id":"115-2-22","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":23,"stem":"自殺企圖病人在急性精神科住院時之護理措施，下列何者最不適當？","options":["危險物品（如刮鬍刀、剪刀）均列入保管","避免討論其自殺的原因，以降低自殺的想法","安排時間及早討論出院計畫","必要時可轉介社區相關機構繼續追蹤"],"answer":"B","correction":"","chapter":"G","extension":false,"context":null,"id":"115-2-23","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":24,"stem":"阿明是一名 25 歲思覺失調症病人，因突發被害妄想（被工作人員故意找麻煩）、情緒躁動，突然攻擊工作人員，雖立即遭警衛壓制，但還是造成工作人員全身多處瘀青。暴力事件發生後，下列因應暴力事件的方法，何者最不適當？","options":["病房主管及同事提供支持及理解","提供工作人員關懷、和協助情緒及認知的調適","協助工作人員暫離暴力情境，重建安全感","直接找病人理論"],"answer":"D","correction":"","chapter":"G","extension":false,"context":null,"id":"115-2-24","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":25,"stem":"依據卡普蘭（Caplan）提出的危機理論，當個人開始面對壓力源時，普遍會出現的反應，下列何項最適當？","options":["焦慮","思考功能障礙","社交隔離","情緒崩潰"],"answer":"A","correction":"","chapter":"G","extension":false,"context":null,"id":"115-2-25","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"},{"year":115,"nth":2,"num":48,"stem":"曾先生為失智症個案，可自主活動，主要照顧者為媳婦，曾接受過照顧服務員訓練，照顧個案達 3 年，家人希望由自己人照顧，但媳婦身心疲憊，期待可以休息旅遊；也表示獨自照顧的孤單感受。下列那些服務項目最適合提供給照顧者？①轉介安養機構資訊 ②指導照護技巧 ③喘息服務資訊 ④情緒支持","options":["①③","①④","②③","③④"],"answer":"D","correction":"","chapter":"L","extension":false,"context":null,"id":"115-2-48","source":"https://wwwq.moex.gov.tw/exam/wFrmExamQandASearch.aspx?y=2026&e=115100"}];
